                                        //        + ★정체 미확인 233.8  = 1634.0
                                        //   ★미확인 233.8g 은 모델된 프레임 전체(256.4g)와 맞먹는다. 프레임이 금속이거나
                                        //     STL 에 없는 부품이 있다는 뜻 — 프레임 형상질량에 비례 배분했다(계수 0.9120,
                                        //     프레임 유효밀도 1050 → 2008 kg/m³). 프레임 부품 하나만 저울에 올리면 확정된다.
