                                        //     소용없다 — 같은 틀린 규칙을 좌우에 적용하면 오차가 상쇄돼 일관돼 보인다.
                                        //     joint_map: -1 인 축 = T2,T3,T4,T5,T6,T8,T9,T10,T11,T14,T16 / 나머지 +1
