                                        "$jointrange, T6,  -106.79, 102.92\r\n" +   // 우 힙피치 (구동측정과 5도 이내 일치) (hand_taught)
                                        "$jointrange, T8,  -107.84, 102.92\r\n" +   // 좌 힙피치 (구동측정과 8도 이내 일치) (hand_taught)
                                        //   ※팔꿈치는 수동 학습값(-88.95/-90.26)을 쓰지 않는다. 사람이 "사람 팔꿈치"
