        public Main()
        {
            InitializeComponent();
            InitSceneTab();   // $scene placement UI 동적 생성 (tabRight 에 "Scene" 탭 추가)
            InitSnapTab();    // STL 스냅 UI 동적 생성 (tabRight 에 "Snap" 탭 추가, snap.html 포팅)
