        private void AddSnapSection(TabPage tab, ref int y, string title)
        {
            Label lbl = new Label();
            lbl.Text = title.ToUpper();
            lbl.Location = new Point(5, y); lbl.Size = new Size(245, 14);
            lbl.ForeColor = Color.Gray;
            lbl.Font = new Font("맑은 고딕", 7.5f, FontStyle.Bold);
            tab.Controls.Add(lbl);
            Label sep = new Label();
            sep.Location = new Point(5, y + 14); sep.Size = new Size(245, 1);
            sep.BorderStyle = BorderStyle.Fixed3D;
            tab.Controls.Add(sep);
            y += 19;
        }

        private Button MakeSnapModeButton(string text, Point loc, bool on)
        {
            Button b = new Button();
            b.Text = text; b.Location = loc; b.Size = new Size(50, 26);
            b.FlatStyle = FlatStyle.Flat;
            if (on) { b.BackColor = Color.FromArgb(42, 108, 255); b.ForeColor = Color.White; b.UseVisualStyleBackColor = false; }
            else { b.UseVisualStyleBackColor = true; }
            return b;
        }

        private Button MakeSnapAxisButton(string text, Point loc, Color hintColor, bool on)
        {
            Button b = new Button();
            b.Text = text; b.Location = loc; b.Size = new Size(36, 26);
            b.FlatStyle = FlatStyle.Flat;
            if (on) { b.BackColor = Color.FromArgb(42, 108, 255); b.ForeColor = Color.White; b.UseVisualStyleBackColor = false; }
            else { b.UseVisualStyleBackColor = true; b.ForeColor = hintColor; }
            return b;
        }

        private TextBox AddSnapAxisField(TabPage tab, string axisLabel, int x, int y, Color c)
        {
            Label lbl = new Label();
            lbl.Text = axisLabel; lbl.Location = new Point(x, y + 3);
            lbl.Size = new Size(15, 20); lbl.ForeColor = c;
            lbl.Font = new Font("맑은 고딕", 8.5f, FontStyle.Bold);
            tab.Controls.Add(lbl);
            TextBox txt = new TextBox();
            txt.Location = new Point(x + 17, y); txt.Size = new Size(45, 22);
            // Enter / Leave 시 입력값을 STL 에 즉시 적용 (Modified 가 true 일 때만)
            txt.KeyDown += new KeyEventHandler(OnSnapManualKeyDown);
            txt.Leave += new EventHandler(OnSnapManualLeave);
            tab.Controls.Add(txt);
            return txt;
        }

        private void OnSnapManualKeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                ApplySnapManualIfChanged(sender as TextBox);
                e.SuppressKeyPress = true;
            }
        }

        private void OnSnapManualLeave(object sender, EventArgs e)
        {
            ApplySnapManualIfChanged(sender as TextBox);
        }

        private void ApplySnapManualIfChanged(TextBox txt)
        {
            if (txt == null || !txt.Modified) return;
            txt.Modified = false;
            OnSnapApplyManual(null, EventArgs.Empty);
        }

        // ========================================
        // Snap 탭 핸들러 (Phase 1: 평면 모드만 동작, 나머지는 placeholder)
        // ========================================

        private void OnSnapModePlane(object sender, EventArgs e)
        {
            m_strSnapMode = "plane";
            SetSnapModeButtonState();
            // 평면 스냅 진입 = 기존 btnFaceSnap_Click 동작
            if (!m_bFaceSnapMode) btnFaceSnap_Click(null, EventArgs.Empty);
            // 원 모드에서 전환 시 원 시각화 정리
            m_lstSnapCircles.Clear();
            m_nSnapSrcCircleIdx = -1;
            m_nSnapHovCircleIdx = -1;
            UpdatePreview(null);
            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = "평면 모드 — B 도형 클릭(소스) → A 도형 클릭 → 정렬";
        }

        private void OnSnapModeCircle(object sender, EventArgs e)
        {
            m_strSnapMode = "circle";
            SetSnapModeButtonState();
            // 원 모드 진입 = face snap 모드 ON (raycast/이벤트 활용)
            if (!m_bFaceSnapMode) btnFaceSnap_Click(null, EventArgs.Empty);
            // 모든 STL 의 원 검출 → 캐시
            BuildCircleCache();
            m_nSnapSrcCircleIdx = -1;
            m_nSnapHovCircleIdx = -1;
            UpdatePreview(null);
            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = string.Format(
                    "원 모드: {0}개 원 검출됨\r\nSTL 원 클릭(소스) → 다른 STL 원 클릭 → 정렬",
                    m_lstSnapCircles.Count);
        }

        /// <summary>수동 이동 모드 토글 — STL 위에 X/Y/Z 축 화살표를 그려
        /// 사용자가 축을 클릭한 뒤 드래그하면 그 축 방향으로 STL 이 이동.</summary>
        private void OnManualMoveToggle(object sender, EventArgs e)
        {
            m_bManualMoveMode = !m_bManualMoveMode;
            // 다른 snap 모드와 상호 배타
            if (m_bManualMoveMode)
            {
                if (m_bFaceSnapMode) ExitFaceSnapMode(null);
                m_strSnapMode = "manual";
                // Mouse Interaction 모드 강제 — STL 드래그가 정상 작동하려면 m_eMode 가 Mouse 여야 함.
                // (라디오 버튼이 다른 모드에 있을 수 있으므로 강제로 Mouse 모드로 전환)
                m_eMode = InteractionMode.Mouse;
                m_eCurrentAction = BuildAction.None;
                if (m_C3d != null)
                    m_C3d.SetMouseMode(99);   // 99 = 카메라 비활성 (STL 드래그 전용)
                // 라디오 버튼 시각 동기화
                if (rdModeMouse != null) rdModeMouse.Checked = true;
                // STL 자동 선택 — 히스토리에 STL 이 있으면 마지막 STL 선택
                if (GetSelectedStlStepIndex() < 0)
                {
                    int lastStl = -1;
                    for (int i = m_Builder.StepCount - 1; i >= 0; i--)
                    {
                        if (m_Builder.GetStep(i).Action == BuildAction.Stl) { lastStl = i; break; }
                    }
                    if (lastStl >= 0 && lastStl < lstHistory.Items.Count)
                        lstHistory.SelectedIndex = lastStl;
                }
            }
            else
            {
                m_strSnapMode = "plane";  // 기본값 복귀
            }
            SetSnapModeButtonState();
            UpdatePreview(null);
            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = m_bManualMoveMode
                    ? "수동 이동 ON\r\n히스토리에서 STL 선택 → 축 끝 공 클릭 후 드래그"
                    : "수동 이동 OFF";
        }

        /// <summary>모든 STL 의 원 검출하여 world 좌표로 캐시.</summary>
        private void BuildCircleCache()
        {
            m_lstSnapCircles.Clear();
            for (int si = 0; si < m_Builder.StepCount; si++)
            {
                DhStep step = m_Builder.GetStep(si);
                if (step.Action != BuildAction.Stl) continue;
                string fn = step.DhLines.TrimStart('@').Replace("[", "").Replace("]", "").Split(',')[0].Trim();
                string stlPath = Path.Combine(Application.StartupPath, "stl", fn);
                StlBoundingBox bbox;
                try { bbox = StlParser.Parse(stlPath); } catch { continue; }
                if (!bbox.IsValid) continue;
                List<StlParser.CircleFit> circles = StlParser.AnalyzeCircles(bbox);
                foreach (StlParser.CircleFit c in circles)
                {
                    // world 좌표 변환
                    double wcx, wcy, wcz, wax, way, waz;
                    m_Builder.StlLocalToWorld(si, c.Cx, c.Cy, c.Cz, false, out wcx, out wcy, out wcz);
                    m_Builder.StlLocalToWorld(si, c.Ax, c.Ay, c.Az, true, out wax, out way, out waz);
                    double al = Math.Sqrt(wax * wax + way * way + waz * waz);
                    if (al > 1e-9) { wax /= al; way /= al; waz /= al; }
                    m_lstSnapCircles.Add(new SnapCircleEntry
                    {
                        StepIdx = si, Circle = c,
                        Wcx = wcx, Wcy = wcy, Wcz = wcz,
                        Wax = wax, Way = way, Waz = waz,
                        Wr = c.Radius
                    });
                }
            }
        }

        /// <summary>마우스 ray 와 가장 가까운 원 찾기. 원 평면 교차점에서 원 중심까지의 거리가
        /// radius 의 0.6~1.4 범위면 hit (원의 boundary 근처).</summary>
        private int PickCircleByRay(int screenX, int screenY)
        {
            if (m_C3d == null) return -1;
            double ox, oy, oz, dx, dy, dz;
            if (!m_C3d.ScreenToWorldRay(screenX, screenY, out ox, out oy, out oz, out dx, out dy, out dz))
                return -1;
            int best = -1; double bestScore = double.MaxValue;
            for (int i = 0; i < m_lstSnapCircles.Count; i++)
            {
                SnapCircleEntry ce = m_lstSnapCircles[i];
                // ray-plane 교차 (평면: n·(p-c) = 0)
                double denom = dx * ce.Wax + dy * ce.Way + dz * ce.Waz;
                if (Math.Abs(denom) < 1e-6) continue;
                double t = ((ce.Wcx - ox) * ce.Wax + (ce.Wcy - oy) * ce.Way + (ce.Wcz - oz) * ce.Waz) / denom;
                if (t < 0) continue;
                double px = ox + t * dx, py = oy + t * dy, pz = oz + t * dz;
                double rx = px - ce.Wcx, ry = py - ce.Wcy, rz = pz - ce.Wcz;
                double rdist = Math.Sqrt(rx * rx + ry * ry + rz * rz);
                // hit 인정: |rdist - radius| < radius*0.4 + 3mm
                double diff = Math.Abs(rdist - ce.Wr);
                double tol = ce.Wr * 0.4 + 3.0;
                if (diff < tol && diff < bestScore)
                { bestScore = diff; best = i; }
            }
            return best;
        }

        /// <summary>원 모드에서 클릭/Hover 처리.</summary>
        private void HandleCircleClick(int hitIdx)
        {
            if (hitIdx < 0) return;
            SnapCircleEntry tgt = m_lstSnapCircles[hitIdx];
            // 원 클릭 = 그 원의 owner STL 클릭과 동일 취급 — lstHistory 에 반영.
            //   사용자가 다른 부품의 원을 클릭하면 자동으로 그 부품으로 선택 전환.
            //   m_bSyncingSelection 가드로 부작용 (DH 텍스트 동기화) 차단.
            if (tgt.StepIdx >= 0 && tgt.StepIdx < lstHistory.Items.Count &&
                lstHistory.SelectedIndex != tgt.StepIdx)
            {
                m_bSyncingSelection = true;
                try { lstHistory.SelectedIndex = tgt.StepIdx; }
                finally { m_bSyncingSelection = false; }
            }
            // 피벗 선택 모드 우선: source/target 정렬 로직 가로채기
            if (m_bSnapPivotPickMode)
            {
                m_dSnapPivotCx = tgt.Wcx; m_dSnapPivotCy = tgt.Wcy; m_dSnapPivotCz = tgt.Wcz;
                m_dSnapPivotAx = tgt.Wax; m_dSnapPivotAy = tgt.Way; m_dSnapPivotAz = tgt.Waz;
                m_bSnapPivotSet = true;
                m_bSnapPivotPickMode = false;
                // 피벗 원의 owner STL 을 '이동(rotating) 대상' 으로 설정.
                //   snap.html 의 partB 동작 — 클릭한 원의 부품이 회전 주체가 됨.
                //   lstHistory.SelectedIndex 변경 → SetSelectedIndex 가 dummy 이벤트 발생할 수 있으니
                //   m_bSyncingSelection 으로 가드.
                if (tgt.StepIdx >= 0 && tgt.StepIdx < lstHistory.Items.Count)
                {
                    m_bSyncingSelection = true;
                    try { lstHistory.SelectedIndex = tgt.StepIdx; }
                    finally { m_bSyncingSelection = false; }
                }
                UpdateSnapPivotButtonState();
                UpdatePreview(null);
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = string.Format(
                        "✓ 피벗 + 회전 대상 = step #{0}\r\nC=({1:F1},{2:F1},{3:F1}) r={4:F1}\r\nN=({5:F2},{6:F2},{7:F2})\r\n→ '선택축' + ±90° 로 회전",
                        tgt.StepIdx, tgt.Wcx, tgt.Wcy, tgt.Wcz, tgt.Wr,
                        tgt.Wax, tgt.Way, tgt.Waz);
                return;
            }
            if (m_nSnapSrcCircleIdx < 0)
            {
                m_nSnapSrcCircleIdx = hitIdx;
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = string.Format(
                        "✓ source 원 (step #{0}, r={1:F1})\r\n→ target 원 클릭",
                        tgt.StepIdx, tgt.Wr);
                return;
            }
            // 2차: target — mateCircles
            SnapCircleEntry src = m_lstSnapCircles[m_nSnapSrcCircleIdx];
            if (src.StepIdx == tgt.StepIdx)
            {
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = "자기자신 STL — 다른 STL 의 원 클릭";
                return;
            }
            MateCircles(src, tgt);
            m_nSnapSrcCircleIdx = -1;
            m_nSnapHovCircleIdx = -1;
            BuildCircleCache();   // STL 이동했으니 cache 재빌드
            RefreshHistory();
            UpdatePreview(null);
        }

        /// <summary>snap.html mateCircles: source 원의 축을 target 축에 정렬 + 중심 일치.
        /// source STL 의 회전 + offset 둘 다 갱신. (R_dh = I 가정)</summary>
        private void MateCircles(SnapCircleEntry src, SnapCircleEntry tgt)
        {
            // 1) 축 정렬: source.axis → target.axis 의 최소 회전
            double sx = src.Wax, sy = src.Way, sz = src.Waz;
            double tx = tgt.Wax, ty = tgt.Way, tz = tgt.Waz;
            // 같은 방향 (dot<0 이면 target 뒤집어서 최소 회전)
            double dotSign = sx * tx + sy * ty + sz * tz;
            if (dotSign < 0) { tx = -tx; ty = -ty; tz = -tz; }
            // R_rotate = source axis 를 target axis 로 보내는 회전
            double[,] Rrot = DhBuilder.RotationFromVectors(sx, sy, sz, tx, ty, tz);

            // 2) source STL 의 기존 rotation Rm 과 합성 → Rm_new = Rrot * Rm
            DhStep srcStep = m_Builder.GetStep(src.StepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(srcStep.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            double[,] Rm = DhBuilder.StlLocalRotation(pan, tilt, swing);
            double[,] RmNew = DhBuilder.MatMul3x3(Rrot, Rm);
            float panNew, tiltNew, swingNew;
            DhBuilder.ZXYEulerFromMatrix(RmNew, out panNew, out tiltNew, out swingNew);

            // 3) 새 offset: vertex_world_new = Rrot * vertex_world_old + correction
            //    src_center 주위 회전이라 vertex_world_new = Rrot * (vertex - src_center) + src_center
            //    + (target_center - source_center_after_rotation)
            //    source 가 회전 후에도 같은 source_center 위치라면 (제자리 회전) → 그 다음 평행이동
            //
            //    STL 변환: vertex_world = Rm * v + offset  (R_dh = I)
            //    vertex_world_new = Rm_new * v + offset_new
            //    = Rrot * (Rm * v + offset_old - src_center) + src_center + (tgt_center - src_center_post)
            //    src_center_post = Rrot * 0 + src_center (회전 중심은 그대로)
            //    = Rrot * Rm * v + Rrot * (offset_old - src_center) + src_center + tgt_center - src_center
            //    = Rm_new * v + Rrot * (offset_old - src_center) + tgt_center
            double ocx = ox - src.Wcx, ocy = oy - src.Wcy, ocz = oz - src.Wcz;
            double rcx = Rrot[0, 0] * ocx + Rrot[0, 1] * ocy + Rrot[0, 2] * ocz;
            double rcy = Rrot[1, 0] * ocx + Rrot[1, 1] * ocy + Rrot[1, 2] * ocz;
            double rcz = Rrot[2, 0] * ocx + Rrot[2, 1] * ocy + Rrot[2, 2] * ocz;
            float oxNew = (float)(rcx + tgt.Wcx);
            float oyNew = (float)(rcy + tgt.Wcy);
            float ozNew = (float)(rcz + tgt.Wcz);

            // 4) 새 DH 라인 빌드 (신/구 형식 보존, rotation 도 갱신)
            srcStep.DhLines = DhBuilder.RebuildStlDhFull(srcStep.DhLines,
                oxNew, oyNew, ozNew, panNew, tiltNew, swingNew);

            RefreshHistory();
            UpdatePreview(null);
            SyncSnapManual();

            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = string.Format(
                    "✓ 원 정렬 완료\r\nsrc r={0:F1} → tgt r={1:F1}\r\n회전={2:F0}/{3:F0}/{4:F0} dir-flip={5}",
                    src.Wr, tgt.Wr, panNew, tiltNew, swingNew, dotSign < 0 ? "예" : "아니오");
        }

        /// <summary>STL DH 라인의 offset + rotation 갱신 (신/구 형식 보존).</summary>
        // (Phase R1 통합) 다음 헬퍼는 DhBuilder partial 로 이동:
        //   RebuildStlDhFull / StripStlLines / MakeStlPreviewDhLinesFormatPreserved /
        //   GetStlColorFromDhLines / GetStlComplementColor / StlLocalToWorld / WorldDeltaToStlOffsetDelta
        //   기존 순수 수학 (R1 의 이전 라운드):
        //   DhBuilder.RotationFromVectors / MatMul3x3 / Transpose3x3 / ZXYEulerFromMatrix / AxisAngleRotation

        private void SetSnapModeButtonState()
        {
            bool plane = (m_strSnapMode == "plane");
            bool circle = (m_strSnapMode == "circle");
            bool manual = m_bManualMoveMode;
            // 수동 이동 모드에서는 평면/원 모드 비활성
            if (m_btnSnapPlane != null)
            {
                bool on = plane && !manual;
                m_btnSnapPlane.BackColor = on ? Color.FromArgb(42, 108, 255) : SystemColors.Control;
                m_btnSnapPlane.ForeColor = on ? Color.White : SystemColors.ControlText;
                m_btnSnapPlane.UseVisualStyleBackColor = !on;
            }
            if (m_btnSnapCircle != null)
            {
                bool on = circle && !manual;
                m_btnSnapCircle.BackColor = on ? Color.FromArgb(42, 108, 255) : SystemColors.Control;
                m_btnSnapCircle.ForeColor = on ? Color.White : SystemColors.ControlText;
                m_btnSnapCircle.UseVisualStyleBackColor = !on;
            }
            if (m_btnManualMove != null)
            {
                m_btnManualMove.BackColor = manual ? Color.FromArgb(255, 140, 0) : SystemColors.Control;
                m_btnManualMove.ForeColor = manual ? Color.White : SystemColors.ControlText;
                m_btnManualMove.UseVisualStyleBackColor = !manual;
            }
        }

        private void SetSnapAxis(string axis)
        {
            m_strSnapAxis = axis;
            Button[] all = { m_btnSnapAxX, m_btnSnapAxY, m_btnSnapAxZ, m_btnSnapAxSel };
            string[] keys = { "x", "y", "z", "sel" };
            Color[] hints = { Color.IndianRed, Color.SeaGreen, Color.RoyalBlue, Color.DarkGray };
            for (int i = 0; i < all.Length; i++)
            {
                if (all[i] == null) continue;
                bool on = (keys[i] == axis);
                if (on) { all[i].BackColor = Color.FromArgb(42, 108, 255); all[i].ForeColor = Color.White; all[i].UseVisualStyleBackColor = false; }
                else { all[i].BackColor = SystemColors.Control; all[i].ForeColor = hints[i]; all[i].UseVisualStyleBackColor = true; }
            }
        }

        private void OnSnapRotate(int signedDeg)
        {
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0)
            {
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = "STL 미선택 — history 에서 STL 선택 필요";
                return;
            }
            // "선택축" + 피벗 설정 → 피벗 중심 + 피벗 축 기준 회전 (snap.html 원래 동작)
            if (m_strSnapAxis == "sel")
            {
                if (!m_bSnapPivotSet)
                {
                    if (m_lblSnapStatus != null)
                        m_lblSnapStatus.Text = "피벗 미설정 — '중심: 원 선택' 으로 원 클릭";
                    return;
                }
                RotateStlAroundPivot(stepIdx, signedDeg,
                    m_dSnapPivotCx, m_dSnapPivotCy, m_dSnapPivotCz,
                    m_dSnapPivotAx, m_dSnapPivotAy, m_dSnapPivotAz);
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = string.Format(
                        "회전 {0}{1}° (피벗 중심, 피벗 축)\r\nC=({2:F1},{3:F1},{4:F1})\r\nN=({5:F2},{6:F2},{7:F2})",
                        signedDeg > 0 ? "+" : "", signedDeg,
                        m_dSnapPivotCx, m_dSnapPivotCy, m_dSnapPivotCz,
                        m_dSnapPivotAx, m_dSnapPivotAy, m_dSnapPivotAz);
                SyncSnapManual();
                return;
            }
            // X/Y/Z: pan/tilt/swing 단순 가산 (기존 동작 유지)
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            switch (m_strSnapAxis)
            {
                case "x": tilt += signedDeg; break;
                case "y": pan  += signedDeg; break;
                case "z": swing += signedDeg; break;
            }
            step.DhLines = DhBuilder.RebuildStlDhFull(step.DhLines, ox, oy, oz, pan, tilt, swing);
            RefreshHistory(); UpdatePreview(null);
            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = string.Format("회전 {0}{1}° (축={2})", signedDeg > 0 ? "+" : "", signedDeg, m_strSnapAxis.ToUpper());
            SyncSnapManual();
        }

        /// <summary>STL 을 world 피벗 중심 + 피벗 축 기준으로 deg 도 회전.
        /// <para>변환: new_world_origin = pivot + R(axis,deg) * (old_world_origin - pivot)</para>
        /// <para>      new_R_world      = R(axis,deg) * old_R_world</para>
        /// 단, R_dh = I 가정 (DH chain 회전 없음). chain 에 회전 있으면 추가 변환 필요.</summary>
        private void RotateStlAroundPivot(int stepIdx, double deg,
            double pivCx, double pivCy, double pivCz,
            double axX, double axY, double axZ)
        {
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            if (!DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing)) return;
            // STL world 위치 = endpoint + Re * (ox, oy, oz) — 여기선 R_dh = I 가정
            double epx, epy, epz;
            m_Builder.GetEndpointPosition(stepIdx, out epx, out epy, out epz);
            double[,] Re = m_Builder.GetEndpointRotation(stepIdx);
            double wx = epx + Re[0, 0] * ox + Re[0, 1] * oy + Re[0, 2] * oz;
            double wy = epy + Re[1, 0] * ox + Re[1, 1] * oy + Re[1, 2] * oz;
            double wz = epz + Re[2, 0] * ox + Re[2, 1] * oy + Re[2, 2] * oz;

            // 피벗 축 정규화
            double al = Math.Sqrt(axX*axX + axY*axY + axZ*axZ);
            if (al < 1e-9) return;
            axX /= al; axY /= al; axZ /= al;

            // 축-각도 회전 행렬 (Rodrigues)
            double[,] Rrot = DhBuilder.AxisAngleRotation(axX, axY, axZ, deg * Math.PI / 180.0);

            // world origin 회전 : new = pivot + R * (old - pivot)
            double dx = wx - pivCx, dy = wy - pivCy, dz = wz - pivCz;
            double rx = Rrot[0,0]*dx + Rrot[0,1]*dy + Rrot[0,2]*dz;
            double ry = Rrot[1,0]*dx + Rrot[1,1]*dy + Rrot[1,2]*dz;
            double rz = Rrot[2,0]*dx + Rrot[2,1]*dy + Rrot[2,2]*dz;
            double newWx = pivCx + rx, newWy = pivCy + ry, newWz = pivCz + rz;

            // world origin → DH endpoint 로컬 offset (R_dh = I 가정으로 Re^T 적용)
            double dxw = newWx - epx, dyw = newWy - epy, dzw = newWz - epz;
            float oxNew = (float)(Re[0,0]*dxw + Re[1,0]*dyw + Re[2,0]*dzw);
            float oyNew = (float)(Re[0,1]*dxw + Re[1,1]*dyw + Re[2,1]*dzw);
            float ozNew = (float)(Re[0,2]*dxw + Re[1,2]*dyw + Re[2,2]*dzw);

            // STL 자체 회전 합성 (DH chain 회전 일반화):
            //   R_world_new = R_rot * R_world_old
            //   R_world = Re * Rm  →  Re * Rm_new = R_rot * Re * Rm_old
            //   Rm_new = Re^T * R_rot * Re * Rm_old   (피벗축을 DH 로컬 프레임으로 conjugation)
            double[,] Rm   = DhBuilder.StlLocalRotation(pan, tilt, swing);
            double[,] ReT  = DhBuilder.Transpose3x3(Re);
            double[,] tmp1 = DhBuilder.MatMul3x3(Rrot, Re);     // R_rot * Re
            double[,] tmp2 = DhBuilder.MatMul3x3(ReT, tmp1);    // Re^T * R_rot * Re  ← 로컬 회전
            double[,] RmNew = DhBuilder.MatMul3x3(tmp2, Rm);    // 로컬 회전 * 이전 Rm
            float panNew, tiltNew, swingNew;
            DhBuilder.ZXYEulerFromMatrix(RmNew, out panNew, out tiltNew, out swingNew);

            step.DhLines = DhBuilder.RebuildStlDhFull(step.DhLines,
                oxNew, oyNew, ozNew, panNew, tiltNew, swingNew);
            RefreshHistory();
            // STL 이 회전했으므로 검출된 원들의 world 좌표/축 도 변경됨 → cache 재빌드
            // (피벗 자체는 world 좌표라 유지)
            if (m_bFaceSnapMode && m_strSnapMode == "circle") BuildCircleCache();
            UpdatePreview(null);
        }

        // (Phase 2 통합) AxisAngleRotation → DhBuilder.AxisAngleRotation

        private void OnSnapPivotPick(object sender, EventArgs e)
        {
            if (!m_bFaceSnapMode || m_strSnapMode != "circle")
            {
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = "피벗 선택은 원 모드에서만 가능 — '원' 모드 활성화 필요";
                return;
            }
            m_bSnapPivotPickMode = !m_bSnapPivotPickMode;
            UpdateSnapPivotButtonState();
            if (m_lblSnapStatus != null)
                m_lblSnapStatus.Text = m_bSnapPivotPickMode
                    ? "피벗 선택 모드 — 원 클릭 → 그 원의 중심 + 축이 피벗으로 설정"
                    : (m_bSnapPivotSet
                        ? "피벗 선택 모드 OFF (이전 피벗 유지)"
                        : "피벗 선택 모드 OFF (피벗 미설정)");
        }

        private void UpdateSnapPivotButtonState()
        {
            if (m_btnSnapRotPivot == null) return;
            if (m_bSnapPivotPickMode)
            {
                m_btnSnapRotPivot.BackColor = Color.FromArgb(42, 108, 255);
                m_btnSnapRotPivot.ForeColor = Color.White;
                m_btnSnapRotPivot.Text = "원 클릭 중…";
                m_btnSnapRotPivot.UseVisualStyleBackColor = false;
            }
            else if (m_bSnapPivotSet)
            {
                m_btnSnapRotPivot.BackColor = Color.FromArgb(255, 140, 0);
                m_btnSnapRotPivot.ForeColor = Color.White;
                m_btnSnapRotPivot.Text = "피벗 ✓ (재선택)";
                m_btnSnapRotPivot.UseVisualStyleBackColor = false;
            }
            else
            {
                m_btnSnapRotPivot.BackColor = SystemColors.Control;
                m_btnSnapRotPivot.ForeColor = SystemColors.ControlText;
                m_btnSnapRotPivot.Text = "중심: 원 선택";
                m_btnSnapRotPivot.UseVisualStyleBackColor = true;
            }
        }

        private void OnSnapReset(object sender, EventArgs e)
        {
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) { if (m_lblSnapStatus != null) m_lblSnapStatus.Text = "STL 미선택"; return; }
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            step.DhLines = DhBuilder.BuildStlDhLines(fn, 0, 0, 0, 0, 0, 0);
            RefreshHistory(); UpdatePreview(null);
            if (m_lblSnapStatus != null) m_lblSnapStatus.Text = "리셋: offset/회전 모두 0";
            SyncSnapManual();
        }

        private void OnSnapApplyManual(object sender, EventArgs e)
        {
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) { if (m_lblSnapStatus != null) m_lblSnapStatus.Text = "STL 미선택"; return; }
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            ParseFloatOr(m_txtSnapPx, ref ox);
            ParseFloatOr(m_txtSnapPy, ref oy);
            ParseFloatOr(m_txtSnapPz, ref oz);
            ParseFloatOr(m_txtSnapRy, ref pan);    // Y = pan
            ParseFloatOr(m_txtSnapRx, ref tilt);   // X = tilt
            ParseFloatOr(m_txtSnapRz, ref swing);  // Z = swing
            step.DhLines = DhBuilder.BuildStlDhLines(fn, ox, oy, oz, pan, tilt, swing);
            RefreshHistory(); UpdatePreview(null);
            SyncSnapManual();
            if (m_lblSnapStatus != null) m_lblSnapStatus.Text = "수동 변환 적용 완료";
        }

        private void ParseFloatOr(TextBox txt, ref float dst)
        {
            if (txt == null) return;
            float v;
            if (float.TryParse(txt.Text, System.Globalization.NumberStyles.Float,
                System.Globalization.CultureInfo.InvariantCulture, out v)) dst = v;
        }

        /// <summary>선택된 STL 의 현재 offset/회전을 수동 변환 입력칸에 동기화.
        /// 포커스 + Modified=true 인 텍스트박스는 사용자가 편집 중이므로 덮어쓰지 않음.</summary>
        private void SyncSnapManual()
        {
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) return;
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            SetSnapField(m_txtSnapPx, ox);
            SetSnapField(m_txtSnapPy, oy);
            SetSnapField(m_txtSnapPz, oz);
            SetSnapField(m_txtSnapRx, tilt);
            SetSnapField(m_txtSnapRy, pan);
            SetSnapField(m_txtSnapRz, swing);
        }

        private void SetSnapField(TextBox txt, float value)
        {
            if (txt == null) return;
            // 사용자가 편집 중 (포커스 + Modified) 이면 덮어쓰지 않음 → 입력값 보존
            if (txt.Focused && txt.Modified) return;
            txt.Text = value.ToString("F2");
            txt.Modified = false;   // 프로그래밍 갱신 → Modified 리셋
        }

        // ========================================
        // Face Snap — 두 면 클릭 정렬 (snap.js mateFaces)
        // ========================================

        private void btnFaceSnap_Click(object sender, EventArgs e)
        {
            if (m_bFaceSnapMode) { ExitFaceSnapMode("Face Snap 취소"); return; }
            // 다른 모드와 상호 배타
            if (m_bMergeMode) ExitMergeMode();
            m_bFaceSnapMode = true;
            m_nFaceSnapClick = 0;
            m_nSnapSrcStepIdx = -1;
            // btnStlMerge_Click 과 동일한 hover 상태 초기화 (이게 없으면 hover preview 가 stale 상태)
            m_bHoverActive = false;
            m_nLastHoverX = -100;
            m_nLastHoverY = -100;
            m_Builder.ClearOverlay();
            if (m_C3d != null) m_C3d.SetMouseMode(0);
            UpdatePreview(null);
            lblStatus.Text = "Face Snap: 1) 이동할 STL 의 면 클릭";
            lblCurrentValue.Text = "src 대기중";
        }

        private void ExitFaceSnapMode(string status)
        {
            m_bFaceSnapMode = false;
            m_nFaceSnapClick = 0;
            m_nSnapSrcStepIdx = -1;
            m_bSnapHoverActive = false;
            // 원 모드 cache 정리
            m_lstSnapCircles.Clear();
            m_nSnapSrcCircleIdx = -1;
            m_nSnapHovCircleIdx = -1;
            m_Builder.ClearOverlay();
            if (m_C3d != null)
                m_C3d.SetMouseMode(m_eMode == InteractionMode.Mouse ? 99 : 0);
            UpdatePreview(null);
            if (!string.IsNullOrEmpty(status)) lblStatus.Text = status;
            lblCurrentValue.Text = "";
        }

        // (Phase R1 통합) StlLocalToWorld / WorldDeltaToStlOffsetDelta → m_Builder 의 인스턴스 메서드로 이동

        /// <summary>STL DH 라인의 offset 자리만 갱신하고 나머지 (color, scale, type/num,
        /// pan/tilt/swing) 는 원본 그대로 보존. 신형 (`[ ]`) / 구형 형식 모두 자동 감지.
        ///   신형: @[filename,color,scale],[type,num],[offX,offY,offZ],[pan,tilt,swing]
        ///   구형: @filename,color,scale,type,num,offX,offY,offZ,pan,tilt,swing</summary>
        private string RebuildStlDhWithNewOffset(string originalDh,
            float newOx, float newOy, float newOz)
        {
            if (string.IsNullOrEmpty(originalDh)) return originalDh;
            // 신형 여부 검출: ],[ 패턴 또는 ] 시작 그룹
            bool isNewFormat = originalDh.Contains("],[") || originalDh.Contains("[");

            string raw = originalDh.TrimStart('@').Replace("[", "").Replace("]", "");
            string[] parts = raw.Split(',');
            if (parts.Length < 11) return originalDh;   // 파싱 실패 시 원본 유지

            string filename = parts[0].Trim();
            string color   = parts[1].Trim();
            string scale   = parts[2].Trim();
            string type    = parts[3].Trim();
            string num     = parts[4].Trim();
            // parts[5..7] = offset (override) / parts[8..10] = pan/tilt/swing (보존)
            string pan   = parts[8].Trim();
            string tilt  = parts[9].Trim();
            string swing = parts[10].Trim();

            var ci = System.Globalization.CultureInfo.InvariantCulture;
            if (isNewFormat)
            {
                return string.Format(ci,
                    "@[{0},{1},{2}],[{3},{4}],[{5:F2},{6:F2},{7:F2}],[{8},{9},{10}]",
                    filename, color, scale, type, num,
                    newOx, newOy, newOz, pan, tilt, swing);
            }
            else
            {
                return string.Format(ci,
                    "@{0},{1},{2},{3},{4},{5:F2},{6:F2},{7:F2},{8},{9},{10}",
                    filename, color, scale, type, num,
                    newOx, newOy, newOz, pan, tilt, swing);
            }
        }

        /// <summary>면 클릭 후 호출 — Face Snap 의 1st(source) / 2nd(target) 분기.</summary>
        private void HandleFaceSnapClick()
        {
            int hitStepIdx = m_nSelectedStlHistoryIdx;
            if (hitStepIdx < 0) return;

            // 1) 클릭된 면의 중심/법선을 월드 좌표로 변환
            double wcx, wcy, wcz, wnx, wny, wnz;
            m_Builder.StlLocalToWorld(hitStepIdx,
                m_fSelectedFaceCenterX, m_fSelectedFaceCenterY, m_fSelectedFaceCenterZ,
                false, out wcx, out wcy, out wcz);
            m_Builder.StlLocalToWorld(hitStepIdx,
                m_fSelectedFaceNormalX, m_fSelectedFaceNormalY, m_fSelectedFaceNormalZ,
                true, out wnx, out wny, out wnz);
            // 법선 정규화
            double nl = Math.Sqrt(wnx * wnx + wny * wny + wnz * wnz);
            if (nl > 1e-9) { wnx /= nl; wny /= nl; wnz /= nl; }

            if (m_nFaceSnapClick == 0)
            {
                // 1st 클릭: source 저장
                m_nSnapSrcStepIdx = hitStepIdx;
                m_dSnapSrcCx = wcx; m_dSnapSrcCy = wcy; m_dSnapSrcCz = wcz;
                m_dSnapSrcNx = wnx; m_dSnapSrcNy = wny; m_dSnapSrcNz = wnz;
                m_nFaceSnapClick = 1;
                lblStatus.Text = "Face Snap: 2) target 면 클릭 (붙일 면)";
                lblCurrentValue.Text = string.Format(
                    "src @ ({0:F1},{1:F1},{2:F1}) n=({3:F2},{4:F2},{5:F2})",
                    wcx, wcy, wcz, wnx, wny, wnz);
                if (m_lblSnapStatus != null)
                {
                    m_lblSnapStatus.Text = string.Format(
                        "✓ 소스 저장됨 (step #{0})\r\nc=({1:F1},{2:F1},{3:F1}) n=({4:F2},{5:F2},{6:F2})\r\n→ 이제 target 면 클릭",
                        hitStepIdx, wcx, wcy, wcz, wnx, wny, wnz);
                }
                return;
            }

            // 2nd 클릭: target — 두 가지 guard:
            //   (a) 같은 STL 자기 자신 클릭 → 무시 (사용자 의도와 다른 자기 정렬 방지)
            //   (b) source 면 법선과 target 면 법선의 방향이 다름 → 무시
            //       (평면 모드는 회전 안 함. 다른 방향 면은 정렬 안 됨이 정상.)
            if (hitStepIdx == m_nSnapSrcStepIdx)
            {
                if (m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = string.Format(
                        "자기자신 STL (step #{0})\r\n→ 다른 STL 위에 정확히 클릭\r\n(작은 STL 은 클릭 어려움)",
                        hitStepIdx);
                lblStatus.Text = string.Format(
                    "Face Snap: source=step #{0} 와 target=step #{0} 동일. 다른 STL 클릭.",
                    hitStepIdx);
                return;   // click 카운트 유지 (소스 그대로)
            }
            // 법선 방향 정보 (정렬 후 사용자 참고용 — guard 없음. snap.html 과 동일.)
            //   mateFaces 는 source 법선 방향만 사용. target 법선 무관. 직교 면 조합도 정렬됨.
            //   다만 사용자 의도와 다를 수 있어서 cos 값을 결과 메시지에 표시.
            double srcDotTgt = wnx * m_dSnapSrcNx + wny * m_dSnapSrcNy + wnz * m_dSnapSrcNz;

            // mateFaces 핵심:
            //   delta = target_center - source_center
            //   offset_world = (delta · source_n) * source_n
            //   → source 면 법선 방향 성분만 → 같은 평면. 측면 위치 유지.
            double dx = wcx - m_dSnapSrcCx;
            double dy = wcy - m_dSnapSrcCy;
            double dz = wcz - m_dSnapSrcCz;
            double dot = dx * m_dSnapSrcNx + dy * m_dSnapSrcNy + dz * m_dSnapSrcNz;
            double offWx = dot * m_dSnapSrcNx;
            double offWy = dot * m_dSnapSrcNy;
            double offWz = dot * m_dSnapSrcNz;

            // 월드 offset → source STL 의 DH endpoint 로컬 delta
            float dox, doy, doz;
            m_Builder.WorldDeltaToStlOffsetDelta(m_nSnapSrcStepIdx,
                offWx, offWy, offWz, out dox, out doy, out doz);

            // source STL 의 기존 offset 에 더해서 새 DH 라인 생성.
            // BuildStlDhLines 는 color 인자 X (무조건 -1) + 구형 형식 → 원본 손실.
            // 직접 신/구 형식 보존하면서 offset 만 갱신.
            DhStep srcStep = m_Builder.GetStep(m_nSnapSrcStepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(srcStep.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            srcStep.DhLines = RebuildStlDhWithNewOffset(srcStep.DhLines,
                ox + dox, oy + doy, oz + doz);

            ExitFaceSnapMode(null);
            RefreshHistory();
            UpdatePreview(null);
            SyncSnapManual();
            lblStatus.Text = string.Format(
                "Face Snap 완료: dist={0:F2}mm (법선 방향 평행이동)", dot);
            lblCurrentValue.Text = string.Format(
                "Δ=({0:F2},{1:F2},{2:F2})mm", dox, doy, doz);
            // 진단 — 사용자가 이상한 결과 보고 시 분석 가능
            Ojw.printf(txtLogHistory,
                "\r\n=== [mateFaces 진단] ===\r\n" +
                "  src_n=({0:F3},{1:F3},{2:F3}) src_c=({3:F2},{4:F2},{5:F2})\r\n",
                m_dSnapSrcNx, m_dSnapSrcNy, m_dSnapSrcNz,
                m_dSnapSrcCx, m_dSnapSrcCy, m_dSnapSrcCz);
            Ojw.printf(txtLogHistory,
                "  tgt_n=({0:F3},{1:F3},{2:F3}) tgt_c=({3:F2},{4:F2},{5:F2})\r\n",
                wnx, wny, wnz, wcx, wcy, wcz);
            Ojw.printf(txtLogHistory,
                "  cos(src_n,tgt_n)={0:F3}, dist={1:F2}mm\r\n",
                srcDotTgt, dot);
            Ojw.printf(txtLogHistory,
                "  Δ world=({0:F3},{1:F3},{2:F3}) Δ local=({3:F3},{4:F3},{5:F3})\r\n",
                offWx, offWy, offWz, dox, doy, doz);
            if (m_lblSnapStatus != null)
            {
                m_lblSnapStatus.Text = string.Format(
                    "✓ 정렬: dist={0:F1}mm cos={1:F2}\r\nΔw=({2:F1},{3:F1},{4:F1})\r\nΔl=({5:F1},{6:F1},{7:F1})\r\n→ Log 탭 진단 참조",
                    dot, srcDotTgt, offWx, offWy, offWz, dox, doy, doz);
            }
        }

        // ========================================
        // 3D 초기화 (Kinematics Main.cs:485 패턴)
        // ========================================
        private void Init3d()
        {
            m_C3d = new Ojw.C3d();
            m_C3d.Init(pnDisp);
            m_C3d.SetFilePath_Design(Application.StartupPath);
            m_C3d.SetStandardAxis(true);
            m_C3d.SetVirtualClass_Enable(false);
            m_C3d.SetAseFile_Path("stl");
            m_C3d.SetSkeletonView(true);
            m_C3d.SetMouseMode(99); // 기본 마우스 모드
            // 로봇 좌표계 기준 초기 뷰: X=정면(화면 밖), Z=위
            m_C3d.SetCoordMode(1);
            // 초기 뷰 각도: 약간 비틀어 3D 입체감 있게
            m_C3d.SetAngle_Display(20.0f, 0.0f, 15.0f);

            // 커스텀 마우스 핸들러 등록
            m_C3d.AddMouseEvent_Down(OnC3dMouseDown);
            m_C3d.AddMouseEvent_Move(OnC3dMouseMove);
            m_C3d.AddMouseEvent_Up(OnC3dMouseUp);
            m_C3d.AddMouseEvent_Wheel(OnC3dMouseWheel);

            // 3D 뷰 STL 드래그드롭 — Tools 프로젝트와 동일 UX (관리 폴더 복사 + 즉시 로드).
            //   MakeUrdf 는 텍스트 기반이므로 @ 라인을 EDH 커서 위치에 삽입하고 Apply 재실행
            //   (Tools 식 가상 오브젝트 주입은 다음 Apply 에서 소실되므로 텍스트 삽입이 정본)
            m_C3d.AllowDrop = true;
            m_C3d.DragEnter += C3d_DragEnter;
            m_C3d.DragDrop += C3d_DragDrop;

            // 카메라 미리보기 / USD Export / View MJCF / View USD / Isaac (USD) 버튼은
            // Main.Designer.cs 에 정의됨 (동적 생성 → Designer 이전, 2026-07-03)

            // === URDF 물리 자동기입 토글 (동적 — 관성/질량/서보 limit 재계산) ===
            //   기본 ON. 끄면 기존 플레이스홀더 <inertial> 그대로 내보냄.
            m_chkUrdfPhysics = new CheckBox();
            m_chkUrdfPhysics.Text = "물리 자동기입";
            m_chkUrdfPhysics.Checked = true;
            m_chkUrdfPhysics.AutoSize = true;
            m_chkUrdfPhysics.BackColor = Color.Transparent;
            m_chkUrdfPhysics.Location = new Point(btnViewMjcf.Right + 8, btnViewMjcf.Top + 12);
            this.Controls.Add(m_chkUrdfPhysics);
            m_chkUrdfPhysics.BringToFront();
        }

        /// <summary>URDF 물리 속성 자동 기입 토글 (Init3d 에서 동적 생성)</summary>
        private CheckBox m_chkUrdfPhysics = null;

        /// <summary>MJCF 뷰어 — robot_stl.xml 을 XML 하이라이팅 HTML 로 렌더.</summary>
        private void btnViewMjcf_Click(object sender, EventArgs e)
        {
            if (!ExportUrdfFiles()) return;
            try
            {
                string urdfDir = GetUrdfOutputDir();
                string mjcfPath = Path.Combine(urdfDir, "robot_stl.xml");
                if (!File.Exists(mjcfPath))
                {
                    MessageBox.Show("MJCF 파일이 없습니다: " + mjcfPath);
                    return;
                }
                string mjcfXml = File.ReadAllText(mjcfPath);
                string htmlPath = Path.Combine(urdfDir, "robot_stl_mjcf.html");
                OpenXmlInBrowser(mjcfXml, htmlPath, "MJCF Viewer", "robot_stl.xml (MuJoCo MJCF)");
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[View MJCF] 오류: {0}\r\n", ex.Message);
            }
        }

        /// <summary>USD (USDA) 뷰어 — robot_stl.usda 를 하이라이팅 HTML 로 렌더. 없으면 자동 생성.</summary>
        private void btnViewUsd_Click(object sender, EventArgs e)
        {
            try
            {
                string urdfDir = GetUrdfOutputDir();
                string usdaPath = Path.Combine(urdfDir, "robot_stl.usda");
                if (!File.Exists(usdaPath))
                {
                    // 없으면 USD Export 먼저 실행 (자동 편의)
                    btnExportUsd_Click(sender, e);
                    if (!File.Exists(usdaPath))
                    {
                        MessageBox.Show("USD 파일 생성 실패: " + usdaPath);
                        return;
                    }
                }
                string usda = File.ReadAllText(usdaPath);
                string htmlPath = Path.Combine(urdfDir, "robot_stl_usda.html");
                OpenUsdaInBrowser(usda, htmlPath, "robot_stl.usda (USD ASCII)");
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[View USD] 오류: {0}\r\n", ex.Message);
            }
        }

        /// <summary>Isaac Sim (USD) 실행 — .usda 파일을 isaac_runner 에 전달.
        /// btnIsaac_Click 과 거의 동일하지만 URDF 대신 USD 경로를 인수로 넘긴다.</summary>
        private void btnIsaacUsd_Click(object sender, EventArgs e)
        {
            string pythonBat = txtIsaacPath.Text.Trim();
            if (string.IsNullOrEmpty(pythonBat) || !File.Exists(pythonBat))
            {
                MessageBox.Show("Isaac Sim python.bat 경로를 확인해 주세요: " + pythonBat);
                return;
            }

            // USDA 는 항상 재생성 — 현재 로드된 로봇 기준으로 최신 보장
            //   (btnIsaac_Click 이 매번 ExportUrdfFiles() 하는 것과 동일 정책)
            string urdfDir = GetUrdfOutputDir();
            string usdaPath = Path.Combine(urdfDir, "robot_stl.usda");
            Ojw.printf(txtLogHistory, "[Isaac USD] .usda 자동 생성 중...\r\n");
            btnExportUsd_Click(sender, e);
            if (!File.Exists(usdaPath))
            {
                MessageBox.Show("USD 파일 생성 실패: " + usdaPath);
                return;
            }

            // isaac_runner.py 복사
            string pythonDir = FindPythonDir();
            string scriptSrc = Path.Combine(pythonDir, "isaac_runner.py");
            if (!File.Exists(scriptSrc))
            {
                MessageBox.Show("isaac_runner.py 가 없습니다: " + scriptSrc);
                return;
            }
            string scriptDst = Path.Combine(urdfDir, "isaac_runner.py");
            try { File.Copy(scriptSrc, scriptDst, true); }
            catch (Exception ex) { MessageBox.Show("스크립트 복사 실패: " + ex.Message); return; }

            Ojw.printf(txtLogHistory, "[Isaac USD] python.bat: {0}\r\n", pythonBat);
            Ojw.printf(txtLogHistory, "[Isaac USD] script:    {0}\r\n", scriptDst);
            Ojw.printf(txtLogHistory, "[Isaac USD] usda:      {0}\r\n", usdaPath);
            Ojw.printf(txtLogHistory, "[Isaac USD] 새 Isaac Sim 창 시작 — 로드까지 30~60초 소요\r\n");

            try
            {
                string logPath = GetWritableRunnerLogPath(urdfDir);
                string cmdArgs = string.Format(
                    "/c \"\"{0}\" \"{1}\" \"{2}\" > \"{3}\" 2>&1\"",
                    pythonBat, scriptDst, usdaPath, logPath);

                var psi = new ProcessStartInfo("cmd.exe", cmdArgs);
                psi.UseShellExecute = false;
                psi.WorkingDirectory = urdfDir;
                psi.EnvironmentVariables["OJW_FIXED_BASE"] = chkFixedBase.Checked ? "1" : "0";
                psi.EnvironmentVariables["OJW_SPAWN_Z"] =
                    string.IsNullOrEmpty(txtSpawnHeight.Text.Trim()) ? "0.4" : txtSpawnHeight.Text.Trim();
                // USD 모드 힌트 (Python 측이 확장자로도 감지하지만 명시적으로 전달)
                psi.EnvironmentVariables["OJW_LOAD_USD"] = "1";
                // 자동학습된 actuator-net 이 있으면 자동 주입
                string strActNetNpzUsd = Path.Combine(GetUrdfOutputDir(), "actnet_v1.npz");
                if (File.Exists(strActNetNpzUsd))
                {
                    psi.EnvironmentVariables["OJW_ACTNET"] = strActNetNpzUsd;
                    Ojw.printf(txtLogHistory, "[Isaac USD] OJW_ACTNET 적용 (자동학습)\r\n");
                }
                Ojw.printf(txtLogHistory, "[Isaac USD] OJW_LOAD_USD=1\r\n");
                Ojw.printf(txtLogHistory, "[Isaac USD] 출력 로그: {0}\r\n", logPath);
                Process.Start(psi);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Isaac Sim (USD) 실행 실패: " + ex.Message);
            }
        }

        /// <summary>USD Export — robot_stl.usda 를 URDF 폴더에 저장. Isaac Sim / Isaac Lab 이 직접 로드 가능.</summary>
        private void btnExportUsd_Click(object sender, EventArgs e)
        {
            // 먼저 표준 URDF export 파이프라인 실행 (STL 파일 복사, meshFolder 결정 등)
            if (!ExportUrdfFiles()) return;

            try
            {
                string urdfDir = GetUrdfOutputDir();
                string commandsPath = Path.Combine(urdfDir, "robot_commands.txt");
                if (!File.Exists(commandsPath))
                {
                    MessageBox.Show("robot_commands.txt 가 없습니다. 먼저 URDF Export 실행 필요.");
                    return;
                }
                string strUrdfCommand = File.ReadAllText(commandsPath, Encoding.UTF8);

                // USD 전용 builder (URDF builder 와 분리 — 미래 확장 여지)
                var usdBuilder = new Ojw.C3d.COjwUrdfBuilder_t();
                usdBuilder.RobotName = "ojw_robot";

                // 식별 메타데이터 — 문자열만 전달, 기록 로직은 라이브러리(BuildUsda) 소유
                if (m_nLastExampleIdx > 0 && !string.IsNullOrEmpty(m_strLastExampleName))
                    usdBuilder.ExportSource = string.Format("ex{0:D2} {1}",
                        m_nLastExampleIdx, m_strLastExampleName);
                else
                    usdBuilder.ExportSource = "manual_dh";
                bool bMetaSkel, bMetaMesh;
                GetViewModeFlags(out bMetaSkel, out bMetaMesh);
                usdBuilder.ExportViewMode = (bMetaMesh && !bMetaSkel) ? "STL만"
                    : (bMetaSkel && !bMetaMesh) ? "스켈레톤만" : "전체";
                string usdMeshPrefix = GetStlSubFolder();   // URDF와 동일 prefix 사용
                usdBuilder.MeshFolder = usdMeshPrefix;
                usdBuilder.ExportScene = chkExportScene != null && chkExportScene.Checked;
                if (chkFixedBase != null && chkFixedBase.Checked)
                    usdBuilder.SetWorldFixed();
                usdBuilder.ParseCommands(strUrdfCommand);

                // 물리 자동기입 반영 — 방금 export 된 robot_stl.urdf (마커 존재 시) 의 inertial 을
                // USDA 질량/COM/관성에 그대로 사용 (URDF 후처리 기준, 3포맷 수치 일치)
                try
                {
                    string urdfPhysPath = Path.Combine(urdfDir, "robot_stl.urdf");
                    if ((m_chkUrdfPhysics == null || m_chkUrdfPhysics.Checked) && File.Exists(urdfPhysPath))
                    {
                        string urdfPhysXml = File.ReadAllText(urdfPhysPath, Encoding.UTF8);
                        if (Ojw.C3d.COjwUrdfPhysics_t.IsProcessed(urdfPhysXml))
                        {
                            int nOvrLinks = usdBuilder.ApplyInertialFromUrdf(urdfPhysXml);
                            // 관절 한계·구동력도 URDF 를 정본으로 (없으면 USD 가 ±180°/effort 100 플레이스홀더로 나감)
                            int nOvrJoints = usdBuilder.ApplyJointLimitsFromUrdf(urdfPhysXml);
                            Ojw.printf(txtLogHistory, "[USD] 물리 자동기입 반영: 링크 inertial {0}개, 관절 limit {1}개\r\n",
                                nOvrLinks, nOvrJoints);
                        }
                    }
                }
                catch (Exception exPhysUsd)
                {
                    Ojw.printf(txtLogHistory, "[USD] 물리 반영 실패 (기존 추정 유지): {0}\r\n", exPhysUsd.Message);
                }

                // stlBaseDir = urdfDir — STL 파일을 직접 읽어 Mesh prim 으로 임베드 (자체완결 USDA)
                string usda = usdBuilder.BuildUsda(null, urdfDir);
                string usdaPath = Path.Combine(urdfDir, "robot_stl.usda");
                File.WriteAllText(usdaPath, usda, new UTF8Encoding(false));  // BOM 없이
                Ojw.printf(txtLogHistory, "[USD] {0} 저장 완료 ({1:N0} B)\r\n", usdaPath, new FileInfo(usdaPath).Length);
                Ojw.printf(txtLogHistory, "[USD] Isaac Sim 에서 File > Open 으로 열거나 isaac_runner 에서 --use-usd 옵션으로 로드\r\n");
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[USD] 오류: {0}\r\n", ex.Message);
                MessageBox.Show("USD Export 실패: " + ex.Message);
            }
        }

        // btnCameraPreview_Click 삭제 (2026-08-15) — Cam Preview 버튼 제거 후 남은 죽은 핸들러였음.
        //   $camera 미리보기는 "📺 Isaac 영상" 버튼(스트리밍)으로 대체됨.

        // ========================================
        // 3D 뷰 STL 드래그드롭 (Tools UX 이식, 2026-08-15)
        // ========================================
        private void C3d_DragEnter(object sender, DragEventArgs e)
        {
            if (e.Data.GetDataPresent(DataFormats.FileDrop)) e.Effect = DragDropEffects.Copy;
        }

        private void C3d_DragDrop(object sender, DragEventArgs e)
        {
            try
            {
                string[] files = (string[])e.Data.GetData(DataFormats.FileDrop, false);
                if (files == null) return;
                int nAdded = 0;
                foreach (string srcPath in files)
                {
                    string fname = Path.GetFileName(srcPath);
                    string ext = Path.GetExtension(fname).ToLower();
                    if (ext != ".stl" && ext != ".sstl" && ext != ".ase" && ext != ".dat" && ext != ".obj")
                        continue;

                    // STL 관리 폴더 (SetAseFile_Path("stl") → StartupPath\stl\) 로 복사 — Tools 와 동일 정책
                    string stlDir = Application.StartupPath.TrimEnd('\\') + m_C3d.GetAseFile_Path();
                    Directory.CreateDirectory(stlDir);
                    string dstPath = Path.Combine(stlDir, fname);
                    if (File.Exists(dstPath))
                    {
                        DialogResult ret = MessageBox.Show(
                            string.Format("{0}\r\n관리 폴더에 같은 이름의 파일이 있습니다. 덮어쓸까요?\r\n(아니오 = 기존 파일 그대로 사용)", fname),
                            "STL 덮어쓰기", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                        if (ret == DialogResult.Yes) File.Copy(srcPath, dstPath, true);
                    }
                    else File.Copy(srcPath, dstPath);

                    // EDH 에 @ 라인 삽입 — 커서 라인 뒤 = 그 부품/체인 좌표계에 부착 (스켈레톤 조립 UX)
                    InsertDhTextLineAtCursor(Ojw.C3d.Edh_BuildStlLine(fname));
                    nAdded++;
                    Ojw.printf(txtLogHistory, "[Drop] {0} → {1} 복사 + @ 라인 삽입\r\n", fname, stlDir);
                }
                if (nAdded > 0) btnApplyDh_Click(null, EventArgs.Empty); // 3D 반영 (시뮬 핫리로드는 러너 있을 때만)
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Drop] 오류: {0}\r\n", ex.Message);
            }
        }

        /// <summary>EDH 텍스트박스의 커서 라인 바로 뒤에 새 라인 삽입 (커서 없으면 맨 끝)</summary>
        private void InsertDhTextLineAtCursor(string strNewLine)
        {
            List<string> lines = new List<string>(txtDhParams.Lines);
            if (lines.Count == 0)
            {
                txtDhParams.Text = strNewLine + "\r\n";
                return;
            }
            int nLine = txtDhParams.GetLineFromCharIndex(txtDhParams.SelectionStart);
            if (nLine < 0 || nLine >= lines.Count) nLine = lines.Count - 1;
            lines.Insert(nLine + 1, strNewLine);
            txtDhParams.Lines = lines.ToArray();
        }

