            Ojw.printf_Init(txtLogHistory, false);
            Ojw.Log_Init(txtLogHistory, false);  // Ojw.Log2 출력도 Log 탭으로


            Init3d();
            InitControlPanel();
            InitDhEditPanel();
            //cmbViewMode.SelectedIndex = 0; // 기본: 전체 보기
            viewmodeApply();

            // 모터 ID 콤보 초기화: 자동, 0, 1, 2, ..., 19
