        /// <summary>모터 목록 갱신 (선택된 수식번호에 따라)</summary>
        /// <remarks>
        /// 개별 체인 수식: CalcInv_MotorIDs()로 해당 체인의 모터만 표시.
        /// 전체 수식 또는 단일 체인: DH 텍스트를 직접 파싱하여 모든 모터 수집.
        /// </remarks>
        private void UpdateMotorList()
        {
            if (cmbMotorCtrl == null) return;

            cmbMotorCtrl.Items.Clear();
            try
            {
                int funcNum = GetSelectedFuncNum();
                List<int> motorIds = new List<int>();

                // 개별 체인 또는 전체(merge) 수식이면 CalcInv_MotorIDs 사용
                if (m_C3d != null && m_nFormulaCount > 1 && funcNum >= 0 && funcNum <= m_nFormulaCount)
                {
                    int[] mids = m_C3d.CalcInv_MotorIDs(funcNum);
                    if (mids != null)
                    {
                        for (int i = 0; i < mids.Length; i++)
                            if (!motorIds.Contains(mids[i])) motorIds.Add(mids[i]);
                    }
                }
                else
                {
                    // 전체 또는 단일 체인: DH 텍스트 직접 파싱
                    string[] lines = txtDhParams.Lines;
                    for (int i = 0; i < lines.Length; i++)
                    {
                        string line = lines[i].Trim();
                        if (line.Length == 0 || line.StartsWith("//") || line.StartsWith("#"))
                            continue;

                        // 주석 꼬리 제거
                        int cmt = line.IndexOf("//");
                        if (cmt >= 0) line = line.Substring(0, cmt).Trim();
                        string cleaned = line.Replace("[", "").Replace("]", "");
                        string[] parts = cleaned.Split(',');

                        if (line.StartsWith("@"))
                        {
                            // 트랙 확장 라인: @filename, color, alpha, type, num, x, y, z, pan, tilt, swing, fX, fY, fR, fDist, mode, axis, dir
                            // axis (afTrack[5]) 는 parts[16]
                            if (parts.Length >= 17)
                            {
                                int nTrackAxis = Ojw.CConvert.StrToInt(parts[16].Trim());
                                if (nTrackAxis >= 0 && !motorIds.Contains(nTrackAxis))
                                    motorIds.Add(nTrackAxis);
                            }
                            continue;
                        }

                        // 일반 DH 라인: [A,D,Theta,Alpha],[Axis,Dir,Init,...] → parts[4] = axis
                        if (parts.Length > 4)
                        {
                            int nAxis = Ojw.CConvert.StrToInt(parts[4].Trim());
                            if (nAxis >= 0 && !motorIds.Contains(nAxis))
                                motorIds.Add(nAxis);
                        }
                    }
                }

                motorIds.Sort();
                for (int i = 0; i < motorIds.Count; i++)
                    cmbMotorCtrl.Items.Add("M" + motorIds[i].ToString());
            }
            catch { }

            // 모터가 없으면 안내
            if (cmbMotorCtrl.Items.Count == 0)
                cmbMotorCtrl.Items.Add("(\uc5c6\uc74c)");

            cmbMotorCtrl.SelectedIndex = 0;
        }

        /// <summary>선택된 모터 번호 가져오기</summary>
        private int GetSelectedMotorId()
        {
            if (cmbMotorCtrl == null || cmbMotorCtrl.SelectedIndex < 0) return -1;
            string item = cmbMotorCtrl.SelectedItem.ToString();
            if (item.StartsWith("M"))
                return Ojw.CConvert.StrToInt(item.Substring(1));
            return -1;
        }

        /// <summary>현재 선택된 모터의 각도를 UI에 반영</summary>
        private void RefreshMotorAngle()
        {
            if (m_C3d == null) return;
            int motorId = GetSelectedMotorId();
            if (motorId < 0) return;

            float angle = m_C3d.GetData(motorId);
            txtAngleCtrl.Text = angle.ToString("F1");
            int trkVal = (int)(angle * 10);
            if (trkVal < trkAngle.Minimum) trkVal = trkAngle.Minimum;
            if (trkVal > trkAngle.Maximum) trkVal = trkAngle.Maximum;
            trkAngle.Value = trkVal;
            lblAngleInfo.Text = String.Format("Current: {0:F1}°", angle);
        }

        /// <summary>콤보박스 인덱스 → CallInverse nType 매핑
        /// 0: Ojw CCD-IK        → nType=1
        /// 1: FABRIK (Paper)    → nType=6
        /// 2: Jacobian DLS      → nType=11
        /// 3: Jacobian + Tool   → nType=12
        /// 4: Formula Editor    → nType=0
        /// 5: TRAC-IK (ROS)     → nType=2
        /// 6: Paper CCD         → nType=3
        /// 7: WangChen CCD      → nType=4
        /// 8: Kenwright CCD     → nType=5
        /// 9: Paper Jacobian DLS (3xN)      → nType=7
        /// 10: Paper Jacobian Euler (6xN)   → nType=8
        /// 11: Jacobian + Tool Global       → nType=13
        /// </summary>
        private int MapIkComboIndexToType(int sel)
        {
            switch (sel)
            {
                case 0:  return 1;   // Ojw CCD-IK
                case 1:  return 6;   // Paper FABRIK
                case 2:  return 11;  // Jacobian DLS (legacy)
                case 3:  return 12;  // Jacobian + Tool
                case 4:  return 0;   // Formula Editor
                case 5:  return 2;   // TRAC-IK
                case 6:  return 3;   // Paper CCD
                case 7:  return 4;   // WangChen CCD
                case 8:  return 5;   // Kenwright CCD
                case 9:  return 7;   // Paper Jacobian DLS (3xN)
                case 10: return 8;   // Paper Jacobian Euler (6xN)
                case 11: return 13;  // Jacobian + Tool Global
                default: return 1;
            }
        }

        /// <summary>IK 알고리즘 변경 — Go 버튼과 마우스 드래그 양쪽에 적용</summary>
        private void cmbCalcInvMode_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (m_C3d == null) return;
            int sel = cmbCalcInvMode.SelectedIndex;
            int nType = MapIkComboIndexToType(sel);

            // 기존 CalcInv 내부 알고리즘(CCD/FABRIK)도 동기화 (sel 0, 1에 해당)
            if (sel == 0) m_C3d.CalcInv_SetIKAlgorithm(0);
            else if (sel == 1) m_C3d.CalcInv_SetIKAlgorithm(1);

            // 드래그 IK 타입도 콤보 선택에 맞춰 변경 (12종 전부 대응)
            m_C3d.SetDragIKType(nType);
        }

