        /// <summary>IK 계산 성공 시 3D에서 각 모터의 현재 각도 수집 (bool 반환 IK용)</summary>
        private float[] CollectAnglesFromC3d(int[] motorIds, bool bSuccess)
        {
            if (!bSuccess || motorIds == null) return null;
            var angles = new float[motorIds.Length];
            for (int i = 0; i < motorIds.Length; i++)
                angles[i] = m_C3d.GetData(motorIds[i]);
            return angles;
        }

        /// <summary>Go (IK): 좌표 → 각도 계산 (선택된 알고리즘 사용)</summary>
        private void btnGoIk_Click(object sender, EventArgs e)
        {
            if (m_C3d == null) return;

            int funcNum = GetSelectedFuncNum();
            float fX = Ojw.CConvert.StrToFloat(txtIkX.Text);
            float fY = Ojw.CConvert.StrToFloat(txtIkY.Text);
            float fZ = Ojw.CConvert.StrToFloat(txtIkZ.Text);

            int ikType = cmbCalcInvMode.SelectedIndex;
            // 매핑: MapIkComboIndexToType (0~11 index → 0~13 nType)

            try
            {
                int[] motorIds = m_C3d.CalcInv_MotorIDs(funcNum);
                bool bSuccess = false;
                float[] angles = null;
                string algName = cmbCalcInvMode.SelectedItem.ToString();

                switch (ikType)
                {
                    case 0: // Ojw CCD-IK (기존 CalcInv + CCD 알고리즘)
                        m_C3d.CalcInv_SetIKAlgorithm(0);
                        angles = m_C3d.CalcInv(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 1: // FABRIK (Paper)
                        angles = m_C3d.PaperFABRIK(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 2: // Jacobian DLS (legacy)
                        bSuccess = Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosOnly(
                            ref m_C3d, funcNum, fX, fY, fZ,
                            100, 0.1f, 0.01f, 0.5f, 1.0f, 5.0f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;

                    case 3: // Jacobian + Tool (손목)
                        bSuccess = Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosWithTool(
                            ref m_C3d, funcNum, fX, fY, fZ,
                            0, 0, 0, 0,   // rx, ry, rz, toolLength (기본값)
                            100, 0.1f, 0.01f, 0.5f, 1.0f, 5.0f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;

                    case 4: // Formula Editor (사용자 수식)
                        angles = m_C3d.CalcInv(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 5: // TRAC-IK (ROS, DLS-RR + LM dual solver)
                        //   반복 1000 → 150: 도달 불가 좌표에서 완주 시간이 지배적이었음.
                        //   DLS 는 통상 50 반복 내 수렴/포기가 갈려 품질 손실 미미 (2026-08-13)
                        bSuccess = m_C3d.TracIK(funcNum, fX, fY, fZ, 150, 0.1f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;

                    case 6: // Probe CCD (구 "Paper CCD-IK" / Wang-Chen damping 0.5)
                        angles = m_C3d.PaperCCDIK(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 7: // WangChen CCD (원본)
                        angles = m_C3d.WangChenCCDIK(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 8: // Kenwright CCD (comfort factor)
                        angles = m_C3d.KenwrightCCDIK(funcNum, fX, fY, fZ);
                        bSuccess = (angles != null);
                        break;

                    case 9: // Paper Jacobian DLS PosOnly (3xN)
                        bSuccess = m_C3d.PaperJacobianDLS(funcNum, fX, fY, fZ, 100, 0.1f, 0.01f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;

                    case 10: // Paper Jacobian Euler (6xN, 위치+자세)
                        bSuccess = m_C3d.PaperJacobianEuler(funcNum, fX, fY, fZ,
                            0, 0, 0, 100, 0.1f, 0.01f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;

                    case 11: // Jacobian + Tool Global
                        bSuccess = Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosWithToolGlobal(
                            ref m_C3d, funcNum, fX, fY, fZ,
                            0, 0, 0, 0,
                            100, 0.1f, 0.01f, 0.5f, 1.0f, 5.0f);
                        angles = CollectAnglesFromC3d(motorIds, bSuccess);
                        break;
                }

                if (bSuccess && angles != null && motorIds != null)
                {
                    string result = "";
                    for (int i = 0; i < motorIds.Length && i < angles.Length; i++)
                        result += String.Format("[M{0}]={1:F1}\u00b0 ", motorIds[i], angles[i]);
                    lblStatus.Text = algName + " result: " + result;
                    lblCurrentValue.Text = String.Format("({0}, {1}, {2})", fX, fY, fZ);
                }
                else
                {
                    lblStatus.Text = algName + " calculation failed (check formula number)";
                }
            }
            catch (Exception ex)
            {
                lblStatus.Text = "IK error: " + ex.Message;
            }

            RefreshMotorAngle();
        }

        /// <summary>Get (FK): 현재 각도 → 끝점 좌표 읽기</summary>
        private void btnGetFk_Click(object sender, EventArgs e)
        {
            if (m_C3d == null) return;

            int funcNum = GetSelectedFuncNum();
            float fX, fY, fZ;

            try
            {
                m_C3d.CalcF(funcNum, true, out fX, out fY, out fZ);
                txtIkX.Text = Ojw.CConvert.FloatToStr(fX);
                txtIkY.Text = Ojw.CConvert.FloatToStr(fY);
                txtIkZ.Text = Ojw.CConvert.FloatToStr(fZ);
                lblStatus.Text = String.Format("FK result: X={0:F1} Y={1:F1} Z={2:F1}", fX, fY, fZ);
                lblCurrentValue.Text = String.Format("({0:F1}, {1:F1}, {2:F1})", fX, fY, fZ);
            }
            catch (Exception ex)
            {
                lblStatus.Text = "FK error: " + ex.Message;
            }
        }

