        /// <summary>수식번호 변경 → 모터 목록 갱신</summary>
        private void cmbFuncNum_SelectedIndexChanged(object sender, EventArgs e)
        {
            UpdateMotorList();
        }

        /// <summary>선택된 수식번호 가져오기</summary>
        private int GetSelectedFuncNum()
        {
            if (cmbFuncNum == null || cmbFuncNum.SelectedIndex < 0) return 0;
            string item = cmbFuncNum.SelectedItem.ToString();
            // "0: Chain0(M1,M2)" 형식에서 숫자 추출
            int colonIdx = item.IndexOf(':');
            if (colonIdx > 0)
                return Ojw.CConvert.StrToInt(item.Substring(0, colonIdx).Trim());
            return Ojw.CConvert.StrToInt(item.Trim());
        }

        /// <summary>수식 콤보 갱신 (MakeAll 완료 후 호출)</summary>
        private void UpdateFormulaCombo()
        {
            if (cmbFuncNum == null || m_C3d == null) return;

            int prevFunc = GetSelectedFuncNum();
            cmbFuncNum.Items.Clear();

            if (m_lstFormulaGroups == null || m_lstFormulaGroups.Count <= 1)
            {
                // 단일 체인: "0: All"
                cmbFuncNum.Items.Add("0: \uc804\uccb4");
            }
            else
            {
                // 멀티 체인: 각 체인 + 전체
                for (int i = 0; i < m_lstFormulaGroups.Count; i++)
                {
                    // 이 체인의 모터 목록 수집
                    string motorStr = "";
                    try
                    {
                        int[] mids = m_C3d.CalcInv_MotorIDs(i);
                        if (mids != null && mids.Length > 0)
                        {
                            List<string> ms = new List<string>();
                            for (int j = 0; j < mids.Length; j++) ms.Add("M" + mids[j]);
                            motorStr = string.Join(",", ms.ToArray());
                        }
                    }
                    catch { }
                    string name = (motorStr.Length > 0)
                        ? string.Format("{0}: {1}({2})", i, m_lstFormulaGroups[i].Name, motorStr)
                        : string.Format("{0}: {1}", i, m_lstFormulaGroups[i].Name);
                    cmbFuncNum.Items.Add(name);
                }
                // 전체 수식
                cmbFuncNum.Items.Add(m_lstFormulaGroups.Count + ": \uc804\uccb4");
            }

            // 기본값: "전체" = 마지막 항목
            cmbFuncNum.SelectedIndex = cmbFuncNum.Items.Count - 1;
        }

        // ========================================
        // 모드 전환
        // ========================================
        private void rbMode()//(int nMode)
        {
            if (rdModeMouse.Checked)
            {
                m_eMode = InteractionMode.Mouse;
                m_eCurrentAction = BuildAction.None;
                if (m_C3d != null) m_C3d.SetMouseMode(99);
                lblStatus.Text = "Click 3D axis to start";
                lblCurrentValue.Text = "";
                UpdateModeUI();
            }
            else if (rdModeHybrid.Checked) // Hybrid
            {
                m_eMode = InteractionMode.Hybrid;
                m_eCurrentAction = BuildAction.None;
                if (m_C3d != null) m_C3d.SetMouseMode(0); // 카메라 제어 활성화
                lblStatus.Text = "Select axis, then drag";
                lblCurrentValue.Text = "";
                UpdateModeUI();
            }
            else // rdModeButton.Checked
            {
                m_eMode = InteractionMode.Button;
                m_eCurrentAction = BuildAction.None;
                if (m_C3d != null) m_C3d.SetMouseMode(0); // 카메라 제어 활성화
                lblStatus.Text = "Enter value and click axis button";
                lblCurrentValue.Text = "";
                UpdateModeUI();
            }
        }
        private void rdModeMouse_CheckedChanged(object sender, EventArgs e)  { if (rdModeMouse.Checked)  { rbMode(); } }
        private void rdModeButton_CheckedChanged(object sender, EventArgs e) { if (rdModeButton.Checked) { rbMode(); } }
        private void rdModeHybrid_CheckedChanged(object sender, EventArgs e) { if (rdModeHybrid.Checked) { rbMode(); } }

        private void tabRight_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (tabRight.SelectedTab == tabCreate)
            {
                // 첫 번째 탭(생성/디자인): rdModeMouse/Button/Hybrid 라디오 따라가기
                if (rdModeMouse.Checked)
                {
                    m_eMode = InteractionMode.Mouse;
                    if (m_C3d != null) m_C3d.SetMouseMode(99);
                }
                else if (rdModeButton.Checked)
                {
                    m_eMode = InteractionMode.Button;
                    if (m_C3d != null) m_C3d.SetMouseMode(0);
                }
                else if (rdModeHybrid.Checked)
                {
                    m_eMode = InteractionMode.Hybrid;
                    if (m_C3d != null) m_C3d.SetMouseMode(0);
                }
                m_eCurrentAction = BuildAction.None;
                UpdateModeUI();
            }
            else
            {
                // 그 외 탭(Control/History/Playback): Control 탭의 rdMouseCam/rdMouseJoint 따라가기
                if (tabRight.SelectedTab == tabTest)
                {
                    m_eMode = InteractionMode.Control;
                    UpdateMotorList();
                }
                m_eCurrentAction = BuildAction.None;
                if (m_C3d != null)
                    m_C3d.SetMouseMode(rdMouseJoint.Checked ? 1 : 0);
            }
        }

        private void UpdateModeUI()
        {
            bool bButton = (m_eMode == InteractionMode.Button);

            // 입력 영역 (생성 탭 내 서브모드)
            lblMoveInput.Visible = bButton;
            txtMoveValue.Visible = bButton;
            lblRotateInput.Visible = bButton;
            txtRotateValue.Visible = bButton;
            pnDragArea.Visible = (m_eMode == InteractionMode.Hybrid);
        }

        // ========================================
        // 축 버튼 클릭 (모드별 분기)
        // ========================================
        private void HandleAxisButton(BuildAction action, string axisName)
        {
            switch (m_eMode)
            {
                case InteractionMode.Mouse:
                    // 축 선택 → 3D 드래그 대기
                    m_eCurrentAction = action;
                    lblStatus.Text = "Click 3D axis (" + axisName + ")";
                    lblCurrentValue.Text = "0";
                    break;

                case InteractionMode.Button:
                    // 이동/회전에 따라 다른 입력창에서 값 읽기
                    bool isRotAction = DhBuilder.IsRotation(action);
                    string inputText = isRotAction ? txtRotateValue.Text : txtMoveValue.Text;
                    float value;
                    if (!float.TryParse(inputText, out value))
                    {
                        lblStatus.Text = "Enter a number!";
                        return;
                    }
                    if (value == 0)
                    {
                        lblStatus.Text = "Enter non-zero value!";
                        return;
                    }

                    // STL 선택 시: STL 오프셋/회전 직접 수정
                    int stlIdx = GetSelectedStlStepIndex();
                    if (stlIdx >= 0)
                    {
                        DhStep stlStep = m_Builder.GetStep(stlIdx);
                        DhBuilder.ApplyStlDelta(stlStep, action, value);
                        UpdatePreview(null);
                        bool isRotS = DhBuilder.IsRotation(action);
                        string unit = isRotS ? "deg" : "mm";
                        lblStatus.Text = string.Format("STL {0} {1:+0;-0}{2}",
                            DhBuilder.GetAxisName(action), value, unit);
                        lblCurrentValue.Text = string.Format("{0}{1}", (int)value, unit);
                        break;
                    }

                    DhStep step = DhBuilder.CreateStep(action, value);
                    m_Builder.AddStep(step);
                    RefreshHistory();
                    UpdatePreview(null);
                    lblStatus.Text = step.Description + " added";
                    bool isRot = DhBuilder.IsRotation(action);
                    lblCurrentValue.Text = string.Format("{0}{1}", (int)value, isRot ? "deg" : "mm");
                    break;

                case InteractionMode.Hybrid:
                    // 축 선택 → 드래그 영역 대기
                    m_eCurrentAction = action;
                    lblStatus.Text = "Drag area (" + axisName + ")";
                    lblCurrentValue.Text = "0";
                    break;
            }
        }

