        private void btnMotor_Click(object sender, EventArgs e)
        {
            int motorNum;
            if (cmbMotorId.SelectedIndex <= 0) // "Auto" 또는 미선택
                motorNum = m_Builder.GetNextMotorNumber();
            else
                motorNum = cmbMotorId.SelectedIndex - 1; // "0"=idx1, "1"=idx2, ...

            DhStep step = DhBuilder.CreateStep(BuildAction.Motor, 0, motorNum);
            m_Builder.AddStep(step);
            RefreshHistory();
            UpdatePreview(null);
            lblStatus.Text = string.Format("Joint M{0} added", motorNum);

            // 다음 ID로 자동 증가 (콤보 범위 내에서)
            int nextIdx = motorNum + 2; // motorNum+1 → 콤보 idx (0=자동, 1="0", 2="1", ...)
            if (nextIdx < cmbMotorId.Items.Count)
                cmbMotorId.SelectedIndex = nextIdx;
        }

