        // ========================================
        // STL 추가 (버튼 확인 방식 - 3D 클릭 불필요)
        // ========================================
        private void btnStl_Click(object sender, EventArgs e)
        {
            using (OpenFileDialog dlg = new OpenFileDialog())
            {
                dlg.Filter = "STL files|*.stl|All files|*.*";
                dlg.Title = "Select STL File";
                if (dlg.ShowDialog() != DialogResult.OK) return;

                try
                {
                    string destName = CopyStlToFolder(dlg.FileName);

                    // 오프셋 없이 바로 추가
                    DhStep step = DhBuilder.CreateStlStep(destName, 0, 0, 0);
                    m_Builder.AddStep(step);
                    RefreshHistory();
                    UpdatePreview(null);
                    lblStatus.Text = step.Description + " added";
                }
                catch (Exception ex)
                {
                    MessageBox.Show("STL file read error: " + ex.Message, "Error",
                        MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }

        /// <summary>
        /// STL 파일을 stl/ 폴더로 복사하고 실제 저장된 파일명 반환
        /// </summary>
        private string CopyStlToFolder(string srcPath)
        {
            string stlDir = Path.Combine(Application.StartupPath, "stl");
            if (!Directory.Exists(stlDir))
                Directory.CreateDirectory(stlDir);
            string destName = Path.GetFileName(srcPath);
            string destPath = Path.Combine(stlDir, destName);
            string srcFull = Path.GetFullPath(srcPath);
            string dstFull = Path.GetFullPath(destPath);

            // 소스가 이미 stl 폴더에 있으면 복사 불필요
            if (srcFull.Equals(dstFull, StringComparison.OrdinalIgnoreCase))
                return destName;

            try
            {
                File.Copy(srcPath, destPath, true);
            }
            catch (IOException)
            {
                // C3d가 파일을 잡고 있으면 다른 이름으로 복사
                string nameOnly = Path.GetFileNameWithoutExtension(destName);
                string ext = Path.GetExtension(destName);
                bool copied = false;
                for (int i = 1; i < 100; i++)
                {
                    destName = string.Format("{0}_{1}{2}", nameOnly, i, ext);
                    destPath = Path.Combine(stlDir, destName);
                    try
                    {
                        File.Copy(srcPath, destPath, true);
                        copied = true;
                        break;
                    }
                    catch (IOException) { }
                }
                if (!copied) throw;
            }
            return destName;
        }

        /// <summary>
        /// STL 면 하이라이트 (레이캐스트 위임). btnStlCenter 등에서 호출.
        /// </summary>
        private void HighlightStlFace(int idx, int mouseX = -1, int mouseY = -1)
        {
            if (mouseX < 0) mouseX = pnDisp.Width / 2;
            if (mouseY < 0) mouseY = pnDisp.Height / 2;
            TrySelectStlFace(mouseX, mouseY);
        }

        /// <summary>
        /// Fusion 360 스타일 면 선택: 마우스 위치에서 3D 레이를 쏘아
        /// STL 삼각형 히트 → 동일 법선 인접 삼각형으로 면 확장 → 빨간색 하이라이트.
        /// C3d 피킹 시스템 불필요 (독립적 레이캐스트).
        /// </summary>
        private bool TrySelectStlFace(int mouseX, int mouseY)
        {
            if (m_C3d == null) return false;

            // gluUnProject 기반 정확한 raycast (GetOrthoRay 보다 카메라 행렬 정확 반영)
            double wox, woy, woz, wdx, wdy, wdz;
            if (!m_C3d.ScreenToWorldRay(mouseX, mouseY,
                out wox, out woy, out woz, out wdx, out wdy, out wdz))
            {
                // fallback: 기존 GetOrthoRay
                m_C3d.GetOrthoRay(mouseX, mouseY, pnDisp.Width, pnDisp.Height,
                    out wox, out woy, out woz, out wdx, out wdy, out wdz);
            }

            // 모든 STL 스텝에 대해 레이캐스트
            int bestStepIdx = -1;
            int bestTriIdx = -1;
            float bestT = float.MaxValue;
            StlBoundingBox bestBbox = null;
            float bestOffX = 0, bestOffY = 0, bestOffZ = 0;
            float bestPan = 0, bestTilt = 0, bestSwing = 0;

            for (int i = 0; i < m_Builder.StepCount; i++)
            {
                DhStep step = m_Builder.GetStep(i);
                if (step.Action != BuildAction.Stl) continue;

                // 신형 DH 형식 (`[ ]` 포함) 도 파싱 가능하도록 괄호 제거 후 split.
                string dhLine = step.DhLines.TrimStart('@').Replace("[", "").Replace("]", "");
                string[] parts = dhLine.Split(',');
                if (parts.Length < 1) continue;
                string stlFilename = parts[0].Trim();

                string stlPath = Path.Combine(Application.StartupPath, "stl", stlFilename);
                StlBoundingBox bbox;
                try { bbox = StlParser.Parse(stlPath); }
                catch { continue; }
                if (!bbox.IsValid) continue;

                float offX = 0, offY = 0, offZ = 0;
                float stlPan = 0, stlTilt = 0, stlSwing = 0;
                if (parts.Length >= 8)
                {
                    float.TryParse(parts[5], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offX);
                    float.TryParse(parts[6], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offY);
                    float.TryParse(parts[7], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offZ);
                }
                if (parts.Length >= 11)
                {
                    float.TryParse(parts[8], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlPan);
                    float.TryParse(parts[9], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlTilt);
                    float.TryParse(parts[10], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlSwing);
                }

                // 레이를 STL 로컬 좌표계로 변환
                // 렌더링: DH_chain * Translate(off) * Rz(swing) * Rx(tilt) * Ry(pan) * vertex
                // 역변환: Ry(-pan) * Rx(-tilt) * Rz(-swing) * (Re^T * (ray - endpoint) - offset)
                double epx, epy, epz;
                m_Builder.GetEndpointPosition(i, out epx, out epy, out epz);
                double[,] Re = m_Builder.GetEndpointRotation(i);

                double dxw = wox - epx, dyw = woy - epy, dzw = woz - epz;

                // Re^T * (ray - endpoint) - offset → endpoint 로컬 좌표
                float eox = (float)(Re[0, 0] * dxw + Re[1, 0] * dyw + Re[2, 0] * dzw) - offX;
                float eoy = (float)(Re[0, 1] * dxw + Re[1, 1] * dyw + Re[2, 1] * dzw) - offY;
                float eoz = (float)(Re[0, 2] * dxw + Re[1, 2] * dyw + Re[2, 2] * dzw) - offZ;

                float edx = (float)(Re[0, 0] * wdx + Re[1, 0] * wdy + Re[2, 0] * wdz);
                float edy = (float)(Re[0, 1] * wdx + Re[1, 1] * wdy + Re[2, 1] * wdz);
                float edz = (float)(Re[0, 2] * wdx + Re[1, 2] * wdy + Re[2, 2] * wdz);

                // STL 회전 역변환: Rm^T * (endpoint_local)
                // Rm = Rz(swing) * Rx(tilt) * Ry(pan) (OjwRotation 적용 순서)
                float lox = eox, loy = eoy, loz = eoz;
                float ldx = edx, ldy = edy, ldz = edz;
                if (stlSwing != 0 || stlTilt != 0 || stlPan != 0)
                {
                    double[,] Rm = DhBuilder.StlLocalRotation(stlPan, stlTilt, stlSwing);
                    // Rm^T * vector
                    lox = (float)(Rm[0, 0] * eox + Rm[1, 0] * eoy + Rm[2, 0] * eoz);
                    loy = (float)(Rm[0, 1] * eox + Rm[1, 1] * eoy + Rm[2, 1] * eoz);
                    loz = (float)(Rm[0, 2] * eox + Rm[1, 2] * eoy + Rm[2, 2] * eoz);
                    ldx = (float)(Rm[0, 0] * edx + Rm[1, 0] * edy + Rm[2, 0] * edz);
                    ldy = (float)(Rm[0, 1] * edx + Rm[1, 1] * edy + Rm[2, 1] * edz);
                    ldz = (float)(Rm[0, 2] * edx + Rm[1, 2] * edy + Rm[2, 2] * edz);
                }

                int hitTri = StlParser.RaycastMesh(bbox, lox, loy, loz, ldx, ldy, ldz);
                if (hitTri < 0) continue;

                // 히트 거리 계산 (여러 STL 간 비교용)
                int b = hitTri * 9;
                float t = StlParser.RayTriangleIntersect(lox, loy, loz, ldx, ldy, ldz,
                    bbox.Vertices[b], bbox.Vertices[b + 1], bbox.Vertices[b + 2],
                    bbox.Vertices[b + 3], bbox.Vertices[b + 4], bbox.Vertices[b + 5],
                    bbox.Vertices[b + 6], bbox.Vertices[b + 7], bbox.Vertices[b + 8]);

                if (t < bestT)
                {
                    bestT = t;
                    bestStepIdx = i;
                    bestTriIdx = hitTri;
                    bestBbox = bbox;
                    bestOffX = offX;
                    bestOffY = offY;
                    bestOffZ = offZ;
                    bestPan = stlPan;
                    bestTilt = stlTilt;
                    bestSwing = stlSwing;
                }
            }

            if (bestStepIdx < 0) return false;

            // 히스토리에서 해당 항목 선택
            if (bestStepIdx < lstHistory.Items.Count)
                lstHistory.SelectedIndex = bestStepIdx;

            // FloodFillFace — 클릭 위치 인접 영역만 묶음. mateFaces 의 center 가
            // 사용자 클릭 위치 근처로 나옴 (떨어진 같은 평면 영역을 묶지 않음).
            // (AnalyzePlanes 는 모든 분산된 영역을 묶어서 center 가 클릭 위치와 멀어졌음)
            List<int> faceTris = StlParser.FloodFillFace(bestBbox, bestTriIdx);
            if (faceTris.Count == 0) return false;
            // 구멍 근처 클릭 시 구멍 경계 삼각형만 분리
            faceTris = StlParser.FilterHoleNearbyTris(bestBbox, faceTris, bestTriIdx);

            // 하이라이트 STL 파일 생성
            string hlName = "_highlight.stl";
            string highlightPath = Path.Combine(Application.StartupPath, "stl", hlName);
            m_C3d.OjwAse_InvalidateCache(hlName);

            int triCount = StlParser.WriteClusterStl(bestBbox, faceTris, highlightPath);

            // 빨강 highlight 는 스냅/Face Align 모드일 때만 표시 — 일반 클릭은 highlight 없음.
            if (triCount > 0 && (m_bMergeMode || m_bFaceSnapMode))
            {
                string overlayLine = string.Format(
                    System.Globalization.CultureInfo.InvariantCulture,
                    "@{0},16711680,1.0,9,0,{1:F3},{2:F3},{3:F3},{4:F1},{5:F1},{6:F1}",
                    hlName, bestOffX, bestOffY, bestOffZ, bestPan, bestTilt, bestSwing);
                m_Builder.SetOverlay(bestStepIdx, overlayLine);
            }

            // 면 중심 및 법선 저장 (btnStlCenter에서 사용)
            float cx, cy, cz;
            StlParser.GetClusterCentroid(bestBbox, faceTris, out cx, out cy, out cz);

            float nx, ny, nz;
            StlParser.GetTriangleNormal(bestBbox, bestTriIdx, out nx, out ny, out nz);

            m_nSelectedStlFace = DhBuilder.DetermineBBFace(nx, ny, nz);
            m_fSelectedFaceCenterX = cx;
            m_fSelectedFaceCenterY = cy;
            m_fSelectedFaceCenterZ = cz;
            m_fSelectedFaceNormalX = nx;
            m_fSelectedFaceNormalY = ny;
            m_fSelectedFaceNormalZ = nz;
            m_nSelectedStlHistoryIdx = bestStepIdx;
            m_lstSelectedFaceTris = faceTris;
            m_SelectedFaceBbox = bestBbox;

            DhStep hitStep = m_Builder.GetStep(bestStepIdx);
            string filename = hitStep.DhLines.TrimStart('@').Replace("[", "").Replace("]", "").Split(',')[0].Trim();

            UpdatePreview(null, true);
            lblStatus.Text = string.Format("{0} → face selected ({1} triangles)", filename, triCount);
            lblCurrentValue.Text = string.Format("Center ({0:F1}, {1:F1}, {2:F1})", cx, cy, cz);
            return true;
        }

        /// <summary>
        /// 마우스 호버 시 STL 면의 경계 에지를 표시.
        /// TrySelectStlFace와 동일한 레이캐스트 후 에지 하이라이트 STL 생성.
        /// </summary>
        private void TryHoverStlFace(int mouseX, int mouseY)
        {
            if (m_C3d == null) return;

            // gluUnProject 기반 정확한 raycast (GetOrthoRay 보다 카메라 행렬 정확 반영)
            double wox, woy, woz, wdx, wdy, wdz;
            if (!m_C3d.ScreenToWorldRay(mouseX, mouseY,
                out wox, out woy, out woz, out wdx, out wdy, out wdz))
            {
                // fallback: 기존 GetOrthoRay
                m_C3d.GetOrthoRay(mouseX, mouseY, pnDisp.Width, pnDisp.Height,
                    out wox, out woy, out woz, out wdx, out wdy, out wdz);
            }

            // 디버그: 레이-바닥면(Z=0) 교차점을 십자선 위치로 저장
            if (Math.Abs(wdz) > 1e-6)
            {
                double tHit = -woz / wdz;
                m_fDbgWorldX = (float)(wox + wdx * tHit);
                m_fDbgWorldY = (float)(woy + wdy * tHit);
                m_fDbgWorldZ = 0;
                m_bDbgShowCrosshair = true;
            }

            int bestStepIdx = -1;
            int bestTriIdx = -1;
            float bestT = float.MaxValue;
            StlBoundingBox bestBbox = null;
            float bestOffX = 0, bestOffY = 0, bestOffZ = 0;
            float bestPan = 0, bestTilt = 0, bestSwing = 0;

            for (int i = 0; i < m_Builder.StepCount; i++)
            {
                DhStep step = m_Builder.GetStep(i);
                if (step.Action != BuildAction.Stl) continue;

                // 신형 DH 형식 (`[ ]` 포함) 도 파싱 가능하도록 괄호 제거 후 split.
                string dhLine = step.DhLines.TrimStart('@').Replace("[", "").Replace("]", "");
                string[] parts = dhLine.Split(',');
                if (parts.Length < 1) continue;
                string stlFilename = parts[0].Trim();

                string stlPath = Path.Combine(Application.StartupPath, "stl", stlFilename);
                StlBoundingBox bbox;
                try { bbox = StlParser.Parse(stlPath); }
                catch { continue; }
                if (!bbox.IsValid) continue;

                float offX = 0, offY = 0, offZ = 0;
                float stlPan = 0, stlTilt = 0, stlSwing = 0;
                if (parts.Length >= 8)
                {
                    float.TryParse(parts[5], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offX);
                    float.TryParse(parts[6], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offY);
                    float.TryParse(parts[7], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out offZ);
                }
                if (parts.Length >= 11)
                {
                    float.TryParse(parts[8], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlPan);
                    float.TryParse(parts[9], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlTilt);
                    float.TryParse(parts[10], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out stlSwing);
                }

                double epx, epy, epz;
                m_Builder.GetEndpointPosition(i, out epx, out epy, out epz);
                double[,] Re = m_Builder.GetEndpointRotation(i);

                double dxw2 = wox - epx, dyw2 = woy - epy, dzw2 = woz - epz;

                // Re^T * (ray - endpoint) - offset → endpoint 로컬 좌표
                float eox = (float)(Re[0, 0] * dxw2 + Re[1, 0] * dyw2 + Re[2, 0] * dzw2) - offX;
                float eoy = (float)(Re[0, 1] * dxw2 + Re[1, 1] * dyw2 + Re[2, 1] * dzw2) - offY;
                float eoz = (float)(Re[0, 2] * dxw2 + Re[1, 2] * dyw2 + Re[2, 2] * dzw2) - offZ;

                float edx = (float)(Re[0, 0] * wdx + Re[1, 0] * wdy + Re[2, 0] * wdz);
                float edy = (float)(Re[0, 1] * wdx + Re[1, 1] * wdy + Re[2, 1] * wdz);
                float edz = (float)(Re[0, 2] * wdx + Re[1, 2] * wdy + Re[2, 2] * wdz);

                // STL 회전 역변환: Rm^T * (endpoint_local)
                float lox = eox, loy = eoy, loz = eoz;
                float ldx = edx, ldy = edy, ldz = edz;
                if (stlSwing != 0 || stlTilt != 0 || stlPan != 0)
                {
                    double[,] Rm = DhBuilder.StlLocalRotation(stlPan, stlTilt, stlSwing);
                    lox = (float)(Rm[0, 0] * eox + Rm[1, 0] * eoy + Rm[2, 0] * eoz);
                    loy = (float)(Rm[0, 1] * eox + Rm[1, 1] * eoy + Rm[2, 1] * eoz);
                    loz = (float)(Rm[0, 2] * eox + Rm[1, 2] * eoy + Rm[2, 2] * eoz);
                    ldx = (float)(Rm[0, 0] * edx + Rm[1, 0] * edy + Rm[2, 0] * edz);
                    ldy = (float)(Rm[0, 1] * edx + Rm[1, 1] * edy + Rm[2, 1] * edz);
                    ldz = (float)(Rm[0, 2] * edx + Rm[1, 2] * edy + Rm[2, 2] * edz);
                }

                int hitTri = StlParser.RaycastMesh(bbox, lox, loy, loz, ldx, ldy, ldz);
                if (hitTri < 0) continue;

                int b = hitTri * 9;
                float t = StlParser.RayTriangleIntersect(lox, loy, loz, ldx, ldy, ldz,
                    bbox.Vertices[b], bbox.Vertices[b + 1], bbox.Vertices[b + 2],
                    bbox.Vertices[b + 3], bbox.Vertices[b + 4], bbox.Vertices[b + 5],
                    bbox.Vertices[b + 6], bbox.Vertices[b + 7], bbox.Vertices[b + 8]);

                if (t < bestT)
                {
                    bestT = t;
                    bestStepIdx = i;
                    bestTriIdx = hitTri;
                    bestBbox = bbox;
                    bestOffX = offX;
                    bestOffY = offY;
                    bestOffZ = offZ;
                    bestPan = stlPan;
                    bestTilt = stlTilt;
                    bestSwing = stlSwing;
                }
            }

            if (bestStepIdx < 0)
            {
                // 히트 없음 → 호버 해제 + 십자선 갱신
                bool needRefresh = m_bHoverActive || m_bDbgShowCrosshair || m_bSnapHoverActive;
                if (m_bHoverActive)
                    m_Builder.ClearOverlay();
                m_bHoverActive = false;
                m_bSnapHoverActive = false;   // hover target 화살표도 끔
                if (needRefresh)
                    UpdatePreview(null);
                if (m_bFaceSnapMode && m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = "hover: no hit";
                return;
            }

            // FloodFillFace — 클릭 위치 인접 영역만 (mateFaces center 정확도 위해)
            List<int> faceTris = StlParser.FloodFillFace(bestBbox, bestTriIdx);
            if (faceTris.Count == 0) return;
            faceTris = StlParser.FilterHoleNearbyTris(bestBbox, faceTris, bestTriIdx);

            // 호버 면 STL 생성 (전체 면 채움, edge 아님)
            string faceName = "_hover_face.stl";
            string facePath = Path.Combine(Application.StartupPath, "stl", faceName);
            m_C3d.OjwAse_InvalidateCache(faceName);
            int faceCount = StlParser.WriteClusterStl(bestBbox, faceTris, facePath);
            if (faceCount > 0)
            {
                // 본 STL 색상의 RGB 보색을 만들고 채도를 최대로 강화.
                // 회색 (R=G=B) 같은 무채색 STL 은 보색도 무채색이라 강조 약함.
                // → 가장 큰 채널을 255 로 정규화 → 항상 채도 높은 색.
                int origColor = 0;
                DhStep bestStep = m_Builder.GetStep(bestStepIdx);
                string bestRaw = bestStep.DhLines.TrimStart('@').Replace("[", "").Replace("]", "");
                string[] bestParts = bestRaw.Split(',');
                if (bestParts.Length > 1)
                    int.TryParse(bestParts[1].Trim(), System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out origColor);
                int rgb = origColor & 0xFFFFFF;
                int compRgb = 0xFFFFFF ^ rgb;
                int rC = (compRgb >> 16) & 0xFF;
                int gC = (compRgb >> 8) & 0xFF;
                int bC = compRgb & 0xFF;
                int maxC = Math.Max(rC, Math.Max(gC, bC));
                int minC = Math.Min(rC, Math.Min(gC, bC));
                // 무채색 (회색) 검출: R=G=B 면 보색도 회색이라 본색 위에서 잘 안 보임
                //   → 본색의 밝기에 따라 대비되는 색으로 강제
                if (maxC == minC)
                {
                    // 본색이 어두우면 (예: 검정) 보색이 밝음 (흰색). maxC == minC == 255.
                    // 본색이 밝으면 (예: 흰색) 보색이 어두움 (검정). maxC == minC == 0.
                    // 중간 회색이면 보색도 중간 회색 → 잘 안 보임. 본색의 밝기 보고 결정:
                    int origMax = Math.Max((rgb >> 16) & 0xFF,
                                  Math.Max((rgb >> 8) & 0xFF, rgb & 0xFF));
                    if (origMax > 127) { rC = gC = bC = 0; }       // 밝은 무채색 → 검정 hover
                    else { rC = gC = bC = 255; }                   // 어두운 무채색 → 흰색 hover
                }
                else if (maxC < 255)
                {
                    // 채도는 있는데 밝기 부족 → 가장 큰 채널을 255 로 정규화
                    float k = 255.0f / maxC;
                    rC = Math.Min(255, (int)(rC * k));
                    gC = Math.Min(255, (int)(gC * k));
                    bC = Math.Min(255, (int)(bC * k));
                }
                compRgb = (rC << 16) | (gC << 8) | bC;
                string overlayLine = string.Format(
                    System.Globalization.CultureInfo.InvariantCulture,
                    "@{0},{1},1.0,9,0,{2:F3},{3:F3},{4:F3},{5:F1},{6:F1},{7:F1}",
                    faceName, compRgb, bestOffX, bestOffY, bestOffZ, bestPan, bestTilt, bestSwing);
                m_Builder.SetOverlay(bestStepIdx, overlayLine);
                m_bHoverActive = true;
                // FaceSnap 모드: hover face 의 native normal/center 를 *직접 계산* 후 world 변환.
                // (이전 버그: m_fSelectedFaceNormal 는 클릭 시점 변수 → hover 만 하면 stale)
                float hovNxNat = 0, hovNyNat = 0, hovNzNat = 0;
                if (m_bFaceSnapMode)
                {
                    StlParser.GetTriangleNormal(bestBbox, bestTriIdx, out hovNxNat, out hovNyNat, out hovNzNat);
                    float hcx, hcy, hcz;
                    StlParser.GetClusterCentroid(bestBbox, faceTris, out hcx, out hcy, out hcz);
                    double cwx, cwy, cwz, nwx, nwy, nwz;
                    m_Builder.StlLocalToWorld(bestStepIdx, hcx, hcy, hcz, false, out cwx, out cwy, out cwz);
                    m_Builder.StlLocalToWorld(bestStepIdx, hovNxNat, hovNyNat, hovNzNat,
                        true, out nwx, out nwy, out nwz);
                    double nl = Math.Sqrt(nwx*nwx + nwy*nwy + nwz*nwz);
                    if (nl > 1e-9) { nwx /= nl; nwy /= nl; nwz /= nl; }
                    m_dSnapHovCx = cwx; m_dSnapHovCy = cwy; m_dSnapHovCz = cwz;
                    m_dSnapHovNx = nwx; m_dSnapHovNy = nwy; m_dSnapHovNz = nwz;
                    m_bSnapHoverActive = true;
                }
                UpdatePreview(null, true);
                // FaceSnap 모드에서 hover hit → 패널 표시 (native + world normal 비교)
                if (m_bFaceSnapMode && m_lblSnapStatus != null)
                    m_lblSnapStatus.Text = string.Format(
                        "hover: step #{0} ({1} tris)\r\nnative n=({2:F2},{3:F2},{4:F2})\r\nworld  n=({5:F2},{6:F2},{7:F2})",
                        bestStepIdx, faceTris.Count,
                        hovNxNat, hovNyNat, hovNzNat,
                        m_dSnapHovNx, m_dSnapHovNy, m_dSnapHovNz);
            }
        }

        // DetermineBBFace → DhBuilder.DetermineBBFace 로 이동됨

        /// <summary>
        /// STL 중심이동: 감지된 면의 중심을 DH 끝점에 맞춤
        /// </summary>
        private void btnStlCenter_Click(object sender, EventArgs e)
        {
            int idx = lstHistory.SelectedIndex;
            if (idx < 0)
            {
                MessageBox.Show("Select an STL item from history.", "Info",
                    MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            DhStep step = m_Builder.GetStep(idx);
            if (step.Action != BuildAction.Stl)
            {
                MessageBox.Show("Selected item is not STL.", "Info",
                    MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            // 면이 아직 감지되지 않았으면 지금 감지
            if (m_nSelectedStlHistoryIdx != idx || m_nSelectedStlFace < 0)
                HighlightStlFace(idx);

            if (m_nSelectedStlHistoryIdx != idx || m_nSelectedStlFace < 0)
                return;

            // 파일명 추출
            string stlFilename = step.DhLines.TrimStart('@').Replace("[", "").Replace("]", "").Split(',')[0].Trim();

            // 기존 회전값 보존
            string fnTmp; float oxTmp, oyTmp, ozTmp, curPan, curTilt, curSwing;
            DhBuilder.ParseStlParams(step.DhLines, out fnTmp, out oxTmp, out oyTmp, out ozTmp,
                out curPan, out curTilt, out curSwing);

            // 면 중심을 DH 끝점으로 이동하는 오프셋 적용 (회전은 유지)
            // 렌더링: T(offset) * Rm * vertex → offset = -Rm * face_center
            double[,] Rm = DhBuilder.StlLocalRotation(curPan, curTilt, curSwing);
            float offX = -(float)(Rm[0, 0] * m_fSelectedFaceCenterX + Rm[0, 1] * m_fSelectedFaceCenterY + Rm[0, 2] * m_fSelectedFaceCenterZ);
            float offY = -(float)(Rm[1, 0] * m_fSelectedFaceCenterX + Rm[1, 1] * m_fSelectedFaceCenterY + Rm[1, 2] * m_fSelectedFaceCenterZ);
            float offZ = -(float)(Rm[2, 0] * m_fSelectedFaceCenterX + Rm[2, 1] * m_fSelectedFaceCenterY + Rm[2, 2] * m_fSelectedFaceCenterZ);

            step.DhLines = DhBuilder.BuildStlDhLines(stlFilename, offX, offY, offZ,
                curPan, curTilt, curSwing);

            RefreshHistory();
            UpdatePreview(null);

            string[] faceNames = { "+X", "-X", "+Y", "-Y", "+Z", "-Z" };
            string faceName = m_nSelectedStlFace >= 0 && m_nSelectedStlFace < 6
                ? faceNames[m_nSelectedStlFace] : "";
            lblStatus.Text = string.Format("{0} → {1} face centered", stlFilename, faceName);
        }

        // ========================================
        // STL 면 축 정렬: 선택한 면의 중심을 DH 축 원점으로 이동
        // 원형 특징(구멍, 보스)이 있으면 그 중심을 우선 사용
        // ========================================

        /// <summary>
        /// STL 면 축 정렬 모드 토글
        /// </summary>
        private void btnStlMerge_Click(object sender, EventArgs e)
        {
            if (m_bMergeMode)
            {
                ExitMergeMode();
                return;
            }

            m_bMergeMode = true;
            m_bHoverActive = false;
            m_nLastHoverX = -100;
            m_nLastHoverY = -100;
            m_Builder.ClearOverlay();
            if (m_C3d != null) m_C3d.SetMouseMode(0); // 카메라 제어 활성화
            UpdatePreview(null);
            lblStatus.Text = "Click STL face to align";
            lblCurrentValue.Text = "Face axis align mode";
        }

        private void ExitMergeMode()
        {
            m_bMergeMode = false;
            m_bHoverActive = false;
            m_nLastHoverX = -100;
            m_nLastHoverY = -100;
            m_Builder.ClearOverlay();
            // 마우스 모드 복원
            if (m_C3d != null)
                m_C3d.SetMouseMode(m_eMode == InteractionMode.Mouse ? 99 : 0);
            UpdatePreview(null);
            lblStatus.Text = "Face align cancelled";
            lblCurrentValue.Text = "";
        }

        /// <summary>
        /// 면 클릭 후 축 정렬 처리.
        /// TrySelectStlFace가 성공한 뒤 호출됨.
        /// 선택한 면의 경계에서 원형 특징을 찾아 그 중심으로,
        /// 없으면 면 중심으로 축 원점에 정렬.
        /// </summary>
        private void HandleMergeClick()
        {
            int stepIdx = m_nSelectedStlHistoryIdx;
            if (stepIdx < 0) return;

            DhStep step = m_Builder.GetStep(stepIdx);
            if (step.Action != BuildAction.Stl) return;

            string stlFilename = step.DhLines.TrimStart('@').Replace("[", "").Replace("]", "").Split(',')[0].Trim();

            // TrySelectStlFace에서 저장된 면 삼각형 사용
            if (m_lstSelectedFaceTris != null && m_lstSelectedFaceTris.Count >= 3
                && m_SelectedFaceBbox != null)
            {
                float[] circCenter = StlParser.FindCircularFeatureOnFace(
                    m_SelectedFaceBbox, m_lstSelectedFaceTris, 0.7f);

                if (circCenter != null)
                {
                    ApplyFaceAlignOffset(step, stlFilename,
                        circCenter[0], circCenter[1], circCenter[2],
                        "원형 특징 중심");
                    return;
                }
            }

            // 원형 특징 없음 → 면 중심 사용
            ApplyFaceAlignOffset(step, stlFilename,
                m_fSelectedFaceCenterX, m_fSelectedFaceCenterY, m_fSelectedFaceCenterZ,
                "면 중심");
        }

        /// <summary>
        /// STL 오프셋 적용: 지정된 중심점이 DH 축 원점에 오도록 이동
        /// </summary>
        private void ApplyFaceAlignOffset(DhStep step, string stlFilename,
            float centerX, float centerY, float centerZ, string centerType)
        {
            // 기존 회전값 보존
            string fnTmp; float oxTmp, oyTmp, ozTmp, curPan, curTilt, curSwing;
            DhBuilder.ParseStlParams(step.DhLines, out fnTmp, out oxTmp, out oyTmp, out ozTmp,
                out curPan, out curTilt, out curSwing);

            // 렌더링: T(offset) * Rm * vertex → offset = -Rm * center
            double[,] Rm = DhBuilder.StlLocalRotation(curPan, curTilt, curSwing);
            float offX = -(float)(Rm[0, 0] * centerX + Rm[0, 1] * centerY + Rm[0, 2] * centerZ);
            float offY = -(float)(Rm[1, 0] * centerX + Rm[1, 1] * centerY + Rm[1, 2] * centerZ);
            float offZ = -(float)(Rm[2, 0] * centerX + Rm[2, 1] * centerY + Rm[2, 2] * centerZ);

            step.DhLines = DhBuilder.BuildStlDhLines(stlFilename, offX, offY, offZ,
                curPan, curTilt, curSwing);

            // 정렬 모드 종료
            m_bMergeMode = false;
            m_bHoverActive = false;
            m_Builder.ClearOverlay();
            if (m_C3d != null)
                m_C3d.SetMouseMode(m_eMode == InteractionMode.Mouse ? 99 : 0);

            RefreshHistory();
            UpdatePreview(null);
            lblStatus.Text = string.Format("{0} → {1} axis aligned", stlFilename, centerType);
            lblCurrentValue.Text = string.Format("({0:F1}, {1:F1}, {2:F1})", centerX, centerY, centerZ);
        }

        // DetectCameraFacingFace → m_C3d.DetectCameraFacingFace 로 이동됨
        // DetectClickedFace → m_C3d.DetectClickedFace 로 이동됨
        // SelectNearestCluster → m_C3d.SelectNearestCluster 로 이동됨

        // ========================================
        // 3D 마우스 드래그 핸들러 (마우스 모드 전용)
        // ========================================
        private void OnC3dMouseDown(object sender, MouseEventArgs e)
        {
            // === $scene placement mode 우선 처리 ===
            //   Scene 탭에서 객체 버튼 클릭 시 m_eSceneMode == PlacingObject 상태가 됨.
            //   3D 뷰 좌클릭 → 클릭 위치 (Z=0 floor) 에 객체 spawn.
            //   기존 픽킹 / 카메라 회전 로직 건드리지 않고 즉시 return.
            //   우클릭 또는 Esc 키 (KeyDown 핸들러) 로 모드 해제.
            if (e.Button == MouseButtons.Left && m_eSceneMode == SceneToolMode.PlacingObject)
            {
                PlaceSceneObjectAt(e.X, e.Y);
                return;
            }
            if (e.Button == MouseButtons.Right && m_eSceneMode != SceneToolMode.None)
            {
                CancelSceneMode();
                return;
            }

            if (e.Button == MouseButtons.Left)
            {
                m_nLastClickX = e.X;
                m_nLastClickY = e.Y;
                // 피킹 트리거: 좌클릭으로 축 핸들 선택
                m_C3d.SetPickCheck_OneShot(e.X, e.Y);
                // 빈 공간 클릭 감지 시작 — 다음 tmrDisp_Tick 부터 N frame 안에 GetEvent_Pick
                // 발화 없으면 허공 클릭으로 간주하고 선택 해제.
                m_bPickWaitForResult = true;
                m_nPickWaitTicks = 3;
            }

            if (m_eMode != InteractionMode.Mouse) return;
            if (e.Button != MouseButtons.Left) return;

            // STL 선택 상태면 STL 드래그 시작 (merge/FaceSnap 모드일 때는 면 클릭이므로 드래그 안 함)
            int stlIdx = GetSelectedStlStepIndex();
            if (stlIdx >= 0 && !m_bMergeMode && !m_bFaceSnapMode)
            {
                m_bDragging = true;
                m_nDragStartX = e.X;
                m_nDragStartY = e.Y;
                m_eAutoDetectedAction = BuildAction.None;
                m_TempStep = null;
                BeginStlDrag(stlIdx);
            }
            else
            {
                m_nStlDragStepIdx = -1;
            }
        }

        private void OnC3dMouseMove(object sender, MouseEventArgs e)
        {
            // STL 면 호버 프리뷰 (결합 모드 또는 FaceSnap 모드: 버튼 안 눌렀을 때)
            if ((m_bMergeMode || m_bFaceSnapMode) && e.Button == MouseButtons.None)
            {
                int hdx = e.X - m_nLastHoverX;
                int hdy = e.Y - m_nLastHoverY;
                if (hdx * hdx + hdy * hdy > 36)
                {
                    m_nLastHoverX = e.X;
                    m_nLastHoverY = e.Y;
                    // 원 모드: 원 hover pick (face hover 대신)
                    if (m_bFaceSnapMode && m_strSnapMode == "circle")
                    {
                        int newHov = PickCircleByRay(e.X, e.Y);
                        if (newHov != m_nSnapHovCircleIdx)
                        {
                            m_nSnapHovCircleIdx = newHov;
                            UpdatePreview(null);
                            if (m_lblSnapStatus != null)
                            {
                                if (newHov >= 0)
                                {
                                    SnapCircleEntry h = m_lstSnapCircles[newHov];
                                    m_lblSnapStatus.Text = string.Format("hover 원: step #{0} r={1:F1}", h.StepIdx, h.Wr);
                                }
                                else m_lblSnapStatus.Text = "원 모드: hover 원 없음";
                            }
                        }
                    }
                    else
                    {
                        TryHoverStlFace(e.X, e.Y);
                    }
                }
                return;
            }

            // STL 드래그만 처리 (DH 파라미터 생성은 클릭+휠 방식으로 변경)
            if (!m_bDragging || m_eMode != InteractionMode.Mouse || m_nStlDragStepIdx < 0) return;

            int dx = e.X - m_nDragStartX;
            int dy = e.Y - m_nDragStartY;

            // 수동 이동 모드: 선택된 STL 의 stepIdx 기준 Re 로 스크린 투영 계산.
            //   (C3d.GetAxisDelta 는 chain 마지막 Re 를 쓰므로 mid-chain STL 의 실제 이동 방향과 어긋남)
            BuildAction action;
            float value;
            if (m_bManualMoveMode)
            {
                action = m_eCurrentAction != BuildAction.None
                    ? m_eCurrentAction
                    : ManualMoveDetectAxis(m_nStlDragStepIdx, dx, dy);
                value = (float)Math.Round(ManualMoveAxisDelta(m_nStlDragStepIdx, action, dx, dy, m_fDragSensitivity));
            }
            else
            {
                action = m_eCurrentAction != BuildAction.None
                    ? m_eCurrentAction
                    : m_C3d.DetectAxisFromDrag(m_Builder, dx, dy);
                value = (float)Math.Round(m_C3d.GetAxisDelta(m_Builder, action, dx, dy, m_fDragSensitivity));
            }
            UpdateStlDrag(action, value);

            bool isRot = DhBuilder.IsRotation(action);
            lblStatus.Text = "STL " + DhBuilder.GetAxisName(action);
            lblCurrentValue.Text = string.Format("{0}{1}", (int)value, isRot ? "deg" : "mm");
        }

        private void OnC3dMouseUp(object sender, MouseEventArgs e)
        {
            // STL 면 선택 (모든 모드): 클릭(드래그 아닌) 시 레이캐스트로 면 감지
            bool stlSelected = false;
            if (e.Button == MouseButtons.Left)
            {
                int adx = Math.Abs(e.X - m_nLastClickX);
                int ady = Math.Abs(e.Y - m_nLastClickY);
                if (adx < 5 && ady < 5)
                {
                    // 원 모드: 원 pick 처리 우선. 원 hit 이면 처리하고 return.
                    //   원 hit X + source 있음 → source 해제 후 return.
                    //   원 hit X + source 없음 → TrySelectStlFace 로 STL 선택 변경 허용 (return X).
                    if (m_bFaceSnapMode && m_strSnapMode == "circle")
                    {
                        int hit = PickCircleByRay(e.X, e.Y);
                        if (hit >= 0)
                        {
                            HandleCircleClick(hit);
                            m_nStlDragStepIdx = -1;
                            m_strStlOriginalDhLines = "";
                            return;
                        }
                        if (m_nSnapSrcCircleIdx >= 0)
                        {
                            m_nSnapSrcCircleIdx = -1;
                            UpdatePreview(null);
                            if (m_lblSnapStatus != null) m_lblSnapStatus.Text = "원 source 해제";
                            return;
                        }
                        // fall through → TrySelectStlFace 로 다른 STL 선택 변경 가능
                    }
                    // 수동 이동 모드: 클릭이 축 ball 근처면 (15px 이내) skip — 축 픽킹용.
                    //   그 외 영역 클릭은 TrySelectStlFace 로 다른 STL 선택 가능.
                    bool isAxisBallClick = m_bManualMoveMode && IsClickNearManualAxisBall(e.X, e.Y, 15);
                    if (isAxisBallClick) stlSelected = false;
                    else stlSelected = TrySelectStlFace(e.X, e.Y);
                    // FaceSnap 모드에서 허공 클릭 + source 이미 선택됨 → source 해제
                    bool srcReleased = false;
                    if (m_bFaceSnapMode && !stlSelected && m_nFaceSnapClick == 1)
                    {
                        m_nFaceSnapClick = 0;
                        m_nSnapSrcStepIdx = -1;
                        m_Builder.ClearOverlay();
                        UpdatePreview(null);
                        if (m_lblSnapStatus != null)
                            m_lblSnapStatus.Text = "source 해제 — 다시 1) 면 클릭";
                        lblStatus.Text = "Face Snap: 1) 이동할 STL 의 면 클릭";
                        srcReleased = true;
                    }
                    // 진단 패널은 hit 없음 & source 해제 안 된 경우만 갱신 (hit 일 때는 HandleFaceSnapClick 이 패널 관리)
                    if (m_bFaceSnapMode && m_lblSnapStatus != null && !srcReleased && !stlSelected)
                    {
                        // 진단: 클릭의 floor (Z=0) 교차점 + 가장 가까운 STL 의 시각 위치 비교
                        string diag = "✗ no hit";
                        try
                        {
                            double fx, fy, fz;
                            if (m_C3d.ScreenToWorldOnFloor(e.X, e.Y, out fx, out fy, out fz))
                            {
                                double bestD = double.MaxValue; int bestI = -1;
                                double bestVx = 0, bestVy = 0, bestVz = 0;
                                for (int si = 0; si < m_Builder.StepCount; si++)
                                {
                                    DhStep ds = m_Builder.GetStep(si);
                                    if (ds.Action != BuildAction.Stl) continue;
                                    double epx, epy, epz;
                                    m_Builder.GetEndpointPosition(si, out epx, out epy, out epz);
                                    string sfn; float ox2, oy2, oz2, pn, tl, sw;
                                    DhBuilder.ParseStlParams(ds.DhLines,
                                        out sfn, out ox2, out oy2, out oz2, out pn, out tl, out sw);
                                    double[,] Re2 = m_Builder.GetEndpointRotation(si);
                                    double vx = Re2[0, 0] * ox2 + Re2[0, 1] * oy2 + Re2[0, 2] * oz2 + epx;
                                    double vy = Re2[1, 0] * ox2 + Re2[1, 1] * oy2 + Re2[1, 2] * oz2 + epy;
                                    double vz = Re2[2, 0] * ox2 + Re2[2, 1] * oy2 + Re2[2, 2] * oz2 + epz;
                                    double dd = Math.Sqrt((vx - fx) * (vx - fx) + (vy - fy) * (vy - fy));
                                    if (dd < bestD) { bestD = dd; bestI = si; bestVx = vx; bestVy = vy; bestVz = vz; }
                                }
                                if (bestI >= 0)
                                {
                                    diag = string.Format(
                                        System.Globalization.CultureInfo.InvariantCulture,
                                        "✗ no hit\r\nclick floor=({0:F1},{1:F1})\r\nnearest STL #{2}\r\n   @ ({3:F1},{4:F1},{5:F1}) dist={6:F1}",
                                        fx, fy, bestI, bestVx, bestVy, bestVz, bestD);
                                }
                            }
                        }
                        catch { }
                        m_lblSnapStatus.Text = diag;
                    }
                    if (stlSelected && m_bMergeMode)
                    {
                        HandleMergeClick();
                        // merge 처리 후 STL 드래그 취소 (EndStlDrag가 DhLines 덮어쓰기 방지)
                        m_nStlDragStepIdx = -1;
                        m_strStlOriginalDhLines = "";
                    }
                    else if (stlSelected && m_bFaceSnapMode)
                    {
                        HandleFaceSnapClick();
                        m_nStlDragStepIdx = -1;
                        m_strStlOriginalDhLines = "";
                    }
                }
            }

            if (!m_bDragging || m_eMode != InteractionMode.Mouse) return;

            // STL 드래그 완료
            if (m_nStlDragStepIdx >= 0)
            {
                BuildAction action = m_eCurrentAction != BuildAction.None ? m_eCurrentAction : m_eAutoDetectedAction;
                int dx = e.X - m_nDragStartX;
                int dy = e.Y - m_nDragStartY;
                // 수동 모드: ManualMoveAxisDelta 사용 (m_C3d.GetAxisDelta 는 stepIdx Re 무시 + 로봇 회전 무시 → 0 반환 가능 → reset 됨)
                float finalDelta;
                if (action == BuildAction.None) finalDelta = 0;
                else if (m_bManualMoveMode)
                    finalDelta = (float)Math.Round(ManualMoveAxisDelta(m_nStlDragStepIdx, action, dx, dy, m_fDragSensitivity));
                else
                    finalDelta = (float)Math.Round(m_C3d.GetAxisDelta(m_Builder, action, dx, dy, m_fDragSensitivity));
                EndStlDrag(action, finalDelta);
                RefreshHistory();
                UpdatePreview(null);
                lblStatus.Text = finalDelta != 0
                    ? string.Format("STL {0} {1:+0;-0}{2}", DhBuilder.GetAxisName(action), finalDelta, DhBuilder.IsRotation(action) ? "deg" : "mm")
                    : "STL drag cancelled";
            }

            m_bDragging = false;
            m_TempStep = null;
            m_eAutoDetectedAction = BuildAction.None;
        }

        // ========================================
        // 마우스 휠 핸들러
        // - 축 선택 후 스크롤       → 이동(translate)
        // - 축 선택 후 Ctrl+스크롤  → 회전(rotate)
        // - 축 미선택               → 줌
        // ========================================
        private void OnC3dMouseWheel(object sender, MouseEventArgs e)
        {
            // 우클릭 + 스크롤 → 줌만 (OpenJigWare 내부 OjwMouseWheel 이 m_fScale 갱신). 이동/회전 skip.
            //   MouseEventArgs.Button 은 wheel 이벤트에서 보통 None — Control.MouseButtons 로 현재 버튼 상태 조회.
            bool isRightDown = (Control.MouseButtons & MouseButtons.Right) != 0;
            if (isRightDown) return;

            if (m_eMode == InteractionMode.Mouse && m_eCurrentAction != BuildAction.None)
            {
                bool isCtrl = (Control.ModifierKeys & Keys.Control) != 0;
                // Move 액션을 기준으로 저장되어 있으므로 Ctrl이면 대응하는 Rotate 액션으로 변환
                BuildAction action = m_eCurrentAction;
                if (isCtrl)
                {
                    if (action == BuildAction.RedMove)   action = BuildAction.RedRotate;
                    else if (action == BuildAction.GreenMove) action = BuildAction.GreenRotate;
                    else if (action == BuildAction.BlueMove)  action = BuildAction.BlueRotate;
                }
                float delta = (e.Delta > 0) ? -5.0f : 5.0f;
                // ±버튼과 완전히 같은 경로 (수동이동 → STL 직접 / 선택 라인 → 그 줄 수정 / 없으면 끝에 누적)
                ApplyAxisDeltaCore(action, delta);
            }
            else
            {
                // 줌
                float fData = (e.Delta > 0) ? -0.01f : 0.01f;
                float newScale = m_C3d.GetScale() + fData;
                if (newScale > 0) m_C3d.SetScale(newScale);
            }
        }

        /// <summary>수동 이동 모드 — 휠 스크롤로 선택된 STL 의 offset/회전을 증감.
        /// AccumulateWheelStep 처럼 새 DH 스텝을 추가하지 않고, STL 라인의 offset/rotation 만 직접 수정.
        /// format (신/구) 보존.</summary>
        private void ApplyManualWheelStep(BuildAction action, float delta)
        {
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) return;
            DhStep step = m_Builder.GetStep(stepIdx);
            step.DhLines = DhBuilder.MakeStlPreviewDhLinesFormatPreserved(step.DhLines, action, delta);
            RefreshHistory();
            UpdatePreview(null);
            SyncSnapManual();
            string unit = DhBuilder.IsRotation(action) ? "deg" : "mm";
            lblStatus.Text = string.Format("STL {0} {1:+0;-0}{2}", DhBuilder.GetAxisName(action), delta, unit);
            lblCurrentValue.Text = string.Format("{0}{1}", (int)delta, unit);
        }

        // 연속 스크롤 누적: 같은 액션이면 마지막 스텝 값 수정, 다르면 새 스텝 추가
        private void AccumulateWheelStep(BuildAction action, float delta)
        {
            float totalVal = delta;
            if (m_Builder.StepCount > 0)
            {
                var last = m_Builder.GetStep(m_Builder.StepCount - 1);
                if (last.Action == action && !last.IsRaw)
                {
                    totalVal = last.Value + delta;
                    m_Builder.RemoveLastStep();
                }
            }
            if (totalVal != 0)
                m_Builder.AddStep(DhBuilder.CreateStep(action, totalVal));

            RefreshHistory();
            UpdatePreview(null);
            string unit = DhBuilder.IsRotation(action) ? "deg" : "mm";
            lblStatus.Text    = string.Format("{0} {1:+0;-0}{2}", DhBuilder.GetAxisName(action), totalVal, unit);
            lblCurrentValue.Text = string.Format("{0}{1}", (int)totalVal, unit);
        }

        // ========================================
        // 축 핸들 클릭 처리 (클릭으로 축 선택, 스크롤=이동, Ctrl+스크롤=회전)
        // ========================================
        private void OnAxisHandlePicked(int pickId)
        {
            // 항상 Move 액션으로 저장 (스크롤 시 Ctrl 여부로 이동/회전 결정)
            if (pickId == PICK_AXIS_X)
            {
                m_eCurrentAction = BuildAction.RedMove;
                lblStatus.Text = "X-axis — Scroll=Move / Ctrl+Scroll=Rotate";
            }
            else if (pickId == PICK_AXIS_Y)
            {
                m_eCurrentAction = BuildAction.GreenMove;
                lblStatus.Text = "Y-axis — Scroll=Move / Ctrl+Scroll=Rotate";
            }
            else
            {
                m_eCurrentAction = BuildAction.BlueMove;
                lblStatus.Text = "Z-axis — Scroll=Move / Ctrl+Scroll=Rotate";
            }
            UpdatePreview(null);
        }

        // ========================================
        // 하이브리드 드래그 핸들러 (pnDragArea)
        // ========================================
        private void pnDragArea_MouseDown(object sender, MouseEventArgs e)
        {
            if (m_eMode != InteractionMode.Hybrid) return;
            if (e.Button != MouseButtons.Left) return;

            if (m_eCurrentAction == BuildAction.None)
            {
                lblStatus.Text = "Select axis first!";
                return;
            }

            m_bDragging = true;
            m_nDragStartX = e.X;
            m_TempStep = null;

            // STL 선택 상태면 STL 드래그 시작
            int stlIdx = GetSelectedStlStepIndex();
            if (stlIdx >= 0)
                BeginStlDrag(stlIdx);
            else
                m_nStlDragStepIdx = -1;
        }

        private void pnDragArea_MouseMove(object sender, MouseEventArgs e)
        {
            if (!m_bDragging || m_eMode != InteractionMode.Hybrid) return;

            int dx = e.X - m_nDragStartX;
            float value = (float)Math.Round(dx * m_fDragSensitivity);

            // STL 드래그 중이면 STL 파라미터 수정
            if (m_nStlDragStepIdx >= 0)
            {
                UpdateStlDrag(m_eCurrentAction, value);
            }
            else
            {
                m_TempStep = DhBuilder.CreateStep(m_eCurrentAction, value);
                UpdatePreview(m_TempStep);
            }

            bool isRot = DhBuilder.IsRotation(m_eCurrentAction);
            string unit = isRot ? "deg" : "mm";
            string prefix = (m_nStlDragStepIdx >= 0) ? "STL " : "";
            lblStatus.Text = prefix + DhBuilder.GetAxisName(m_eCurrentAction);
            lblCurrentValue.Text = string.Format("{0}{1}", (int)value, unit);
        }

        private void pnDragArea_MouseUp(object sender, MouseEventArgs e)
        {
            if (!m_bDragging || m_eMode != InteractionMode.Hybrid) return;

            // STL 드래그 완료
            if (m_nStlDragStepIdx >= 0)
            {
                int dx = e.X - m_nDragStartX;
                float finalDelta = (float)Math.Round(dx * m_fDragSensitivity);
                EndStlDrag(m_eCurrentAction, finalDelta);
                RefreshHistory();
                if (finalDelta != 0)
                    lblStatus.Text = string.Format("STL {0} {1:+0;-0}{2}", DhBuilder.GetAxisName(m_eCurrentAction),
                        finalDelta, DhBuilder.IsRotation(m_eCurrentAction) ? "deg" : "mm");
                else
                    lblStatus.Text = "STL drag cancelled";
            }
            else if (m_TempStep != null && m_TempStep.Value != 0)
            {
                m_Builder.AddStep(m_TempStep);
                RefreshHistory();
                lblStatus.Text = m_TempStep.Description + " added";
            }
            else
            {
                lblStatus.Text = "Drag area (" + DhBuilder.GetAxisName(m_eCurrentAction) + ")";
            }

            m_bDragging = false;
            m_TempStep = null;
            // 하이브리드 모드: 축 선택 유지 (연속 드래그 가능)
            UpdatePreview(null);
        }

        // ========================================
        // 3D 축 투영 (카메라 회전 + DH 끝점 회전 반영)
        // ========================================

        // 3x3 회전 행렬 곱셈
        // MatMul, RotX, RotY, RotZ → DhBuilder.MatMul3x3, RotX3, RotY3, RotZ3 로 이동됨

        // GetEndpointRotation, GetEndpointPosition → m_Builder.GetEndpointRotation/Position 로 이동됨
        // StlLocalRotation → DhBuilder.StlLocalRotation 로 이동됨

        // GetCameraViewMatrix, GetAxisScreenProjection, GetAxisDelta, DetectAxisFromDrag → m_C3d 로 이동됨
        // GetAxisName, IsRotation, DetermineBBFace → DhBuilder 로 이동됨
        // ApplyStlDelta, GetStlPreviewDhLines → DhBuilder 로 이동됨

        private int GetSelectedStlStepIndex()
        {
            int idx = lstHistory.SelectedIndex;
            if (idx < 0 || idx >= m_Builder.StepCount) return -1;
            if (m_Builder.GetStep(idx).Action != BuildAction.Stl) return -1;
            return idx;
        }

        /// <summary>
        /// STL 드래그 시작: 원본 DhLines를 저장.
        /// </summary>
        private void BeginStlDrag(int stepIdx)
        {
            m_nStlDragStepIdx = stepIdx;
            m_strStlOriginalDhLines = m_Builder.GetStep(stepIdx).DhLines;
        }

        /// <summary>
        /// STL 드래그 중: 원본에 delta를 적용하여 실시간 미리보기.
        /// </summary>
        private void UpdateStlDrag(BuildAction action, float delta)
        {
            if (m_nStlDragStepIdx < 0) return;
            DhStep step = m_Builder.GetStep(m_nStlDragStepIdx);
            step.DhLines = DhBuilder.MakeStlPreviewDhLinesFormatPreserved(m_strStlOriginalDhLines, action, delta);
            UpdatePreview(null);
            // 드래그 중 실시간으로 텍스트박스 갱신
            SyncSnapManual();
        }

        // (Phase R1 통합) MakeStlPreviewDhLinesFormatPreserved → DhBuilder.MakeStlPreviewDhLinesFormatPreserved

        /// <summary>
        /// STL 드래그 완료: 최종 delta 적용 확정.
        /// </summary>
        private void EndStlDrag(BuildAction action, float delta)
        {
            if (m_nStlDragStepIdx < 0) return;
            DhStep step = m_Builder.GetStep(m_nStlDragStepIdx);
            if (delta != 0)
                step.DhLines = DhBuilder.MakeStlPreviewDhLinesFormatPreserved(m_strStlOriginalDhLines, action, delta);
            else
                step.DhLines = m_strStlOriginalDhLines; // delta 0이면 원복
            m_nStlDragStepIdx = -1;
            m_strStlOriginalDhLines = "";
            // 드래그 결과로 변경된 offset/회전 값을 Snap 탭 텍스트박스에 자동 반영
            SyncSnapManual();
        }

        /// <summary>
        /// STL 드래그 취소: 원본 DhLines로 원복.
        /// </summary>
        private void CancelStlDrag()
        {
            if (m_nStlDragStepIdx < 0) return;
            m_Builder.GetStep(m_nStlDragStepIdx).DhLines = m_strStlOriginalDhLines;
            m_nStlDragStepIdx = -1;
            m_strStlOriginalDhLines = "";
            UpdatePreview(null);
        }

        // ESC로 드래그 취소
        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
        {
            if (keyData == Keys.Escape)
            {
                if (m_bMergeMode)
                {
                    ExitMergeMode();
                    return true;
                }
                if (m_bDragging)
                {
                    CancelDrag();
                    return true;
                }
            }
            return base.ProcessCmdKey(ref msg, keyData);
        }

        private void CancelDrag()
        {
            // STL 드래그 취소: 원본 복원
            if (m_nStlDragStepIdx >= 0)
                CancelStlDrag();

            m_bDragging = false;
            m_TempStep = null;
            m_eCurrentAction = BuildAction.None;
            lblStatus.Text = "Cancelled";
            lblCurrentValue.Text = "";
            UpdatePreview(null);
        }

        // ========================================
        // 3D 미리보기 갱신
        // ========================================
        /// <summary>원을 segments 개의 line segment 로 그림 (world 좌표).</summary>
        /// <summary>STL DH 라인의 색상에서 채도 최대화된 보색 계산.
        // (Phase R1 통합) GetStlComplementColor → DhBuilder.GetStlComplementColor(dhLines)

        /// <summary>원 segments 를 동심원 stack 으로 그려 두께감을 표현 (얇은 라인 가시성 보완).
        /// rings = 동심원 개수, color = 라인 색, segments = 원 분할 수.
        /// 동심원 간격은 반지름 비례 (최소 0.4mm). 안쪽 STL 면에 가려져도 일부는 보이도록.</summary>
        private void DrawCircleSegments(SnapCircleEntry ce, Color color, int segments, int rings)
        {
            if (m_C3d == null) return;
            double ax = ce.Wax, ay = ce.Way, az = ce.Waz;
            double ux, uy, uz;
            if (Math.Abs(ax) > 0.9) { ux = 0; uy = 1; uz = 0; }
            else { ux = 1; uy = 0; uz = 0; }
            double udota = ux * ax + uy * ay + uz * az;
            ux -= udota * ax; uy -= udota * ay; uz -= udota * az;
            double ul = Math.Sqrt(ux * ux + uy * uy + uz * uz);
            if (ul < 1e-9) return;
            ux /= ul; uy /= ul; uz /= ul;
            double vx = ay * uz - az * uy;
            double vy = az * ux - ax * uz;
            double vz = ax * uy - ay * ux;
            double r = ce.Wr;
            // 동심원 간격: 반지름의 2.5%, 최소 0.4mm
            double step = Math.Max(0.4, r * 0.025);
            if (rings < 1) rings = 1;
            // rings 가 홀수이면 가운데 ring 포함, 짝수이면 가운데 생략 (양옆)
            int half = (rings - 1) / 2;
            for (int k = -half; k <= half; k++)
            {
                double rr = r + k * step;
                if (rr < 0.1) continue;
                for (int i = 0; i < segments; i++)
                {
                    double a1 = (i * 2 * Math.PI) / segments;
                    double a2 = ((i + 1) * 2 * Math.PI) / segments;
                    double c1 = Math.Cos(a1), s1 = Math.Sin(a1);
                    double c2 = Math.Cos(a2), s2 = Math.Sin(a2);
                    float x1 = (float)(ce.Wcx + rr * (c1 * ux + s1 * vx));
                    float y1 = (float)(ce.Wcy + rr * (c1 * uy + s1 * vy));
                    float z1 = (float)(ce.Wcz + rr * (c1 * uz + s1 * vz));
                    float x2 = (float)(ce.Wcx + rr * (c2 * ux + s2 * vx));
                    float y2 = (float)(ce.Wcy + rr * (c2 * uy + s2 * vy));
                    float z2 = (float)(ce.Wcz + rr * (c2 * uz + s2 * vz));
                    m_C3d.User_Set_Init(true);
                    m_C3d.User_Set_Model("#17");
                    m_C3d.User_Set_Color(color);
                    m_C3d.User_Set_Alpha(1.0f);
                    m_C3d.User_Set_nPickGroup_A(-1);
                    m_C3d.User_Set_nPickGroup_B(-1);
                    m_C3d.User_Set_nPickGroup_C(-1);
                    m_C3d.User_Set_Points_Clear();
                    m_C3d.User_Set_Points_Add(x1, y1, z1);
                    m_C3d.User_Set_Points_Add(x2, y2, z2);
                    m_C3d.User_Add();
                }
            }
        }

        /// <summary>수동 이동 모드 — 선택된 STL 의 world 위치에 X/Y/Z 축 화살표 그리기.
        /// 각 축은 pickGroup (A=255, C=253/254/255) → OnAxisHandlePicked 로 처리.
        /// 클릭 후 드래그하면 기존 STL 드래그 메커니즘이 해당 축으로 이동시킴.
        /// <para>중요: 화살표 방향은 DH 끝점의 LOCAL X/Y/Z 축 (= Re 의 열 벡터) 으로 그림.
        /// 왜냐하면 GetAxisDelta/GetStlPreviewDhLines 가 로컬 축 기준으로 동작하기 때문.
        /// 월드 축으로 그리면 화살표 방향과 실제 이동 방향이 어긋남.</para></summary>
        private void DrawManualMoveAxes()
        {
            if (m_C3d == null) return;
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) return;

            // STL world 위치 = endpoint + Re * stl_offset
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            double epx, epy, epz;
            m_Builder.GetEndpointPosition(stepIdx, out epx, out epy, out epz);
            double[,] Re = m_Builder.GetEndpointRotation(stepIdx);
            double sx = epx + Re[0, 0] * ox + Re[0, 1] * oy + Re[0, 2] * oz;
            double sy = epy + Re[1, 0] * ox + Re[1, 1] * oy + Re[1, 2] * oz;
            double sz = epz + Re[2, 0] * ox + Re[2, 1] * oy + Re[2, 2] * oz;

            const float arrowLen = 80.0f;
            const float ballSize = 6.0f;
            // 로컬 축 방향 = Re 의 각 열 벡터
            float lxx = (float)Re[0, 0], lxy = (float)Re[1, 0], lxz = (float)Re[2, 0]; // local +X
            float lyx = (float)Re[0, 1], lyy = (float)Re[1, 1], lyz = (float)Re[2, 1]; // local +Y
            float lzx = (float)Re[0, 2], lzy = (float)Re[1, 2], lzz = (float)Re[2, 2]; // local +Z
            DrawManualMoveAxis(sx, sy, sz, lxx * arrowLen, lxy * arrowLen, lxz * arrowLen, Color.Red,  253, ballSize);
            DrawManualMoveAxis(sx, sy, sz, lyx * arrowLen, lyy * arrowLen, lyz * arrowLen, Color.Lime, 254, ballSize);
            DrawManualMoveAxis(sx, sy, sz, lzx * arrowLen, lzy * arrowLen, lzz * arrowLen, Color.Blue, 255, ballSize);
        }

        /// <summary>수동 이동 모드 — STL 위치에서 X/Y/Z 화살표가 스크린 상 어느 방향을 가리키는지 계산.
        /// <para>gluProject 로 STL 중심 + 각 축 끝점을 스크린에 투영 → 두 점의 픽셀 차이가 곧 화살표의 2D 방향.</para>
        /// <para>이 방식은 실제 render 의 modelview/projection 매트릭스 (카메라 + 로봇 회전 + 원근 모두 포함) 를
        /// 그대로 쓰므로 화살표가 보이는 방향과 100% 일치.</para>
        /// projX/Y/Z[0]=screen-X 픽셀 dir, [1]=screen-Y 픽셀 dir (WinForms top-down, **아래로 +**).
        /// 마우스 dy 도 top-down 이라 그대로 dot 가능.</summary>
        private bool GetManualAxisProjections(int stepIdx,
            out float[] projX, out float[] projY, out float[] projZ)
        {
            projX = projY = projZ = null;
            // STL world 위치 계산
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing);
            double epx, epy, epz;
            m_Builder.GetEndpointPosition(stepIdx, out epx, out epy, out epz);
            double[,] Re = m_Builder.GetEndpointRotation(stepIdx);
            double sx = epx + Re[0, 0] * ox + Re[0, 1] * oy + Re[0, 2] * oz;
            double sy = epy + Re[1, 0] * ox + Re[1, 1] * oy + Re[1, 2] * oz;
            double sz = epz + Re[2, 0] * ox + Re[2, 1] * oy + Re[2, 2] * oz;

            // 화살표 끝점 = STL 중심 + 로컬 축 × 길이
            const double L = 50.0;
            double xex = sx + Re[0, 0] * L, xey = sy + Re[1, 0] * L, xez = sz + Re[2, 0] * L;
            double yex = sx + Re[0, 1] * L, yey = sy + Re[1, 1] * L, yez = sz + Re[2, 1] * L;
            double zex = sx + Re[0, 2] * L, zey = sy + Re[1, 2] * L, zez = sz + Re[2, 2] * L;

            // gluProject 로 4개 점 모두 스크린에 투영
            double c_sx, c_sy, x_sx, x_sy, y_sx, y_sy, z_sx, z_sy;
            if (!m_C3d.WorldToScreen(sx, sy, sz, out c_sx, out c_sy)) return false;
            if (!m_C3d.WorldToScreen(xex, xey, xez, out x_sx, out x_sy)) return false;
            if (!m_C3d.WorldToScreen(yex, yey, yez, out y_sx, out y_sy)) return false;
            if (!m_C3d.WorldToScreen(zex, zey, zez, out z_sx, out z_sy)) return false;

            // 화살표 스크린 방향 = (끝점 - 중심), WinForms top-down Y (아래로 +)
            projX = new float[] { (float)(x_sx - c_sx), (float)(x_sy - c_sy) };
            projY = new float[] { (float)(y_sx - c_sx), (float)(y_sy - c_sy) };
            projZ = new float[] { (float)(z_sx - c_sx), (float)(z_sy - c_sy) };
            return true;
        }

        /// <summary>마우스 (dx, dy) 가 어느 축의 스크린 투영과 가장 일치하는지 탐지 (절대값 기준).
        /// proj 는 WinForms top-down 좌표라 dy 부호 그대로 사용.</summary>
        private BuildAction ManualMoveDetectAxis(int stepIdx, int dx, int dy)
        {
            float[] px, py, pz;
            if (!GetManualAxisProjections(stepIdx, out px, out py, out pz))
                return BuildAction.RedMove;
            float ax = Math.Abs(dx * px[0] + dy * px[1]);
            float ay = Math.Abs(dx * py[0] + dy * py[1]);
            float az = Math.Abs(dx * pz[0] + dy * pz[1]);
            if (ay >= ax && ay >= az) return BuildAction.GreenMove;
            if (ax >= az) return BuildAction.RedMove;
            return BuildAction.BlueMove;
        }

        /// <summary>마우스 (dx, dy) 를 지정된 축의 스크린 투영 방향으로 dot 한 값 / 정규화 / 감도.
        /// = 화살표 방향으로 마우스가 움직인 거리 (스크린 픽셀) × sensitivity.
        /// proj 와 mouse dy 모두 WinForms top-down (아래로 +) 이라 부호 그대로 dot.</summary>
        private float ManualMoveAxisDelta(int stepIdx, BuildAction action, int dx, int dy, float sensitivity)
        {
            float[] px, py, pz;
            if (!GetManualAxisProjections(stepIdx, out px, out py, out pz))
                return 0;
            float[] proj;
            switch (action)
            {
                case BuildAction.RedMove:   case BuildAction.RedRotate:   proj = px; break;
                case BuildAction.GreenMove: case BuildAction.GreenRotate: proj = py; break;
                case BuildAction.BlueMove:  case BuildAction.BlueRotate:  proj = pz; break;
                default: proj = px; break;
            }
            float dot = dx * proj[0] + dy * proj[1];
            float len = (float)Math.Sqrt(proj[0] * proj[0] + proj[1] * proj[1]);
            if (len < 0.1f) len = 0.1f;
            return (dot / len) * sensitivity;
        }

        /// <summary>클릭 픽셀 (mx, my) 이 어느 축 ball 의 스크린 위치에서 tolPx 픽셀 이내인지 판정.
        /// 수동 모드에서 축 ball 클릭과 다른 STL 클릭을 구분하기 위함.</summary>
        private bool IsClickNearManualAxisBall(int mx, int my, int tolPx)
        {
            if (!m_bManualMoveMode) return false;
            int stepIdx = GetSelectedStlStepIndex();
            if (stepIdx < 0) return false;

            // STL world 위치 (DrawManualMoveAxes 와 동일 계산)
            DhStep step = m_Builder.GetStep(stepIdx);
            string fn; float ox, oy, oz, pan, tilt, swing;
            if (!DhBuilder.ParseStlParams(step.DhLines,
                out fn, out ox, out oy, out oz, out pan, out tilt, out swing)) return false;
            double epx, epy, epz;
            m_Builder.GetEndpointPosition(stepIdx, out epx, out epy, out epz);
            double[,] Re = m_Builder.GetEndpointRotation(stepIdx);
            double sx = epx + Re[0, 0] * ox + Re[0, 1] * oy + Re[0, 2] * oz;
            double sy = epy + Re[1, 0] * ox + Re[1, 1] * oy + Re[1, 2] * oz;
            double sz = epz + Re[2, 0] * ox + Re[2, 1] * oy + Re[2, 2] * oz;

            // 화살표 끝점 (DrawManualMoveAxes 의 arrowLen=80 과 동일)
            const double L = 80.0;
            double[][] ends = new double[][] {
                new double[] { sx + Re[0,0]*L, sy + Re[1,0]*L, sz + Re[2,0]*L },
                new double[] { sx + Re[0,1]*L, sy + Re[1,1]*L, sz + Re[2,1]*L },
                new double[] { sx + Re[0,2]*L, sy + Re[1,2]*L, sz + Re[2,2]*L }
            };
            int tolSq = tolPx * tolPx;
            foreach (var e in ends)
            {
                double bx, by;
                if (!m_C3d.WorldToScreen(e[0], e[1], e[2], out bx, out by)) continue;
                double ddx = bx - mx, ddy = by - my;
                if (ddx * ddx + ddy * ddy <= tolSq) return true;
            }
            return false;
        }

        /// <summary>축 화살표 하나: STL 중심에서 (dx,dy,dz) 끝점까지 라인 + 끝점에 클릭 가능한 ball.
        /// pickGroup C 값으로 X/Y/Z 식별 (253=X, 254=Y, 255=Z).</summary>
        private void DrawManualMoveAxis(double cx, double cy, double cz,
            float dx, float dy, float dz, Color color, int pickC, float ballSize)
        {
            float ex = (float)(cx + dx);
            float ey = (float)(cy + dy);
            float ez = (float)(cz + dz);
            // 1) 라인 (visual 만, pickable 아님)
            m_C3d.User_Set_Init(true);
            m_C3d.User_Set_Model("#17");
            m_C3d.User_Set_Color(color);
            m_C3d.User_Set_Alpha(1.0f);
            m_C3d.User_Set_nPickGroup_A(-1);
            m_C3d.User_Set_nPickGroup_B(-1);
            m_C3d.User_Set_nPickGroup_C(-1);
            m_C3d.User_Set_Points_Clear();
            m_C3d.User_Set_Points_Add((float)cx, (float)cy, (float)cz);
            m_C3d.User_Set_Points_Add(ex, ey, ez);
            m_C3d.User_Add();
            // 2) 끝점 ball (pickable — 기존 OnAxisHandlePicked 가 받는 그룹)
            m_C3d.User_Set_Init(true);
            m_C3d.User_Set_Model("#9");   // ball (outside render)
            m_C3d.User_Set_Color(color);
            m_C3d.User_Set_Alpha(1.0f);
            m_C3d.User_Set_Width_Or_Radius(ballSize);
            m_C3d.User_Set_nPickGroup_A(255);
            m_C3d.User_Set_nPickGroup_C(pickC);
            m_C3d.User_Set_Offset_Translation(ex, ey, ez);
            m_C3d.User_Add();
        }

        /// <summary>FaceSnap 시각화: face center 에서 normal 방향으로 길이 length 의
        /// 굵은 라인 + 끝에 짧은 cross 화살표 모양. 십자선 패턴 그대로 활용.</summary>
        private void DrawFaceNormalArrow(double cx, double cy, double cz,
            double nx, double ny, double nz, Color color, float length)
        {
            if (m_C3d == null) return;
            // 정규화
            double nl = Math.Sqrt(nx * nx + ny * ny + nz * nz);
            if (nl < 1e-9) return;
            nx /= nl; ny /= nl; nz /= nl;
            float endX = (float)(cx + nx * length);
            float endY = (float)(cy + ny * length);
            float endZ = (float)(cz + nz * length);
            // 1) center → end 라인 (방향)
            m_C3d.User_Set_Init(true);
            m_C3d.User_Set_Model("#17");   // line
            m_C3d.User_Set_Color(color);
            m_C3d.User_Set_Alpha(1.0f);
            m_C3d.User_Set_nPickGroup_A(-1);
            m_C3d.User_Set_nPickGroup_B(-1);
            m_C3d.User_Set_nPickGroup_C(-1);
            m_C3d.User_Set_Points_Clear();
            m_C3d.User_Set_Points_Add((float)cx, (float)cy, (float)cz);
            m_C3d.User_Set_Points_Add(endX, endY, endZ);
            m_C3d.User_Add();
            // 2) end 에 짧은 교차 화살표 머리 (수직 두 라인)
            // perpendicular 두 축 계산: any vector not parallel to n
            double ux, uy, uz, vx, vy, vz;
            if (Math.Abs(nx) > 0.9) { ux = 0; uy = 1; uz = 0; }
            else { ux = 1; uy = 0; uz = 0; }
            // u = u - (u·n)*n  (n 에 수직화)
            double udotn = ux * nx + uy * ny + uz * nz;
            ux -= udotn * nx; uy -= udotn * ny; uz -= udotn * nz;
            double ul = Math.Sqrt(ux * ux + uy * uy + uz * uz);
            if (ul > 1e-9) { ux /= ul; uy /= ul; uz /= ul; }
            // v = n × u
            vx = ny * uz - nz * uy;
            vy = nz * ux - nx * uz;
            vz = nx * uy - ny * ux;
            float headSize = length * 0.15f;
            // U 방향 짧은 라인 (end 점 부근)
            m_C3d.User_Set_Init(true);
            m_C3d.User_Set_Model("#17");
            m_C3d.User_Set_Color(color);
            m_C3d.User_Set_Alpha(1.0f);
            m_C3d.User_Set_nPickGroup_A(-1);
            m_C3d.User_Set_nPickGroup_B(-1);
            m_C3d.User_Set_nPickGroup_C(-1);
            m_C3d.User_Set_Points_Clear();
            m_C3d.User_Set_Points_Add(endX + (float)(ux * headSize), endY + (float)(uy * headSize), endZ + (float)(uz * headSize));
            m_C3d.User_Set_Points_Add(endX - (float)(ux * headSize), endY - (float)(uy * headSize), endZ - (float)(uz * headSize));
            m_C3d.User_Add();
            // V 방향
            m_C3d.User_Set_Init(true);
            m_C3d.User_Set_Model("#17");
            m_C3d.User_Set_Color(color);
            m_C3d.User_Set_Alpha(1.0f);
            m_C3d.User_Set_nPickGroup_A(-1);
            m_C3d.User_Set_nPickGroup_B(-1);
            m_C3d.User_Set_nPickGroup_C(-1);
            m_C3d.User_Set_Points_Clear();
            m_C3d.User_Set_Points_Add(endX + (float)(vx * headSize), endY + (float)(vy * headSize), endZ + (float)(vz * headSize));
            m_C3d.User_Set_Points_Add(endX - (float)(vx * headSize), endY - (float)(vy * headSize), endZ - (float)(vz * headSize));
            m_C3d.User_Add();
        }

        private void UpdatePreview(DhStep tempStep, bool keepOverlay = false)
        {
            if (!keepOverlay)
                m_Builder.ClearOverlay();

            string dhString;
            if (tempStep != null)
                dhString = m_Builder.GenerateFullDhWithPreview(tempStep);
            else
                dhString = m_Builder.GenerateFullDh();

            // === Snap 탭 '메시' 체크박스 ===
            //   uncheck → @ 로 시작하는 STL 라인을 제거 → 메시 렌더 X (체인 변환은 유지).
            //   사용 시나리오: 메시 안쪽 hole/원이 가려질 때 메시 끄고 snap 특성만 보기.
            bool meshOn = (m_chkSnapMesh == null) || m_chkSnapMesh.Checked;
            if (!meshOn) dhString = DhBuilder.StripStlLines(dhString);

            MakeAll(dhString);

            // === Snap 탭 '스냅 특성' 체크박스 + 대상 드롭다운 ===
            //   특성 unchecked → 원/평면 시각화 모두 skip.
            //   대상: 둘다(0)/B(1=선택된 STL)/A(2=다른 STL).
            bool featOn       = (m_chkSnapFeat == null) || m_chkSnapFeat.Checked;
            int  featTarget   = (m_cmbSnapFeatTarget != null) ? m_cmbSnapFeatTarget.SelectedIndex : 0;
            int  selectedStep = GetSelectedStlStepIndex();

            // Circle Snap 시각화 — featOn 체크 + 대상 필터 적용
            if (featOn && m_bFaceSnapMode && m_strSnapMode == "circle" && m_C3d != null)
            {
                for (int i = 0; i < m_lstSnapCircles.Count; i++)
                {
                    SnapCircleEntry ce = m_lstSnapCircles[i];
                    // 대상 필터: B = 선택된 STL 만, A = 다른 STL 만
                    if (featTarget == 1 && ce.StepIdx != selectedStep) continue;
                    if (featTarget == 2 && ce.StepIdx == selectedStep) continue;
                    bool isPivot = m_bSnapPivotSet &&
                                   Math.Abs(ce.Wcx - m_dSnapPivotCx) < 0.5 &&
                                   Math.Abs(ce.Wcy - m_dSnapPivotCy) < 0.5 &&
                                   Math.Abs(ce.Wcz - m_dSnapPivotCz) < 0.5;
                    Color c; int rings;
                    if (isPivot)                       { c = Color.Magenta; rings = 7; }
                    else if (i == m_nSnapSrcCircleIdx) { c = Color.Yellow;  rings = 5; }
                    else if (i == m_nSnapHovCircleIdx) { c = Color.Cyan;    rings = 5; }
                    else                                { c = DhBuilder.GetStlComplementColor(m_Builder.GetStep(ce.StepIdx).DhLines); rings = 3; }
                    DrawCircleSegments(ce, c, 36, rings);
                }
            }

            // 수동 이동 모드: 선택된 STL 에 X/Y/Z 축 화살표 표시
            if (m_bManualMoveMode && m_C3d != null)
            {
                DrawManualMoveAxes();
            }

            // FaceSnap 화살표 (face normal 시각화): source = 노랑, hover target = 시안
            //   사용자가 어느 방향이 face normal 인지 직관적으로 확인 가능.
            //   featOn unchecked → 표시 skip.
            if (featOn && m_bFaceSnapMode && m_strSnapMode == "plane" && m_C3d != null)
            {
                const float arrowLen = 40.0f;
                // source 화살표 (1차 클릭 후 유지)
                if (m_nFaceSnapClick == 1)
                {
                    DrawFaceNormalArrow(
                        m_dSnapSrcCx, m_dSnapSrcCy, m_dSnapSrcCz,
                        m_dSnapSrcNx, m_dSnapSrcNy, m_dSnapSrcNz,
                        Color.Yellow, arrowLen);
                }
                // hover target 화살표
                if (m_bSnapHoverActive)
                {
                    DrawFaceNormalArrow(
                        m_dSnapHovCx, m_dSnapHovCy, m_dSnapHovCz,
                        m_dSnapHovNx, m_dSnapHovNy, m_dSnapHovNz,
                        Color.Cyan, arrowLen);
                }
            }

            // 디버그: 마우스 월드 좌표에 십자선 표시
            if (m_bDbgShowCrosshair && m_C3d != null)
            {
                float sz = 10.0f;
                // X 방향 선
                m_C3d.User_Set_Init(true);
                m_C3d.User_Set_Model("#17"); // line
                m_C3d.User_Set_Color(Color.Yellow);
                m_C3d.User_Set_Alpha(1.0f);
                m_C3d.User_Set_nPickGroup_A(-1);
                m_C3d.User_Set_nPickGroup_B(-1);
                m_C3d.User_Set_nPickGroup_C(-1);
                m_C3d.User_Set_Points_Clear();
                m_C3d.User_Set_Points_Add(m_fDbgWorldX - sz, m_fDbgWorldY, m_fDbgWorldZ);
                m_C3d.User_Set_Points_Add(m_fDbgWorldX + sz, m_fDbgWorldY, m_fDbgWorldZ);
                m_C3d.User_Add();
                // Y 방향 선
                m_C3d.User_Set_Init(true);
                m_C3d.User_Set_Model("#17");
                m_C3d.User_Set_Color(Color.Yellow);
                m_C3d.User_Set_Alpha(1.0f);
                m_C3d.User_Set_nPickGroup_A(-1);
                m_C3d.User_Set_nPickGroup_B(-1);
                m_C3d.User_Set_nPickGroup_C(-1);
                m_C3d.User_Set_Points_Clear();
                m_C3d.User_Set_Points_Add(m_fDbgWorldX, m_fDbgWorldY - sz, m_fDbgWorldZ);
                m_C3d.User_Set_Points_Add(m_fDbgWorldX, m_fDbgWorldY + sz, m_fDbgWorldZ);
                m_C3d.User_Add();
            }

            // 로컬 좌표축 표시: DH 끝점에서 회전된 축 방향을 버튼 색상으로 표시
            if (m_bShowLocalAxis)
            {
                if (m_C3d != null && m_Builder.StepCount > 0)
                {
                    int selIdx = lstHistory.SelectedIndex;
                    // 선택된 스텝까지의 끝점, 미선택 시 체인 전체 끝점
                    int upTo = (selIdx >= 0 && selIdx < m_Builder.StepCount) ? selIdx + 1 : -1;
                    m_C3d.DrawLocalAxes(m_Builder, upTo);
                }
            }

            // DH 파라미터 텍스트박스 갱신 (드래그 중 임시 스텝은 제외, 확정된 것만)
            if (tempStep == null && txtDhParams != null && !txtDhParams.Focused)
                txtDhParams.Text = m_Builder.GenerateFullDh().Replace("\r\n", "\r\n");
        }

        // DrawLocalAxes → m_C3d.DrawLocalAxes 로 이동됨
        // DrawAxisLine → m_C3d.DrawAxisLine 로 이동됨

        /// <summary>
        /// DH 파라미터 텍스트를 직접 편집 후 적용
        /// </summary>
        private void btnApplyDh_Click(object sender, EventArgs e)
        {
            string dhText = txtDhParams.Text.Trim();
            // 빈 텍스트도 그대로 통과시켜 빌더/lstHistory/3D 모두 초기화한다
            m_Builder.ImportFromText(dhText);
            RefreshHistory();
            MakeAll(dhText);
            ClearDhEditSelection();
            if (tabRight.SelectedTab == tabTest) UpdateMotorList();
            lblStatus.Text = string.IsNullOrEmpty(dhText) ? "DH cleared" : "DH applied";
            // 시뮬(Isaac)이 떠 있으면 변경된 기구/카메라를 핫 리로드로 즉시 반영
            if (!string.IsNullOrEmpty(dhText)) TrySimReloadAfterApply();
        }

        // ========================================
        // 히스토리 관리
        // ========================================
        private void RefreshHistory(int selectIndex = -1)
        {
            // 호출 전 선택 상태 캡쳐 → 명시 인자 없으면 보존 (마지막 항목 자동선택 X)
            int prevSelected = lstHistory.SelectedIndex;
            m_bSyncingSelection = true;
            lstHistory.Items.Clear();
            for (int i = 0; i < m_Builder.StepCount; i++)
            {
                lstHistory.Items.Add(string.Format("[{0}] {1}",
                    i + 1, m_Builder.GetStep(i).Description));
            }
            if (selectIndex >= 0 && selectIndex < lstHistory.Items.Count)
                lstHistory.SelectedIndex = selectIndex;
            else if (prevSelected >= 0 && prevSelected < lstHistory.Items.Count)
                lstHistory.SelectedIndex = prevSelected;     // ← 보존
            else if (lstHistory.Items.Count > 0)
                lstHistory.SelectedIndex = lstHistory.Items.Count - 1;
            m_bSyncingSelection = false;
        }

        /// <summary>히스토리 항목 선택 → txtDhParams 줄 + 3D 동기화</summary>
        private void lstHistory_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (m_bSyncingSelection) return;
            int idx = lstHistory.SelectedIndex;
            if (idx < 0 || idx >= m_Builder.StepCount) return;

            m_bSyncingSelection = true;
            try
            {
                int dhIdx = m_Builder.MapStepToDhLine(idx);
                SelectDhTextLineByDhIndex(dhIdx);
                // 선택된 STL 의 offset/회전 값을 Snap 탭 텍스트박스에 반영
                SyncSnapManual();
            }
            finally { m_bSyncingSelection = false; }
        }

        /// <summary>
        /// 3D 피킹 결과로 히스토리 항목 선택.
        /// PickGroup_B(nMotor)와 일치하는 모터/STL 스텝을 찾아 선택.
        /// </summary>
        private int SelectHistoryByPickGroup(int nMotor)
        {
            if (nMotor < 0) return -1;

            // PickGroup은 모터 번호 기준으로 할당됨
            // 각 스텝이 어떤 모터 그룹에 속하는지 추적
            int currentGroup = -1;
            int bestIdx = -1;
            for (int i = 0; i < m_Builder.StepCount; i++)
            {
                var step = m_Builder.GetStep(i);
                if (step.Action == BuildAction.Motor)
                    currentGroup = step.MotorNumber;

                // 현재 그룹이 클릭된 그룹과 일치하는 스텝 중 마지막 것 선택
                if (currentGroup == nMotor)
                    bestIdx = i;
            }

            if (bestIdx >= 0 && bestIdx < lstHistory.Items.Count)
            {
                lstHistory.SelectedIndex = bestIdx;
                var step = m_Builder.GetStep(bestIdx);
                lblStatus.Text = string.Format("Selected: [{0}] {1}", bestIdx + 1, step.Description);
            }
            return bestIdx;
        }

        private void btnUndo_Click(object sender, EventArgs e)
        {
            m_Builder.RemoveLastStep();
            RefreshHistory();
            UpdatePreview(null);
        }

        private void btnDelete_Click(object sender, EventArgs e)
        {
            int idx = lstHistory.SelectedIndex;
            if (idx >= 0)
            {
                m_Builder.RemoveStepAt(idx);
                RefreshHistory();
                UpdatePreview(null);
            }
        }

        private void btnClear_Click(object sender, EventArgs e)
        {
            if (m_Builder.StepCount > 0)
            {
                var result = MessageBox.Show("Delete all steps?", "Clear All",
                    MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                if (result == DialogResult.Yes)
                {
                    m_Builder.Clear();
                    RefreshHistory();
                    UpdatePreview(null);
                    ClearDhEditSelection();
                    lblStatus.Text = "All cleared";
                }
            }
        }

        // ========================================
        // ========================================
        // URDF HTML 뷰어 생성 (MJCF 도 XML 이라 재사용)
        // ========================================
        private void OpenUrdfInBrowser(string urdfXml, string htmlPath)
        {
            OpenXmlInBrowser(urdfXml, htmlPath, "URDF Viewer", "robot_stl.urdf");
        }

        /// <summary>XML 텍스트 (URDF / MJCF 등) 를 구문 하이라이팅 HTML 로 만들어 브라우저 오픈.</summary>
        private void OpenXmlInBrowser(string xml, string htmlPath, string title, string subtitle)
        {
            StringBuilder h = new StringBuilder();
            h.AppendLine("<!DOCTYPE html>");
            h.AppendLine("<html lang=\"ko\"><head><meta charset=\"UTF-8\">");
            h.AppendFormat("<title>{0}</title>\n", Esc(title));
            h.AppendLine("<style>");
            h.AppendLine("*{margin:0;padding:0;box-sizing:border-box}");
            h.AppendLine("body{background:#1e1e1e;color:#d4d4d4;font-family:Consolas,monospace;padding:20px}");
            h.AppendLine("h1{color:#569cd6;font-size:20px;margin-bottom:8px}");
            h.AppendLine(".info{color:#888;font-size:13px;margin-bottom:16px}");
            h.AppendLine("table{border-collapse:collapse;width:100%}");
            h.AppendLine("td{padding:0 12px;white-space:pre;font-size:14px;line-height:1.7;vertical-align:top}");
            h.AppendLine("tr:hover{background:#2a2a2a}");
            h.AppendLine(".ln{color:#555;text-align:right;user-select:none;width:40px;padding-right:16px}");
            h.AppendLine(".tag{color:#569cd6}");
            h.AppendLine(".atn{color:#9cdcfe}");
            h.AppendLine(".atv{color:#ce9178}");
            h.AppendLine(".cmt{color:#6a9955;font-style:italic}");
            h.AppendLine(".pnc{color:#808080}");
            h.AppendLine(".kw{color:#c586c0}");
            h.AppendLine("</style></head><body>");
            h.AppendFormat("<h1>{0}</h1>\n", Esc(title));
            h.AppendFormat("<div class=\"info\">{0}</div>\n", Esc(subtitle));
            h.AppendLine("<table><tbody>");

            string[] lines = xml.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
            for (int i = 0; i < lines.Length; i++)
            {
                string line = lines[i];
                if (line.TrimEnd().Length == 0 && i == lines.Length - 1) break;
                h.AppendFormat("<tr><td class=\"ln\">{0}</td><td>", i + 1);
                h.Append(ColorizeXmlLine(line));
                h.AppendLine("</td></tr>");
            }
            h.AppendLine("</tbody></table></body></html>");
            File.WriteAllText(htmlPath, h.ToString(), Encoding.UTF8);
            try { Process.Start(htmlPath); } catch { }
        }

        /// <summary>USDA 텍스트를 구문 하이라이팅 HTML 로 만들어 브라우저 오픈.
        /// XML 이 아니므로 별도 하이라이터 사용 (keyword / string / comment / brace).</summary>
        private void OpenUsdaInBrowser(string usda, string htmlPath, string subtitle)
        {
            StringBuilder h = new StringBuilder();
            h.AppendLine("<!DOCTYPE html>");
            h.AppendLine("<html lang=\"ko\"><head><meta charset=\"UTF-8\">");
            h.AppendLine("<title>USD (USDA) Viewer</title>");
            h.AppendLine("<style>");
            h.AppendLine("*{margin:0;padding:0;box-sizing:border-box}");
            h.AppendLine("body{background:#1e1e1e;color:#d4d4d4;font-family:Consolas,monospace;padding:20px}");
            h.AppendLine("h1{color:#4ec9b0;font-size:20px;margin-bottom:8px}");
            h.AppendLine(".info{color:#888;font-size:13px;margin-bottom:16px}");
            h.AppendLine("table{border-collapse:collapse;width:100%}");
            h.AppendLine("td{padding:0 12px;white-space:pre;font-size:14px;line-height:1.7;vertical-align:top}");
            h.AppendLine("tr:hover{background:#2a2a2a}");
            h.AppendLine(".ln{color:#555;text-align:right;user-select:none;width:40px;padding-right:16px}");
            h.AppendLine(".kw{color:#c586c0}");     // def / prepend / rel / uniform 등 키워드
            h.AppendLine(".ty{color:#4ec9b0}");     // 타입 (Xform / Sphere / Camera / float / double 등)
            h.AppendLine(".at{color:#9cdcfe}");     // attribute (xformOp:translate 등)
            h.AppendLine(".st{color:#ce9178}");     // 문자열 리터럴 \"...\"
            h.AppendLine(".num{color:#b5cea8}");    // 숫자
            h.AppendLine(".cmt{color:#6a9955;font-style:italic}");
            h.AppendLine(".pnc{color:#808080}");    // 구두점
            h.AppendLine("</style></head><body>");
            h.AppendLine("<h1>USD (USDA) Viewer</h1>");
            h.AppendFormat("<div class=\"info\">{0}</div>\n", Esc(subtitle));
            h.AppendLine("<table><tbody>");

            // STL 임베드 시 points 배열 한 줄이 수 MB 가 될 수 있음 → 줄 길이/줄 수 제한
            //   (브라우저 멈춤 방지 — 원본 확인은 .usda 파일을 에디터로)
            const int MAX_LINE_CHARS = 400;
            const int MAX_LINES = 4000;
            string[] lines = usda.Split(new[] { "\r\n", "\n" }, StringSplitOptions.None);
            int shown = Math.Min(lines.Length, MAX_LINES);
            for (int i = 0; i < shown; i++)
            {
                string line = lines[i];
                if (line.TrimEnd().Length == 0 && i == lines.Length - 1) break;
                bool truncated = line.Length > MAX_LINE_CHARS;
                if (truncated) line = line.Substring(0, MAX_LINE_CHARS);
                h.AppendFormat("<tr><td class=\"ln\">{0}</td><td>", i + 1);
                h.Append(ColorizeUsdaLine(line));
                if (truncated)
                    h.AppendFormat("<span class=\"cmt\">  … ({0:N0}자 생략 — 원본은 .usda 파일 참조)</span>", lines[i].Length - MAX_LINE_CHARS);
                h.AppendLine("</td></tr>");
            }
            if (lines.Length > MAX_LINES)
                h.AppendFormat("<tr><td class=\"ln\">…</td><td><span class=\"cmt\"># … 총 {0:N0}줄 중 {1:N0}줄만 표시 (원본은 .usda 파일 참조)</span></td></tr>\n",
                    lines.Length, MAX_LINES);
            h.AppendLine("</tbody></table></body></html>");
            File.WriteAllText(htmlPath, h.ToString(), Encoding.UTF8);
            try { Process.Start(htmlPath); } catch { }
        }

        /// <summary>USDA 한 줄을 HTML 구문 하이라이팅 (심플 토큰 스캐너).</summary>
        private static string ColorizeUsdaLine(string line)
        {
            // 대문자로 시작하는 USDA 키워드 및 타입 집합
            var kwSet = new HashSet<string> {
                "def","over","class","prepend","append","uniform","varying","rel","add","delete","reorder",
                "custom","references","payload","subLayers","defaultPrim","metersPerUnit","upAxis",
                "apiSchemas","physics","drive"
            };
            var tySet = new HashSet<string> {
                "Xform","Sphere","Cylinder","Cube","Cone","Mesh","Camera","Scope","Material","Shader",
                "PhysicsScene","PhysicsFixedJoint","PhysicsRevoluteJoint","PhysicsPrismaticJoint","PhysicsMeshCollisionAPI",
                "PhysicsRigidBodyAPI","PhysicsMassAPI","PhysicsArticulationRootAPI",
                "float","double","int","token","string","bool","asset","point3f","vector3f","color3f","quatf","matrix4d",
                "double3","float3","float4","true","false"
            };
            StringBuilder sb = new StringBuilder();
            int pos = 0;
            int len = line.Length;
            while (pos < len)
            {
                char ch = line[pos];
                // 주석 # ... 끝까지
                if (ch == '#')
                {
                    sb.AppendFormat("<span class=\"cmt\">{0}</span>", Esc(line.Substring(pos)));
                    break;
                }
                // 문자열 리터럴 "..." (에스케이프 미지원 — USDA 실무 충분)
                if (ch == '"')
                {
                    int end = line.IndexOf('"', pos + 1);
                    if (end < 0) end = len - 1;
                    sb.AppendFormat("<span class=\"st\">{0}</span>", Esc(line.Substring(pos, end + 1 - pos)));
                    pos = end + 1;
                    continue;
                }
                // asset 리터럴 @...@
                if (ch == '@')
                {
                    int end = line.IndexOf('@', pos + 1);
                    if (end < 0) end = len - 1;
                    sb.AppendFormat("<span class=\"st\">{0}</span>", Esc(line.Substring(pos, end + 1 - pos)));
                    pos = end + 1;
                    continue;
                }
                // 숫자 (±소수 포함)
                if (char.IsDigit(ch) || (ch == '-' && pos + 1 < len && (char.IsDigit(line[pos + 1]) || line[pos + 1] == '.')))
                {
                    int start = pos;
                    if (ch == '-') pos++;
                    while (pos < len && (char.IsDigit(line[pos]) || line[pos] == '.' || line[pos] == 'e' || line[pos] == 'E' || line[pos] == '+' || line[pos] == '-'))
                    {
                        // -는 지수부에서만
                        if (line[pos] == '-' && (pos == start || (line[pos-1] != 'e' && line[pos-1] != 'E'))) break;
                        pos++;
                    }
                    sb.AppendFormat("<span class=\"num\">{0}</span>", Esc(line.Substring(start, pos - start)));
                    continue;
                }
                // 식별자
                if (char.IsLetter(ch) || ch == '_')
                {
                    int start = pos;
                    while (pos < len && (char.IsLetterOrDigit(line[pos]) || line[pos] == '_' || line[pos] == ':')) pos++;
                    string tok = line.Substring(start, pos - start);
                    string cls;
                    if (kwSet.Contains(tok)) cls = "kw";
                    else if (tySet.Contains(tok)) cls = "ty";
                    else if (tok.Contains(":")) cls = "at";   // xformOp:translate 같은 attribute 경로
                    else cls = "at";
                    sb.AppendFormat("<span class=\"{0}\">{1}</span>", cls, Esc(tok));
                    continue;
                }
                // 구두점 / 공백
                if ("(){}[],=/<>".IndexOf(ch) >= 0)
                {
                    sb.AppendFormat("<span class=\"pnc\">{0}</span>", Esc(ch.ToString()));
                }
                else
                {
                    sb.Append(Esc(ch.ToString()));
                }
                pos++;
            }
            return sb.ToString();
        }

        /// <summary>XML 한 줄을 HTML 구문 하이라이팅</summary>
        private static string ColorizeXmlLine(string line)
        {
            StringBuilder sb = new StringBuilder();
            int pos = 0;
            int len = line.Length;

            while (pos < len)
            {
                // 주석: <!-- ... -->
                if (pos + 3 < len && line[pos] == '<' && line[pos + 1] == '!'
                    && line[pos + 2] == '-' && line[pos + 3] == '-')
                {
                    int end = line.IndexOf("-->", pos + 4);
                    if (end < 0) end = len - 3;
                    string comment = line.Substring(pos, end + 3 - pos);
                    sb.AppendFormat("<span class=\"cmt\">{0}</span>", Esc(comment));
                    pos = end + 3;
                    continue;
                }

                // XML 선언: <?xml ... ?>
                if (pos + 1 < len && line[pos] == '<' && line[pos + 1] == '?')
                {
                    int end = line.IndexOf("?>", pos + 2);
                    if (end < 0) end = len - 2;
                    string decl = line.Substring(pos, end + 2 - pos);
                    sb.AppendFormat("<span class=\"kw\">{0}</span>", Esc(decl));
                    pos = end + 2;
                    continue;
                }

                // 닫는 태그: </tagname>
                if (pos + 1 < len && line[pos] == '<' && line[pos + 1] == '/')
                {
                    int end = line.IndexOf('>', pos + 2);
                    if (end < 0) end = len - 1;
                    string tagName = line.Substring(pos + 2, end - pos - 2).Trim();
                    sb.AppendFormat("<span class=\"pnc\">&lt;/</span><span class=\"tag\">{0}</span><span class=\"pnc\">&gt;</span>",
                        Esc(tagName));
                    pos = end + 1;
                    continue;
                }

                // 여는 태그: <tagname attr="val" ...> 또는 <tagname ... />
                if (line[pos] == '<' && pos + 1 < len && char.IsLetter(line[pos + 1]))
                {
                    // 태그 이름 추출
                    int nameStart = pos + 1;
                    int nameEnd = nameStart;
                    while (nameEnd < len && !char.IsWhiteSpace(line[nameEnd])
                           && line[nameEnd] != '>' && line[nameEnd] != '/')
                        nameEnd++;

                    string tagName = line.Substring(nameStart, nameEnd - nameStart);
                    sb.AppendFormat("<span class=\"pnc\">&lt;</span><span class=\"tag\">{0}</span>", Esc(tagName));

                    pos = nameEnd;

                    // 속성 파싱
                    while (pos < len && line[pos] != '>' && !(line[pos] == '/' && pos + 1 < len && line[pos + 1] == '>'))
                    {
                        // 공백 건너뛰기
                        if (char.IsWhiteSpace(line[pos]))
                        {
                            sb.Append(line[pos]);
                            pos++;
                            continue;
                        }

                        // 속성이름=값
                        if (char.IsLetter(line[pos]) || line[pos] == '_')
                        {
                            int aStart = pos;
                            while (pos < len && line[pos] != '=' && line[pos] != '>'
                                   && !char.IsWhiteSpace(line[pos]) && line[pos] != '/')
                                pos++;
                            string attrName = line.Substring(aStart, pos - aStart);
                            sb.AppendFormat("<span class=\"atn\">{0}</span>", Esc(attrName));

                            // = 부호
                            if (pos < len && line[pos] == '=')
                            {
                                sb.Append("<span class=\"pnc\">=</span>");
                                pos++;

                                // 값 (따옴표)
                                if (pos < len && (line[pos] == '"' || line[pos] == '\''))
                                {
                                    char q = line[pos];
                                    int vEnd = line.IndexOf(q, pos + 1);
                                    if (vEnd < 0) vEnd = len - 1;
                                    string val = line.Substring(pos, vEnd + 1 - pos);
                                    sb.AppendFormat("<span class=\"atv\">{0}</span>", Esc(val));
                                    pos = vEnd + 1;
                                }
                            }
                            continue;
                        }

                        // 기타 문자
                        sb.Append(Esc(line[pos].ToString()));
                        pos++;
                    }

                    // 자기닫기 /> 또는 >
                    if (pos < len && line[pos] == '/' && pos + 1 < len && line[pos + 1] == '>')
                    {
                        sb.Append("<span class=\"pnc\">/&gt;</span>");
                        pos += 2;
                    }
                    else if (pos < len && line[pos] == '>')
                    {
                        sb.Append("<span class=\"pnc\">&gt;</span>");
                        pos++;
                    }
                    continue;
                }

                // 텍스트 내용 (태그 밖)
                int nextTag = line.IndexOf('<', pos);
                if (nextTag < 0) nextTag = len;
                if (nextTag > pos)
                {
                    sb.Append(Esc(line.Substring(pos, nextTag - pos)));
                    pos = nextTag;
                }
                else
                {
                    sb.Append(Esc(line[pos].ToString()));
                    pos++;
                }
            }

            return sb.ToString();
        }

        private static string Esc(string s)
        {
            return s.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
        }

        // URDF/MJCF 내보내기 (Kinematics:908 패턴)
        // ========================================
        /// <summary>
        /// 현재 설정된 출력 폴더 이름 반환 (비어있으면 Application.StartupPath 직접 사용)
        /// </summary>
        private string GetUrdfOutputDir()
        {
            string folderName = txtUrdfFolder.Text.Trim();
            if (string.IsNullOrEmpty(folderName))
                return Application.StartupPath;
            return Path.Combine(Application.StartupPath, folderName);
        }

        /// <summary>
        /// STL 서브폴더 이름 반환 (비어있으면 null → STL 폴더 없이 URDF 폴더에 직접 저장)
        /// </summary>
        private string GetStlSubFolder()
        {
            string s = txtStlFolder.Text.Trim();
            return string.IsNullOrEmpty(s) ? null : s;
        }

        /// <summary>
        /// strUrdfCommand 중간언어에서 mesh 명령의 파일명(STL) 목록 수집
        /// </summary>
        private static List<string> CollectMeshFilenames(string strUrdfCommand)
        {
            var result = new List<string>();
            foreach (string line in strUrdfCommand.Split('\n'))
            {
                string t = line.Trim();
                if (!t.StartsWith("mesh,")) continue;
                string[] parts = t.Split(',');
                if (parts.Length < 2) continue;
                string fname = parts[1].Trim();
                if (!string.IsNullOrEmpty(fname) && !result.Contains(fname))
                    result.Add(fname);
            }
            return result;
        }

        /// <summary>
        /// URDF/MJCF 파일 생성 및 저장 (브라우저 열기 없음)
        /// </summary>
        private bool ExportUrdfFiles()
        {
            try
            {
                string dhString = m_Builder.GenerateFullDh();
                if (string.IsNullOrWhiteSpace(dhString))
                {
                    Ojw.printf(txtLogHistory, "[Export] Build a robot first!\r\n");
                    return false;
                }

                // ── EDH 엄격 구문 검증 (OpenJigWare\COjw_12_3D_EdhValidator.cs, silent failure 차단) ──
                // 경고만 출력하고 Export 는 계속한다 (기존 동작 비차단).
                List<string> edhSyntaxErrors = OpenJigWare.CEdhValidator.Validate(dhString);
                if (edhSyntaxErrors.Count > 0)
                {
                    Ojw.printf(txtLogHistory, "[EDH 검증] 문법 경고 {0}건 (Export 는 계속):\r\n", edhSyntaxErrors.Count);
                    for (int ei = 0; ei < edhSyntaxErrors.Count && ei < 10; ei++)
                        Ojw.printf(txtLogHistory, "  {0}\r\n", edhSyntaxErrors[ei]);
                }

                // ── 폴더 결정 ──────────────────────────────────────
                string urdfDir  = GetUrdfOutputDir();
                string stlSub   = GetStlSubFolder();          // null이면 STL 서브폴더 없음
                string stlDir   = stlSub != null
                                  ? Path.Combine(urdfDir, stlSub)
                                  : urdfDir;
                string meshPrefix = stlSub;                   // URDF 내 경로 prefix (null이면 없음)

                Directory.CreateDirectory(urdfDir);
                Directory.CreateDirectory(stlDir);

                // ── URDF 중간언어 생성 ─────────────────────────────
                string strUrdfCommand = "";
                string strUrdfXml     = "";

                bool bShowSkeleton, bShowMesh;
                GetViewModeFlags(out bShowSkeleton, out bShowMesh);

                float fSkeletonSize = Ojw.CConvert.StrToFloat(txtSkeletonSize.Text);
                if (fSkeletonSize <= 0) fSkeletonSize = 10.0f;
                float fAxisSize = Ojw.CConvert.StrToFloat(txtAxisSize.Text);
                if (fAxisSize <= 0) fAxisSize = 20.0f;

                m_C3d.MakeDHSkeleton_Urdf(
                    false, true, bShowSkeleton, bShowMesh, fSkeletonSize, fAxisSize, Color.Violet,
                    dhString, 0, 0, 0, 0, 0, 0, 0,
                    ref txtMessage,
                    ref strUrdfCommand,
                    ref strUrdfXml);

                // ── STL 파일 복사 ──────────────────────────────────
                // STL 원본 위치: SetAseFile_Path("stl")로 설정된 경로 (예: Release\stl\)
                string stlSrcDir = Application.StartupPath.TrimEnd('\\')
                                   + (m_C3d != null ? m_C3d.GetAseFile_Path() : "\\stl\\");

                List<string> stlFiles = CollectMeshFilenames(strUrdfCommand);
                foreach (string fname in stlFiles)
                {
                    string justName = Path.GetFileName(fname);
                    // 후보 소스 경로: 1) SetAseFile_Path 폴더, 2) StartupPath 직접
                    string src = Path.Combine(stlSrcDir, justName);
                    if (!File.Exists(src))
                        src = Path.Combine(Application.StartupPath, justName);

                    string dst = Path.Combine(stlDir, justName);
                    if (File.Exists(src))
                    {
                        File.Copy(src, dst, true);
                        Ojw.printf(txtLogHistory, "[Export] STL 복사: {0}\r\n", justName);
                    }
                    else
                    {
                        Ojw.printf(txtLogHistory, "[Export] STL 없음(스킵): {0}\r\n", justName);
                    }
                }

                // ── URDF 재생성 (MeshFolder prefix 적용) ──────────
                var urdfBuilder = new Ojw.C3d.COjwUrdfBuilder_t();
                urdfBuilder.RobotName  = "ojw_robot";
                urdfBuilder.MeshFolder = meshPrefix;  // null이면 prefix 없음
                urdfBuilder.ExportScene = chkExportScene.Checked;   // $scene 항목 출력 토글
                if (chkFixedBase.Checked)
                    urdfBuilder.SetWorldFixed();
                urdfBuilder.ParseCommands(strUrdfCommand);
                strUrdfXml = urdfBuilder.Build();

                // ── URDF 물리 속성 자동 기입 (관성/질량/서보 limit — fix_ojw_urdf.py 포팅) ──
                //   플레이스홀더 <inertial> 을 collision STL 기반 실측치로 재계산.
                //   실패 시 원본 유지 (Export 는 계속).
                if (m_chkUrdfPhysics == null || m_chkUrdfPhysics.Checked)
                {
                    try
                    {
                        var phys = new Ojw.C3d.COjwUrdfPhysics_t();
                        // P1: EDH 물리 지시자 ($servo 기종 / $jointrange 가동범위 / $extramass 뭉치질량)
                        //     — ProcessUrdf 전에 적용해야 관절 limit/질량에 반영됨
                        string dirLog = phys.ApplyEdhDirectives(dhString);
                        if (!string.IsNullOrEmpty(dirLog)) Ojw.printf(txtLogHistory, "{0}", dirLog);
                        foreach (string wPhys in phys.Warnings)
                            Ojw.printf(txtLogHistory, "[Physics] 경고: {0}\r\n", wPhys);
                        string physLog;
                        strUrdfXml = phys.ProcessUrdf(strUrdfXml, urdfDir, out physLog);
                        Ojw.printf(txtLogHistory, "{0}", physLog);
                        foreach (string wPhys in phys.Warnings)
                            Ojw.printf(txtLogHistory, "[Physics] 경고: {0}\r\n", wPhys);
                    }
                    catch (Exception physEx)
                    {
                        Ojw.printf(txtLogHistory, "[Physics] 자동 기입 실패 (원본 유지): {0}\r\n", physEx.Message);
                    }
                }

                // ── 파일 저장 (PyBullet/MuJoCo용 — mimic 보존) ────────
                string urdfPath = Path.Combine(urdfDir, "robot_stl.urdf");
                File.WriteAllText(urdfPath, strUrdfXml, Encoding.UTF8);
                Ojw.printf(txtLogHistory, "[Export] {0} 저장 완료\r\n", urdfPath);

                // ── world_fixed 카메라 별도 출력 ($scene 패턴, robot URDF 와 무관) ────────
                {
                    string worldCamsPath = Path.Combine(urdfDir, "world_cameras.json");
                    if (urdfBuilder.HasWorldCameras())
                    {
                        // BOM 없이 저장 — Python json.load 가 BOM 을 처리 못함 (utf-8 vs utf-8-sig)
                        File.WriteAllText(worldCamsPath, urdfBuilder.BuildWorldCamerasJson(), new UTF8Encoding(false));
                        Ojw.printf(txtLogHistory, "[Export] {0} 저장 완료 (world_fixed 카메라)\r\n", worldCamsPath);
                    }
                    else if (File.Exists(worldCamsPath))
                    {
                        // 이전 로봇 (예: OMX) export 가 남긴 낡은 파일 삭제 —
                        // 안 지우면 카메라 없는 로봇 (휴머노이드 등) 로드 시 유령 카메라 마커가 나타남
                        try
                        {
                            File.Delete(worldCamsPath);
                            Ojw.printf(txtLogHistory, "[Export] 낡은 world_cameras.json 삭제 (현재 로봇에 world 카메라 없음)\r\n");
                        }
                        catch { }
                    }
                }

                // ── 종동(passive) 조인트 메타 출력 (델타 등 폐루프 퍼펫팅용) ────────
                //   러너/뷰어가 매 스텝 수식을 평가해 dpass_* 조인트를 구동한다.
                {
                    string passivePath = Path.Combine(urdfDir, "delta_passive.json");
                    var lstPassive = m_C3d.GetLastPassiveJointsUrdf();
                    if (lstPassive != null && lstPassive.Count > 0)
                    {
                        File.WriteAllText(passivePath, m_C3d.BuildPassiveJointsJson(), new UTF8Encoding(false));
                        Ojw.printf(txtLogHistory, "[Export] {0} 저장 완료 (종동 조인트 {1}개 — 퍼펫팅 메타)\r\n", passivePath, lstPassive.Count);
                    }
                    else if (File.Exists(passivePath))
                    {
                        try { File.Delete(passivePath); } catch { } // 이전 로봇 잔재 제거
                    }
                }

                // ── Isaac Sim 전용 URDF 생성 (mimic 제거 등) ──────────
                List<string> isaacLog;
                string strIsaacXml = SanitizeUrdfForIsaacSim(strUrdfXml, stlDir, out isaacLog);
                string isaacPath = Path.Combine(urdfDir, "robot_stl_isaac.urdf");
                File.WriteAllText(isaacPath, strIsaacXml, Encoding.UTF8);
                Ojw.printf(txtLogHistory, "[Isaac] ── Isaac Sim 호환 후처리 ──────────────\r\n");
                Ojw.printf(txtLogHistory, "[Isaac] {0} 저장 완료\r\n", isaacPath);
                if (isaacLog.Count == 0)
                    Ojw.printf(txtLogHistory, "[Isaac] 변경 없음\r\n");
                else
                    foreach (string entry in isaacLog)
                        Ojw.printf(txtLogHistory, "{0}\r\n", entry);

                // 중간언어 저장
                File.WriteAllText(Path.Combine(urdfDir, "robot_commands.txt"),
                                  strUrdfCommand, Encoding.UTF8);

                // MJCF 생성 및 저장
                // MeshFolder가 설정된 경우 URDF filename에 이미 "stl/..." 경로가 포함되므로
                // meshdir에 중복 지정하지 않도록 "." 전달
                var mjcfBuilder = new Ojw.C3d.COjwUrdfBuilder_t();
                mjcfBuilder.RobotName  = "ojw_robot";
                mjcfBuilder.MeshFolder = meshPrefix;
                if (chkFixedBase.Checked)
                    mjcfBuilder.SetWorldFixed();
                mjcfBuilder.ParseCommands(strUrdfCommand);
                // 물리 자동기입 ON 이면 처리된 URDF 로 변환 — 마커 감지 시 <inertial> 을 MJCF body 에 반영.
                // OFF 면 기존 경로 (Build() 재생성) 그대로 → 기존 출력과 diff 0
                string strMjcfXml = (m_chkUrdfPhysics == null || m_chkUrdfPhysics.Checked)
                    ? mjcfBuilder.BuildMjcfFromUrdf(strUrdfXml, ".")
                    : mjcfBuilder.BuildMjcf("robot_stl.urdf", ".");

                string mjcfPath = Path.Combine(urdfDir, "robot_stl.xml");
                File.WriteAllText(mjcfPath, strMjcfXml, Encoding.UTF8);
                Ojw.printf(txtLogHistory, "[Export] {0} 저장 완료\r\n", mjcfPath);

                // 트랙 벨트 메타데이터 JSON 저장 (런타임 Python 스크립트가 belt flow 애니메이션에 사용)
                try
                {
                    var trackMetas = m_C3d.GetLastTrackBeltMetasUrdf();
                    if (trackMetas != null && trackMetas.Count > 0)
                    {
                        // URDF 의 mesh filename 과 일관성 맞추기 위해 meshPrefix 적용
                        if (!string.IsNullOrEmpty(meshPrefix))
                        {
                            string prefix = meshPrefix.TrimEnd('/', '\\');
                            foreach (var m in trackMetas)
                            {
                                if (!string.IsNullOrEmpty(m.segmentStl) &&
                                    !m.segmentStl.Contains("/") && !m.segmentStl.Contains("\\"))
                                {
                                    m.segmentStl = prefix + "/" + m.segmentStl;
                                }
                            }
                        }
                        string trackJsonPath = Path.Combine(urdfDir, "robot_stl_tracks.json");
                        string trackJson = m_C3d.BuildTrackBeltJson();
                        File.WriteAllText(trackJsonPath, trackJson, Encoding.UTF8);
                        Ojw.printf(txtLogHistory, "[Export] {0} 저장 완료 (트랙 {1}개)\r\n",
                            trackJsonPath, trackMetas.Count);
                    }
                    else
                    {
                        // ★트랙 없는 로봇 Export 시 이전 로봇(탱크 등)의 트랙 JSON 잔존 방지 —
                        //   낡은 부산물이 PyBullet 뷰어의 트랙 전처리를 오작동시킨다
                        //   (delta_passive.json/world_cameras.json 과 동일한 "없으면 삭제" 규약)
                        string trackJsonPath = Path.Combine(urdfDir, "robot_stl_tracks.json");
                        if (File.Exists(trackJsonPath))
                        {
                            File.Delete(trackJsonPath);
                            Ojw.printf(txtLogHistory, "[Export] {0} 삭제 (이 로봇은 트랙 없음)\r\n", trackJsonPath);
                        }
                    }
                }
                catch (Exception exTrack)
                {
                    Ojw.printf(txtLogHistory, "[Export] 트랙 JSON 저장 실패: {0}\r\n", exTrack.Message);
                }

                Ojw.printf(txtLogHistory, "[Export] 완료 → {0}\r\n", urdfDir);
                return true;
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Export] 오류: {0}\r\n", ex.Message);
                return false;
            }
        }

        /// <summary>Isaac Sim 호환 URDF 후처리 (DLL 위임 — mimic 제거 + STL 파일명 정규화)</summary>
        private string SanitizeUrdfForIsaacSim(string urdf, string stlDir, out List<string> log)
        {
            return Ojw.C3d.COjwUrdfBuilder_t.SanitizeUrdfForIsaacSim(urdf, stlDir, out log);
        }

        // ========================================
        // Robot Config 내보내기 (FK/IK용 DH 텍스트 파일)
        // ========================================
        private void btnExportConfig_Click(object sender, EventArgs e)
        {
            try
            {
                string dhString = m_Builder.GenerateFullDh();
                if (string.IsNullOrWhiteSpace(dhString))
                {
                    Ojw.printf(txtLogHistory, "[Config] Build a robot first!\r\n");
                    return;
                }

                // SaveFileDialog로 저장 위치 선택
                SaveFileDialog dlg = new SaveFileDialog();
                dlg.Title = "Save Robot Config";
                dlg.Filter = "Text files (*.txt)|*.txt|All files (*.*)|*.*";
                dlg.FileName = "robot_config.txt";
                dlg.InitialDirectory = Path.GetDirectoryName(Application.ExecutablePath) ?? ".";

                if (dlg.ShowDialog() != DialogResult.OK) return;

                string configText = BuildRobotConfigText(dhString);
                File.WriteAllText(dlg.FileName, configText, Encoding.UTF8);

                Ojw.printf(txtLogHistory, "[Config] 저장 완료: {0}\r\n", dlg.FileName);
                lblStatus.Text = "Config saved";
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Config] 오류: {0}\r\n", ex.Message);
            }
        }

        /// <summary>DH 텍스트에서 robot_config.txt 내용 생성 (DLL 위임 — 손목/그리퍼 ID 는 UI 선택값)</summary>
        private string BuildRobotConfigText(string dhString)
        {
            return Ojw.C3d.Edh_BuildRobotConfigText(dhString, GetSelectedWristMotorId(), GetSelectedGripperMotorId());
        }

        /// <summary>DH 텍스트에서 유니크 모터 ID 목록 추출 (순서 유지)</summary>
        /// <summary>DH 텍스트에서 유니크 모터 ID 목록 추출 (DLL 위임)</summary>
        private List<int> ExtractMotorIds(string dhString)
        {
            return Ojw.C3d.Edh_ExtractMotorIds(dhString);
        }

        private void btnExportUrdf_Click(object sender, EventArgs e)
        {
            if (!ExportUrdfFiles()) return;

            try
            {
                // HTML 뷰어 생성 + 브라우저 열기
                string urdfDir = GetUrdfOutputDir();
                string urdfPath = Path.Combine(urdfDir, "robot_stl.urdf");
                string urdfXml = File.Exists(urdfPath) ? File.ReadAllText(urdfPath) : "";
                string htmlPath = Path.Combine(urdfDir, "robot_stl.html");
                OpenUrdfInBrowser(urdfXml, htmlPath);
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[URDF 보기] 오류: {0}\r\n", ex.Message);
            }
        }

        // ========================================
        // Win32 윈도우 전체 캡쳐 — 외부 시뮬레이터 창도 동일 패턴으로 사용
        //   PrintWindow 는 가려진 부분/오프스크린도 캡쳐 가능 (단, OpenGL/DirectX 영역은
        //   PW_RENDERFULLCONTENT(0x2) 플래그 필요 — Windows 8 이상)
        // ========================================
        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern bool PrintWindow(IntPtr hwnd, IntPtr hdcBlt, uint nFlags);

        [System.Runtime.InteropServices.DllImport("user32.dll", SetLastError = true)]
        private static extern bool GetWindowRect(IntPtr hwnd, out RECT lpRect);

        [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]
        private struct RECT { public int Left, Top, Right, Bottom; }

        private delegate bool EnumWindowsProc(IntPtr hwnd, IntPtr lParam);

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);

        [System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Auto)]
        private static extern int GetWindowText(IntPtr hwnd, System.Text.StringBuilder lpString, int nMaxCount);

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(IntPtr hwnd, out uint lpdwProcessId);

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern bool IsWindowVisible(IntPtr hwnd);

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern bool ShowWindow(IntPtr hwnd, int nCmdShow);

        [System.Runtime.InteropServices.DllImport("user32.dll")]
        private static extern bool SetForegroundWindow(IntPtr hwnd);

        private const int SW_MAXIMIZE = 3;

        /// <summary>
        /// 모든 top-level 윈도우 중 타이틀에 titlePart 포함하는 것을 찾음.
        /// titleParts 는 ';' 구분 다중 후보 가능 (예: "Isaac;Omniverse;Kit").
        /// pid > 0 이면 그 프로세스 (또는 자식) 소유 윈도우만.
        /// </summary>
        private static IntPtr FindWindowByTitlePart(string titleParts, int pid)
        {
            if (string.IsNullOrEmpty(titleParts)) return IntPtr.Zero;
            string[] parts = titleParts.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

            IntPtr found = IntPtr.Zero;
            EnumWindows((hwnd, lParam) =>
            {
                if (!IsWindowVisible(hwnd)) return true;
                if (pid > 0)
                {
                    uint wpid;
                    GetWindowThreadProcessId(hwnd, out wpid);
                    if (wpid != (uint)pid) return true;
                }
                var sb = new System.Text.StringBuilder(512);
                GetWindowText(hwnd, sb, sb.Capacity);
                string title = sb.ToString();
                if (string.IsNullOrEmpty(title)) return true;
                foreach (string p in parts)
                {
                    string pt = p.Trim();
                    if (pt.Length == 0) continue;
                    if (title.IndexOf(pt, StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        found = hwnd;
                        return false;   // 검색 중단
                    }
                }
                return true;
            }, IntPtr.Zero);
            return found;
        }

        /// <summary>
        /// titleParts (";" 구분) 중 하나에 매칭하면서 (minW, minH) 이상 크기인 윈도우 중 **면적 최대** 를 반환.
        /// blacklist ("; " 구분) 에 매칭되는 타이틀은 제외 (예: "NVIDIA GeForce Overlay" 같은 시스템 오버레이).
        /// splash/loader 같은 작은 윈도우 배제 + 메인 GUI 우선 선택용.
        /// </summary>
        private static IntPtr FindLargestWindowByTitlePart(string titleParts, int pid, int minW, int minH, string blacklist = null)
        {
            if (string.IsNullOrEmpty(titleParts)) return IntPtr.Zero;
            string[] parts = titleParts.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);
            string[] blackParts = string.IsNullOrEmpty(blacklist)
                ? new string[0]
                : blacklist.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries);

            IntPtr bestHwnd = IntPtr.Zero;
            long bestArea = 0;
            EnumWindows((hwnd, lParam) =>
            {
                if (!IsWindowVisible(hwnd)) return true;
                if (pid > 0)
                {
                    uint wpid;
                    GetWindowThreadProcessId(hwnd, out wpid);
                    if (wpid != (uint)pid) return true;
                }
                var sb = new System.Text.StringBuilder(512);
                GetWindowText(hwnd, sb, sb.Capacity);
                string title = sb.ToString();
                if (string.IsNullOrEmpty(title)) return true;
                // blacklist 체크
                foreach (string b in blackParts)
                {
                    string bt = b.Trim();
                    if (bt.Length == 0) continue;
                    if (title.IndexOf(bt, StringComparison.OrdinalIgnoreCase) >= 0) return true;   // skip
                }
                bool matched = false;
                foreach (string p in parts)
                {
                    string pt = p.Trim();
                    if (pt.Length == 0) continue;
                    if (title.IndexOf(pt, StringComparison.OrdinalIgnoreCase) >= 0) { matched = true; break; }
                }
                if (!matched) return true;
                RECT rc;
                if (!GetWindowRect(hwnd, out rc)) return true;
                int w = rc.Right - rc.Left, h = rc.Bottom - rc.Top;
                if (w < minW || h < minH) return true;
                long area = (long)w * h;
                if (area > bestArea)
                {
                    bestArea = area;
                    bestHwnd = hwnd;
                }
                return true;   // 전체 순회 (가장 큰 것 찾기 위해)
            }, IntPtr.Zero);
            return bestHwnd;
        }

        /// <summary>
        /// 디버그용 — 현재 모든 visible top-level 윈도우의 타이틀을 반환 (캡쳐 실패 시 어떤 윈도우가 있었는지 확인).
        /// pid > 0 이면 그 pid 소유 윈도우만.
        /// </summary>
        private static List<string> EnumVisibleWindowTitles(int pid)
        {
            var titles = new List<string>();
            EnumWindows((hwnd, lParam) =>
            {
                if (!IsWindowVisible(hwnd)) return true;
                if (pid > 0)
                {
                    uint wpid;
                    GetWindowThreadProcessId(hwnd, out wpid);
                    if (wpid != (uint)pid) return true;
                }
                var sb = new System.Text.StringBuilder(512);
                GetWindowText(hwnd, sb, sb.Capacity);
                string t = sb.ToString();
                if (!string.IsNullOrEmpty(t)) titles.Add(t);
                return true;
            }, IntPtr.Zero);
            return titles;
        }

        // ========================================
        // 외부 viewer 실행 후 윈도우 캡쳐 (PyBullet/MuJoCo/Isaac 공통 패턴)
        //   1) 스크립트의 release_dir/USE_FIXED_BASE 패칭 후 %TEMP% 임시 파일로 저장
        //   2) python.exe (또는 지정 인터프리터) 외부 프로세스로 실행
        //      - 환경변수 OJW_AUTO_EXIT_SEC 로 viewer 측 자동 종료 시간 전달
        //   3) waitSec 초 동안 GUI 윈도우 안정화 대기
        //   4) titlePart 매칭하는 윈도우 핸들 찾기 → PrintWindow 캡쳐
        //   5) 프로세스 종료 (graceful 또는 강제)
        // ========================================
        private bool CaptureViewerWindow(
            string scriptName,
            string outPath,
            string titlePart,
            int waitBeforeCaptureSec,
            int autoExitSec,
            string interpreterPath = "python",
            int extraStabilizeMs = 3000,
            bool detachConsole = false,
            string extraArgs = "",
            bool captureFullScreen = false)
        {
            try
            {
                string pythonDir = FindPythonDir();
                string scriptPath = Path.Combine(pythonDir, scriptName);
                if (!File.Exists(scriptPath))
                {
                    Ojw.printf(txtLogHistory, "[Capture] 스크립트 없음: {0}\r\n", scriptPath);
                    return false;
                }

                // 스크립트 패칭 (RunPythonViewer 와 동일 패턴)
                string code = File.ReadAllText(scriptPath, System.Text.Encoding.UTF8);
                string releaseDir = GetUrdfOutputDir().Replace("\\", "/");
                code = code.Replace(
                    "release_dir = os.path.join(script_dir, \"..\", \"Release\")",
                    "release_dir = r\"" + releaseDir + "\"");
                string fixedBaseStr = chkFixedBase.Checked ? "True" : "False";
                code = code.Replace(
                    "USE_FIXED_BASE = viewer_config['FIXED_BASE']",
                    "USE_FIXED_BASE = " + fixedBaseStr);

                string tmpScript = Path.Combine(Path.GetTempPath(),
                    "ojw_capture_" + Path.GetFileName(scriptName));
                File.WriteAllText(tmpScript, code, System.Text.Encoding.UTF8);

                ProcessStartInfo psi;
                if (detachConsole)
                {
                    // 새 콘솔 윈도우 분리 (Isaac Sim 같이 GUI 가 부모 콘솔에 영향받는 케이스):
                    //   batch wrapper 에서 환경변수 set + interpreter 실행 → UseShellExecute=true 로 새 콘솔
                    string wrapperBat = Path.Combine(Path.GetTempPath(),
                        "ojw_capture_wrapper_" + Path.GetFileNameWithoutExtension(scriptName) + ".bat");
                    var sb = new StringBuilder();
                    sb.AppendLine("@echo off");
                    sb.AppendLine("set OJW_AUTO_EXIT_SEC=" + autoExitSec);
                    sb.AppendLine("\"" + interpreterPath + "\" \"" + tmpScript + "\" " + extraArgs);
                    File.WriteAllText(wrapperBat, sb.ToString(), System.Text.Encoding.Default);

                    psi = new ProcessStartInfo(wrapperBat)
                    {
                        UseShellExecute = true,
                        WorkingDirectory = pythonDir,
                    };
                }
                else
                {
                    string args = "\"" + tmpScript + "\"";
                    if (!string.IsNullOrEmpty(extraArgs)) args += " " + extraArgs;
                    psi = new ProcessStartInfo(interpreterPath, args)
                    {
                        UseShellExecute = false,   // 환경변수 설정 위해 false 필수
                        WorkingDirectory = pythonDir,
                        CreateNoWindow = false,
                        RedirectStandardOutput = false,
                        RedirectStandardError = false,
                    };
                    psi.EnvironmentVariables["OJW_AUTO_EXIT_SEC"] = autoExitSec.ToString();
                }

                var proc = Process.Start(psi);
                if (proc == null)
                {
                    Ojw.printf(txtLogHistory, "[Capture] 프로세스 시작 실패\r\n");
                    return false;
                }
                Ojw.printf(txtLogHistory, "[Capture]   프로세스 시작 (pid={0}, detachConsole={1})\r\n", proc.Id, detachConsole);

                // 폴링: waitBeforeCaptureSec 동안 매 2초마다 윈도우 찾기 시도.
                // 발견되면 추가 안정화 (3초) 후 캡쳐 — 전체 wait 시간을 다 쓰지 않아 효율적.
                IntPtr hwnd = IntPtr.Zero;
                int elapsed = 0;
                int pollIntervalMs = 2000;
                while (elapsed < waitBeforeCaptureSec * 1000)
                {
                    System.Threading.Thread.Sleep(pollIntervalMs);
                    elapsed += pollIntervalMs;
                    // Application.DoEvents() 제거 — ex03+ STL paint hang 회피
                    if (proc.HasExited)
                    {
                        Ojw.printf(txtLogHistory, "[Capture]   프로세스 조기 종료 (exit={0})\r\n", proc.ExitCode);
                        break;
                    }
                    // detachConsole 일 때는 wrapper batch 의 pid 이므로 자식 windows 가 다른 pid → 전체 검색
                    // 폴링도 FindLargestWindowByTitlePart + blacklist 사용 → NVIDIA Overlay 등 무관 윈도우 처음부터 배제
                    string blackForPoll = "Overlay;GeForce Experience;NVIDIA App;Settings";
                    hwnd = detachConsole
                        ? FindLargestWindowByTitlePart(titlePart, 0, 400, 300, blackForPoll)
                        : FindWindowByTitlePart(titlePart, proc.Id);
                    if (hwnd == IntPtr.Zero)
                        hwnd = detachConsole
                            ? IntPtr.Zero   // 이미 전체 검색했음
                            : FindWindowByTitlePart(titlePart, 0);
                    if (hwnd != IntPtr.Zero)
                    {
                        Ojw.printf(txtLogHistory, "[Capture]   윈도우 발견 (t={0}s) — {1}ms 안정화\r\n",
                            elapsed / 1000, extraStabilizeMs);
                        // 안정화 대기
                        int extra = 0;
                        while (extra < extraStabilizeMs)
                        {
                            System.Threading.Thread.Sleep(500);
                            extra += 500;
                            // Application.DoEvents() 제거 — paint hang 회피
                            if (proc.HasExited) break;
                        }
                        break;
                    }
                }
                if (hwnd == IntPtr.Zero)
                {
                    try { proc.Refresh(); if (proc.MainWindowHandle != IntPtr.Zero) hwnd = proc.MainWindowHandle; }
                    catch { }
                }

                // 캡쳐 직전 fresh re-search: stabilize 동안 splash 사라지고 메인 GUI 떴을 수 있음.
                IntPtr hwndBig = FindLargestWindowByTitlePart(titlePart, 0, 600, 400,
                    "Overlay;GeForce Experience;NVIDIA App;Settings");
                if (hwndBig != IntPtr.Zero) hwnd = hwndBig;

                // detachConsole 의 경우 캡쳐 직전 윈도우를 maximize → 전체 화면 캡쳐
                //   (Isaac Sim 같은 multi-pane GUI 는 default 크기가 작아 viewport 가 짤림)
                if (detachConsole && hwnd != IntPtr.Zero)
                {
                    try
                    {
                        ShowWindow(hwnd, SW_MAXIMIZE);
                        SetForegroundWindow(hwnd);
                        // maximize 후 layout 재배치·재렌더링 대기
                        for (int s = 0; s < 6; s++)
                        {
                            System.Threading.Thread.Sleep(500);
                            // Application.DoEvents() 제거 — paint hang 회피
                        }
                    }
                    catch { }
                }

                bool capOk = false;
                if (hwnd != IntPtr.Zero)
                {
                    // captureFullScreen=true → 데스크탑 전체 캡쳐 (Isaac Sim 같이 dock panels 가 별도 top-level)
                    //                  false → 잡은 hwnd 의 윈도우 영역만 (PrintWindow)
                    //   ※ FullScreen 시 hwnd 를 넘겨 *해당 윈도우가 위치한 모니터만* 캡쳐.
                    //     듀얼/확장 모니터에서 전체 VirtualScreen 을 잡으면 다른 모니터 내용까지 섞여 들어옴.
                    capOk = captureFullScreen
                        ? CaptureScreenToFile(outPath, hwnd)
                        : CaptureHwndToFile(hwnd, outPath);
                }
                else
                {
                    Ojw.printf(txtLogHistory, "[Capture]   윈도우 못 찾음 (titlePart=\"{0}\")\r\n", titlePart);
                }

                // 프로세스 종료
                try
                {
                    if (!proc.HasExited)
                    {
                        // 약간 더 기다려서 graceful 종료 시도 (auto_exit 가 동작할 시간)
                        for (int s = 0; s < 3; s++)
                        {
                            System.Threading.Thread.Sleep(500);
                            // Application.DoEvents() 제거 — paint hang 회피
                            if (proc.HasExited) break;
                        }
                        if (!proc.HasExited)
                        {
                            if (detachConsole)
                            {
                                // wrapper batch 만 Kill 하면 자식 (python.bat → python.exe → omni.kit.exe) 살아남음
                                // taskkill /F /T /PID 로 프로세스 tree 전체 종료
                                try
                                {
                                    var killPsi = new ProcessStartInfo("taskkill", "/F /T /PID " + proc.Id)
                                    {
                                        UseShellExecute = false,
                                        CreateNoWindow = true,
                                        RedirectStandardOutput = true,
                                        RedirectStandardError = true,
                                    };
                                    using (var killProc = Process.Start(killPsi))
                                    {
                                        if (killProc != null) killProc.WaitForExit(5000);
                                    }
                                    Ojw.printf(txtLogHistory, "[Capture]   taskkill /T pid={0} 실행\r\n", proc.Id);
                                }
                                catch (Exception kex)
                                {
                                    Ojw.printf(txtLogHistory, "[Capture]   taskkill 실패: {0}\r\n", kex.Message);
                                }
                            }
                            else
                            {
                                proc.Kill();
                                proc.WaitForExit(3000);
                            }
                        }
                    }
                }
                catch { }

                return capOk;
            }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Capture] viewer 실행/캡쳐 오류: {0}\r\n", ex.Message);
                return false;
            }
        }

        /// <summary>
        /// 특정 윈도우의 실제 rect 영역만 화면에서 캡쳐해 PNG 로 저장.
        ///   Isaac Sim 같이 dock panels 가 native top-level 인 케이스도, maximize 후 메인 윈도우 rect
        ///   안에 모두 들어와 있으므로 그 영역만 잘라내면 충분.
        ///   PrintWindow 와 달리 *화면 캡쳐* 라 OpenGL/DirectX 합성 영역도 정상 확보.
        ///   hwnd 가 IntPtr.Zero 또는 GetWindowRect 실패 시 fallback 으로 PrimaryScreen 사용.
        /// </summary>
        private static bool CaptureScreenToFile(string filePath, IntPtr hwnd)
        {
            try
            {
                int x, y, w, h;
                RECT rc;
                if (hwnd != IntPtr.Zero && GetWindowRect(hwnd, out rc))
                {
                    x = rc.Left; y = rc.Top;
                    w = rc.Right - rc.Left;
                    h = rc.Bottom - rc.Top;
                }
                else
                {
                    var bnd = System.Windows.Forms.Screen.PrimaryScreen.Bounds;
                    x = bnd.Left; y = bnd.Top; w = bnd.Width; h = bnd.Height;
                }
                if (w <= 0 || h <= 0) return false;

                using (Bitmap bmp = new Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
                {
                    using (Graphics g = Graphics.FromImage(bmp))
                    {
                        g.CopyFromScreen(x, y, 0, 0, new Size(w, h));
                    }
                    bmp.Save(filePath, System.Drawing.Imaging.ImageFormat.Png);
                }
                return true;
            }
            catch { return false; }
        }

        /// <summary>
        /// 임의 윈도우 핸들의 클라이언트 영역을 포함한 전체 윈도우를 PNG 로 저장.
        /// PW_RENDERFULLCONTENT(0x2) 사용 → OpenGL/DirectX 합성 영역도 정상 캡쳐.
        /// </summary>
        private static bool CaptureHwndToFile(IntPtr hwnd, string filePath)
        {
            if (hwnd == IntPtr.Zero) return false;
            RECT rc;
            if (!GetWindowRect(hwnd, out rc)) return false;
            int w = rc.Right - rc.Left;
            int h = rc.Bottom - rc.Top;
            if (w <= 0 || h <= 0) return false;

            using (Bitmap bmp = new Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
            {
                using (Graphics g = Graphics.FromImage(bmp))
                {
                    IntPtr hdc = g.GetHdc();
                    try { PrintWindow(hwnd, hdc, 0x00000002); }  // PW_RENDERFULLCONTENT
                    finally { g.ReleaseHdc(hdc); }
                }
                bmp.Save(filePath, System.Drawing.Imaging.ImageFormat.Png);
            }
            return true;
        }

        // ========================================
        // 예제 인덱스 → DH 텍스트 (Capture All 핸들러와 공유)
        // ========================================
        private string GetExampleDhText(int idx)
        {
            switch (idx)
            {
                case 1: return m_strExample1;
                case 2: return m_strExample2;
                case 3: return m_strExample3;
                case 4: return m_strExample4;
                case 5: return m_strExample5;
                case 6: return m_strExample6;
                case 7: return m_strExample7;
                case 8: return m_strExample8;
                case 9: return m_strExample9;
                case 10: return m_strExample10;
                case 11: return m_strExample11;
                case 12: return m_strExample12;
                case 13: return m_strExample13;
                case 14: return m_strExample14;
                case 15: return m_strExample15;
                case 16: return m_strExample16;
            }
            return "";
        }

        // ========================================
        // 예제 로드
        // ========================================
        private void cmbExample_SelectedIndexChanged(object sender, EventArgs e)
        {
            int idx = cmbExample.SelectedIndex;
            if (idx <= 0) return; // "예제 선택..." 항목

            // 예제 번호 = 항목 텍스트의 "N:" 접두 (리스트 표시 순서와 번호 분리 —
            //   14번(기본형)을 5번(+카메라) 앞에 두는 등 재정렬 가능). 접두 없으면 인덱스.
            string name = cmbExample.Items[idx].ToString();
            int nExampleNum = idx;
            int nColon = name.IndexOf(':');
            if (nColon > 0)
            {
                int nParsed;
                if (int.TryParse(name.Substring(0, nColon).Trim(), out nParsed)) nExampleNum = nParsed;
            }

            string dhText = GetExampleDhText(nExampleNum);
            if (string.IsNullOrEmpty(dhText)) return;

            // 빌더에 임포트 → 히스토리/텍스트/3D 동기화
            m_Builder.ImportFromText(dhText);
            RefreshHistory();
            UpdatePreview(null);
            ClearDhEditSelection();
            if (tabRight.SelectedTab == tabTest) UpdateMotorList();
            lblStatus.Text = name + " loaded";
            m_nLastExampleIdx = nExampleNum;   // Capture All / ExportSource 가 사용 (예제 번호)
            m_strLastExampleName = name;
            //cmbExample.SelectedIndex = 0;
        }

        // ========================================
        // Capture All — 현재 로드된 예제 하나에 대해 4 viewer 모두 캡쳐
        //   사용 흐름:
        //     1) 사용자가 cmbExample 에서 예제 로드 (또는 직접 DH 텍스트 편집)
        //     2) 카메라 시점 / 줌을 적절히 맞춤
        //     3) Capture All 클릭
        //     4) 현재 상태 그대로 MakeUrdf 폼 전체 캡쳐 + 4 viewer 자동 실행 / 창 캡쳐
        //   출력: <exeDir>/captures/<example_name_or_timestamp>/<viewer>.png
        //   현재 단계: Step A — MakeUrdf 폼 전체만. PyBullet/MuJoCo/Isaac 은 Step B~D 에서.
        // ========================================
        private void btnCaptureAll_Click(object sender, EventArgs e)
        {
            string releaseDir = AppDomain.CurrentDomain.BaseDirectory;
            string captureRoot = Path.Combine(releaseDir, "captures");
            try { Directory.CreateDirectory(captureRoot); }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Capture] 디렉토리 생성 실패: {0}\r\n", ex.Message);
                return;
            }

            // 폴더명: 마지막 cmbExample 선택 인덱스 있으면 ex<NN>_<name>, 없으면 timestamp
            string exName;
            if (m_nLastExampleIdx > 0 && !string.IsNullOrEmpty(m_strLastExampleName))
            {
                string label = System.Text.RegularExpressions.Regex.Replace(m_strLastExampleName, "[^a-zA-Z0-9가-힣]+", "_").Trim('_');
                exName = string.Format("ex{0:D2}_{1}", m_nLastExampleIdx, label);
            }
            else
            {
                exName = "current_" + DateTime.Now.ToString("yyyyMMdd_HHmmss");
            }
            string exDir = Path.Combine(captureRoot, exName);
            try { Directory.CreateDirectory(exDir); }
            catch (Exception ex)
            {
                Ojw.printf(txtLogHistory, "[Capture] 폴더 생성 실패 ({0}): {1}\r\n", exDir, ex.Message);
                return;
            }

            btnCaptureAll.Enabled = false;
            try { txtLogHistory.MaxLength = int.MaxValue; } catch { }
            // 진단용 디스크 로그 — printf 가 silent fail 해도 디스크엔 남음.
            //   ex03 의 STL 메시 paint hang 추적용. 정상 동작 검증 후 제거 가능.
            string dbgLog = Path.Combine(Path.GetTempPath(), "ojw_capture_dbg.log");
            Action<string> dlog = (msg) =>
            {
                try { File.AppendAllText(dbgLog, DateTime.Now.ToString("HH:mm:ss.fff ") + msg + "\r\n"); }
                catch { }
            };
            dlog("ENTRY exDir=" + exDir);

            Ojw.printf(txtLogHistory, "[Capture] 시작 — 출력: {0}\r\n", exDir);
            lblStatus.Text = "Capturing: " + exName;
            // tabRight.SelectedTab = tabHistory      ← 제거: tab change event 가 paint 트리거 가능
            // Application.DoEvents()                 ← 제거: paint event → m_C3d.OjwDraw() → STL ex03 hang
            dlog("after first lblStatus");

            int ok = 0, total = 0;

            // ──────────────────────────────────────────────────────────────
            // 1) MakeUrdf 폼 전체 캡쳐 (현재 상태 그대로 — DH/카메라 건드리지 않음)
            // ──────────────────────────────────────────────────────────────
            total++;
            try
            {
                dlog("step1 draw begin");
                lblStatus.Text = "Capturing: " + exName + " (1/5 draw)";
                System.Threading.Thread.Sleep(500);   // DoEvents 안 함 — paint hang 회피
                dlog("step1 draw end");

                dlog("step2 form capture begin");
                lblStatus.Text = "Capturing: " + exName + " (2/5 form capture)";
                string makeurdfPath = Path.Combine(exDir, "makeurdf.png");
                bool capR = CaptureHwndToFile(this.Handle, makeurdfPath);
                dlog("step2 form capture end (ok=" + capR + ")");
                if (capR)
                {
                    Ojw.printf(txtLogHistory, "[Capture] MakeUrdf → makeurdf.png OK\r\n");
                    ok++;
                }
                else
                {
                    Ojw.printf(txtLogHistory, "[Capture] MakeUrdf PrintWindow 실패\r\n");
                }
            }
            catch (Exception ex)
            {
                dlog("step1/2 EXCEPTION: " + ex.Message);
                Ojw.printf(txtLogHistory, "[Capture] MakeUrdf 실패: {0}\r\n", ex.Message);
            }

            // ──────────────────────────────────────────────────────────────
            // 2) PyBullet 창 전체 캡쳐
            // ──────────────────────────────────────────────────────────────
            dlog("step3 PyBullet begin");
            total++;
            if (!CheckPythonPackage("pybullet"))
            {
                dlog("step3 pybullet not installed");
                Ojw.printf(txtLogHistory, "[Capture] PyBullet: pybullet 패키지 미설치 — skip\r\n");
            }
            else
            {
                dlog("step3 ExportUrdfFiles begin");
                bool expOk = ExportUrdfFiles();
                dlog("step3 ExportUrdfFiles end (ok=" + expOk + ")");
                if (!expOk)
                {
                    Ojw.printf(txtLogHistory, "[Capture] PyBullet: ExportUrdfFiles 실패 — skip\r\n");
                }
                else
                {
                    SavePythonConfig();
                    lblStatus.Text = "Capturing: PyBullet...";
                    dlog("step3 PyBullet CaptureViewerWindow begin");
                        string pybulletPath = Path.Combine(exDir, "pybullet.png");
                    // wait=10s, autoExit=25s, stabilize=5000ms (viewer 죽기 전 캡쳐 완료 보장)
                    bool pbOk = CaptureViewerWindow("urdf_viewer_with_sock.py", pybulletPath, "Bullet", 10, 25, "python", 5000);
                    dlog("step3 PyBullet end (ok=" + pbOk + ")");
                    if (pbOk)
                    {
                        Ojw.printf(txtLogHistory, "[Capture] PyBullet → pybullet.png OK\r\n");
                        ok++;
                    }
                    else
                    {
                        Ojw.printf(txtLogHistory, "[Capture] PyBullet 캡쳐 실패\r\n");
                    }
                }
            }

            // ──────────────────────────────────────────────────────────────
            // 3) MuJoCo 창 전체 캡쳐
            // ──────────────────────────────────────────────────────────────
            dlog("step4 MuJoCo begin");
            total++;
            if (!CheckPythonPackage("mujoco"))
            {
                Ojw.printf(txtLogHistory, "[Capture] MuJoCo: mujoco 패키지 미설치 — skip\r\n");
            }
            else
            {
                SavePythonConfig();   // SPAWN_Z / FIXED_BASE 반영
                lblStatus.Text = "Capturing: MuJoCo...";
                string mujocoPath = Path.Combine(exDir, "mujoco.png");
                if (CaptureViewerWindow("urdf_viewer_mujoco.py", mujocoPath, "MuJoCo", 8, 12))
                {
                    Ojw.printf(txtLogHistory, "[Capture] MuJoCo → mujoco.png OK\r\n");
                    ok++;
                }
                else
                {
                    Ojw.printf(txtLogHistory, "[Capture] MuJoCo 캡쳐 실패\r\n");
                }
            }

            // ──────────────────────────────────────────────────────────────
            // 4) Isaac Sim 창 전체 캡쳐 — txtIsaacPath 의 python.bat 사용
            //    Isaac Sim 시작 30~60초 소요 → 대기 시간 대폭 증가
            // ──────────────────────────────────────────────────────────────
            total++;
            string isaacPython = txtIsaacPath.Text.Trim();
            if (string.IsNullOrEmpty(isaacPython) || !File.Exists(isaacPython))
            {
                Ojw.printf(txtLogHistory, "[Capture] Isaac Sim: python.bat 경로 없음 ({0}) — skip\r\n", isaacPython);
            }
            else
            {
                dlog("step5 Isaac begin");
                SavePythonConfig();   // SPAWN_Z / FIXED_BASE 반영
                lblStatus.Text = "Capturing: Isaac Sim (시작 ~1분 + 안정화 20s)...";
                string isaacPath = Path.Combine(exDir, "isaac.png");
                // isaac_runner.py 는 URDF 경로를 positional arg 로 요구.
                string isaacReleaseDir = GetUrdfOutputDir();
                string isaacUrdf = Path.Combine(isaacReleaseDir, "robot_stl_isaac.urdf");
                if (!File.Exists(isaacUrdf))
                    isaacUrdf = Path.Combine(isaacReleaseDir, "robot_stl.urdf");
                string isaacExtraArgs = "\"" + isaacUrdf + "\"";

                // wait=180s 시작 대기, stabilize=40s, autoExit=0, captureFullScreen=true (데스크탑 전체)
                if (CaptureViewerWindow("isaac_runner.py", isaacPath, "Isaac;Omniverse;Kit", 180, 0, isaacPython, 40000, detachConsole: true, extraArgs: isaacExtraArgs, captureFullScreen: true))
                {
                    Ojw.printf(txtLogHistory, "[Capture] Isaac Sim → isaac.png OK\r\n");
                    ok++;
                }
                else
                {
                    Ojw.printf(txtLogHistory, "[Capture] Isaac Sim 캡쳐 실패\r\n");
                }
            }

            Ojw.printf(txtLogHistory, "[Capture] 완료: {0}/{1} viewer 캡쳐됨\r\n", ok, total);
            lblStatus.Text = string.Format("Capture done: {0}/{1} → {2}", ok, total, exName);
            btnCaptureAll.Enabled = true;

            // 끝나면 출력 폴더를 Explorer 로 열어 사용자가 즉시 확인
            try { Process.Start("explorer.exe", "\"" + exDir + "\""); } catch { }
        }

        // ========================================
        // Python 뷰어 공통: 스크립트 찾기 및 실행
        // ========================================

        /// <summary>
        /// python 폴더 탐색: bin/python, bin/Debug/python 등 여러 후보 경로를 확인.
        /// </summary>
        private string FindPythonDir()
        {
            string[] candidates = new string[]
            {
                Path.Combine(Application.StartupPath, "python"),
                Path.Combine(Application.StartupPath, "..", "python"),
            };
            foreach (var dir in candidates)
            {
                string full = Path.GetFullPath(dir);
                if (Directory.Exists(full))
                    return full;
            }
            return Path.Combine(Application.StartupPath, "python");
        }

        /// <summary>
        /// Kinematics python 뷰어 스크립트를 읽어서 release_dir 경로를 패치 후 실행.
        /// 원본 스크립트의 release_dir = os.path.join(script_dir, "..", "Release") 를
        /// 현재 실행 경로(URDF/STL이 있는 곳)로 교체한다.
        /// </summary>
        private bool RunPythonViewer(string scriptFilename)
        {
            string pythonDir = FindPythonDir();
            string scriptPath = Path.Combine(pythonDir, scriptFilename);

            Ojw.printf(txtLogHistory, "[Python] 스크립트 경로: {0}\r\n", scriptPath);

            if (!File.Exists(scriptPath))
            {
                Ojw.printf(txtLogHistory, "[Python] 오류: {0} 파일을 찾을 수 없습니다.\r\n", scriptFilename);
                Ojw.printf(txtLogHistory, "[Python] Kinematics/bin/python/ 폴더의 파일을 MakeUrdf/bin/python/ 에 복사해 주세요.\r\n");
                return false;
            }

            string code = File.ReadAllText(scriptPath, System.Text.Encoding.UTF8);

            // release_dir를 URDF 출력 폴더로 패치 (URDF, MJCF, STL 파일 위치)
            string releaseDir = GetUrdfOutputDir().Replace("\\", "/");
            code = code.Replace(
                "release_dir = os.path.join(script_dir, \"..\", \"Release\")",
                "release_dir = r\"" + releaseDir + "\"");

            // USE_FIXED_BASE를 직접 패치 (config 파일 의존 제거)
            string fixedBaseStr = chkFixedBase.Checked ? "True" : "False";
            code = code.Replace(
                "USE_FIXED_BASE = viewer_config['FIXED_BASE']",
                "USE_FIXED_BASE = " + fixedBaseStr);

            m_CPython.SetTextBox(txtLogHistory);
            m_CPython.SetDebugMode(false);
            m_CPython.Run(code);

            // 로그 탭으로 자동 전환
            tabRight.SelectedTab = tabHistory;

            return true;
        }

        // ========================================
        // 좌표고정 설정 저장 (Python 뷰어용)
        // ========================================
        private void SavePythonConfig()
        {
            try
            {
                // Python 뷰어의 release_dir 위치와 동일한 경로에 저장해야 읽힘
                string configPath = Path.Combine(GetUrdfOutputDir(), "viewer_config.txt");
                // SPAWN_Z: free-floating / fixed 모두 동일하게 적용되는 로봇 base 의 초기 z (m)
                string spawnZ = txtSpawnHeight.Text.Trim();
                if (string.IsNullOrEmpty(spawnZ)) spawnZ = "0.4";
                File.WriteAllText(configPath,
                    "# Robot Viewer Configuration\r\n" +
                    "FIXED_BASE=" + (chkFixedBase.Checked ? "1" : "0") + "\r\n" +
                    "SPAWN_Z=" + spawnZ + "\r\n",
                    Encoding.UTF8);
            }
            catch { }
        }

