        /// <summary>
        /// python -c "import packageName" 실행하여 패키지 설치 여부 확인
        /// </summary>
        private static bool CheckPythonPackage(string packageName)
        {
            try
            {
                var psi = new ProcessStartInfo("python",
                    "-c \"import " + packageName + "\"")
                {
                    RedirectStandardOutput = true,
                    RedirectStandardError = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                };
                using (var proc = Process.Start(psi))
                {
                    proc.WaitForExit(5000);
                    return proc.ExitCode == 0;
                }
            }
            catch
            {
                return false;
            }
        }

        /// <summary>
        /// 패키지 미설치 시 팝업 후 OK 선택 시 pip install 실행
        /// </summary>
        private void PromptInstallPackage(string packageName, string displayName)
        {
#if true
            MessageBox.Show("");
#else
            var result = MessageBox.Show(
                displayName + " is not installed.\n\n" +
                "Install now?\n" +
                "(python -m pip install " + packageName + ")",
                displayName + " Not Installed",
                MessageBoxButtons.OKCancel,
                MessageBoxIcon.Warning);

            if (result != DialogResult.OK) return;

            // 버튼 비활성화
            btnPyBullet.Enabled = false;
            btnMuJoCo.Enabled   = false;
            Ojw.printf(txtLogHistory, "[설치] python -m pip install " + packageName + " 시작...\r\n");

            // 프로그레스 다이얼로그 (코드로 생성, Marquee 스타일)
            var dlg = new Form();
            dlg.Text             = displayName + " installing...";
            dlg.Size             = new System.Drawing.Size(420, 120);
            dlg.FormBorderStyle  = FormBorderStyle.FixedDialog;
            dlg.MaximizeBox      = false;
            dlg.MinimizeBox      = false;
            dlg.ControlBox       = false;
            dlg.StartPosition    = FormStartPosition.CenterParent;

            var lbl = new Label();
            lbl.Text      = "Running python -m pip install " + packageName + "... (do not close the console)";
            lbl.AutoSize  = true;
            lbl.Location  = new System.Drawing.Point(12, 12);

            var pb = new ProgressBar();
            pb.Style                 = ProgressBarStyle.Marquee;
            pb.MarqueeAnimationSpeed = 25;
            pb.Location              = new System.Drawing.Point(12, 40);
            pb.Size                  = new System.Drawing.Size(380, 22);

            dlg.Controls.Add(lbl);
            dlg.Controls.Add(pb);

            // pip.exe 직접 호출은 조직 Device Guard 정책 등으로 차단될 수 있음
            // python -m pip 형태로 호출하여 현재 인터프리터의 pip 모듈 사용
            var psi = new ProcessStartInfo("python", "-m pip install " + packageName)
            {
                UseShellExecute = true,   // 도스창 표시
                CreateNoWindow  = false
            };

            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                try
                {
                    using (var proc = Process.Start(psi))
                    {
                        proc.WaitForExit();
                        int exitCode = proc.ExitCode;

                        this.Invoke((System.Windows.Forms.MethodInvoker)delegate
                        {
                            dlg.Close();
                            btnPyBullet.Enabled = true;
                            btnMuJoCo.Enabled   = true;

                            if (exitCode == 0)
                            {
                                Ojw.printf(txtLogHistory, "[설치] " + displayName + " 설치 완료!\r\n");
                                MessageBox.Show(
                                    displayName + " installation complete.\nPress the button again to run.",
                                    "Install Complete",
                                    MessageBoxButtons.OK,
                                    MessageBoxIcon.Information);
                            }
                            else
                            {
                                Ojw.printf(txtLogHistory, "[설치] " + displayName + " 설치 실패 (code=" + exitCode + ")\r\n");
                                MessageBox.Show(
                                    displayName + " installation failed.\nCheck the console output.\n\n" +
                                    "If blocked by organization security policy (Device Guard),\n" +
                                    "open a terminal and run manually:\n" +
                                    "   python -m pip install " + packageName,
                                    "Install Failed",
                                    MessageBoxButtons.OK,
                                    MessageBoxIcon.Error);
                            }
                        });
                    }
                }
                catch (Exception ex)
                {
                    this.Invoke((System.Windows.Forms.MethodInvoker)delegate
                    {
                        dlg.Close();
                        btnPyBullet.Enabled = true;
                        btnMuJoCo.Enabled   = true;
                        MessageBox.Show(
                            "Error during installation:\n" + ex.Message,
                            "Error",
                            MessageBoxButtons.OK,
                            MessageBoxIcon.Error);
                    });
                }
            });

            // 백그라운드 스레드 시작 후 다이얼로그 표시 (닫힐 때까지 블로킹)
            dlg.ShowDialog(this);
#endif
        }

