        /// <summary>러너 로그 파일 경로 확보 — 잠겨 있으면 대체 이름으로 우회.
        /// 이전 Isaac 실행이 낳은 좀비(예: Omniverse hub.exe 가 리다이렉트 핸들을 상속한 채 상주)가
        /// isaac_runner.log 를 잠그면 cmd 리다이렉트가 즉시 실패해 "Isaac 창이 안 뜨는" 증상이 된다
        /// (2026-08-15 실사고). 배타 열기로 검사해 잠긴 파일은 건너뛴다.</summary>
        private string GetWritableRunnerLogPath(string urdfDir)
        {
            for (int i = 0; i < 10; i++)
            {
                string p = Path.Combine(urdfDir, (i == 0) ? "isaac_runner.log" : string.Format("isaac_runner_{0}.log", i + 1));
                try
                {
                    using (var fs = new FileStream(p, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None)) { }
                    return p;
                }
                catch (IOException)
                {
                    Ojw.printf(txtLogHistory, "[Isaac] 로그 잠김(좀비 프로세스 추정) — 다음 이름 시도: {0}\r\n", Path.GetFileName(p));
                }
            }
            return Path.Combine(urdfDir, string.Format("isaac_runner_{0:HHmmss}.log", DateTime.Now));
        }

        // ========================================
        // Isaac Sim 실행 — txtIsaacPath 의 python.bat 으로 isaac_runner.py 외부 프로세스 시작
        //   MuJoCo/PyBullet 과 달리 임베디드 Python 으로는 동작 불가 (omni.* 모듈 의존)
        //   매 호출마다 새 Isaac Sim 창이 뜸 — 시작 30~60초 소요
        // ========================================
        private void btnIsaac_Click(object sender, EventArgs e)
        {
            string pythonBat = txtIsaacPath.Text.Trim();
            if (string.IsNullOrEmpty(pythonBat))
            {
                MessageBox.Show("Isaac Sim 의 python.bat 경로를 입력해 주세요.");
                return;
            }
            if (!File.Exists(pythonBat))
            {
                MessageBox.Show("python.bat 을 찾을 수 없습니다: " + pythonBat);
                return;
            }

            // URDF Export 자동
            if (!ExportUrdfFiles()) return;

            string releaseDir = GetUrdfOutputDir();
            // Isaac 전용 후처리 URDF 우선, 없으면 표준 robot_stl.urdf
            string urdfPath = Path.Combine(releaseDir, "robot_stl_isaac.urdf");
            if (!File.Exists(urdfPath))
                urdfPath = Path.Combine(releaseDir, "robot_stl.urdf");
            if (!File.Exists(urdfPath))
            {
                MessageBox.Show("URDF 파일이 없습니다: " + urdfPath);
                return;
            }

            // 스크립트 자동 복사: bin/python/isaac_runner.py → releaseDir/isaac_runner.py
            string pythonDir = FindPythonDir();
            string scriptSrc = Path.Combine(pythonDir, "isaac_runner.py");
            if (!File.Exists(scriptSrc))
            {
                MessageBox.Show("isaac_runner.py 가 없습니다: " + scriptSrc);
                return;
            }
            string scriptDst = Path.Combine(releaseDir, "isaac_runner.py");
            try
            {
                File.Copy(scriptSrc, scriptDst, true);
            }
            catch (Exception ex)
            {
                MessageBox.Show("스크립트 복사 실패: " + ex.Message);
                return;
            }

            // python.bat <스크립트> <urdf 경로> 외부 프로세스 실행
            Ojw.printf(txtLogHistory, "[Isaac] python.bat: {0}\r\n", pythonBat);
            Ojw.printf(txtLogHistory, "[Isaac] script:    {0}\r\n", scriptDst);
            Ojw.printf(txtLogHistory, "[Isaac] urdf:      {0}\r\n", urdfPath);
            Ojw.printf(txtLogHistory, "[Isaac] 새 Isaac Sim 창 시작 — 로드까지 30~60초 소요\r\n");

            try
            {
                // viewer_config.txt 도 최신화 — 러너는 OJW_SPAWN_Z env 를 우선 쓰지만,
                // 파일이 낡은 값으로 남으면 다음 진단 때 혼란 (UI 0 인데 파일 0.4 사건)
                SavePythonConfig();
                // 콘솔 출력을 파일로 리다이렉트 (DOS 창이 즉시 닫혀도 로그 보존)
                // cmd /c "python.bat ... > isaac_runner.log 2>&1" 형태로 실행.
                string logPath = GetWritableRunnerLogPath(Path.GetDirectoryName(urdfPath));
                string cmdArgs = string.Format(
                    "/c \"\"{0}\" \"{1}\" \"{2}\" > \"{3}\" 2>&1\"",
                    pythonBat, scriptDst, urdfPath, logPath);

                var psi = new ProcessStartInfo("cmd.exe", cmdArgs);
                psi.UseShellExecute = false;   // env var 전달 위해 false
                psi.WorkingDirectory = releaseDir;
                // Fixed Base 체크박스 → isaac_runner 의 import_config.fix_base 로 전달
                psi.EnvironmentVariables["OJW_FIXED_BASE"] = chkFixedBase.Checked ? "1" : "0";
                // SPAWN_Z 도 전달 (필요 시 활용 가능)
                psi.EnvironmentVariables["OJW_SPAWN_Z"] =
                    string.IsNullOrEmpty(txtSpawnHeight.Text.Trim()) ? "0.4" : txtSpawnHeight.Text.Trim();
                // 자동학습된 actuator-net 이 있으면 자동 주입 — 시뮬 관절이 실기 응답으로 움직임
                string strActNetNpz = Path.Combine(GetUrdfOutputDir(), "actnet_v1.npz");
                if (File.Exists(strActNetNpz))
                {
                    psi.EnvironmentVariables["OJW_ACTNET"] = strActNetNpz;
                    Ojw.printf(txtLogHistory, "[Isaac] OJW_ACTNET={0} (자동학습 적용)\r\n", strActNetNpz);
                }
                Ojw.printf(txtLogHistory, "[Isaac] OJW_FIXED_BASE={0} OJW_SPAWN_Z={1}\r\n",
                    psi.EnvironmentVariables["OJW_FIXED_BASE"], psi.EnvironmentVariables["OJW_SPAWN_Z"]);
                Ojw.printf(txtLogHistory, "[Isaac] 출력 로그: {0}\r\n", logPath);
                Process.Start(psi);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Isaac Sim 실행 실패: " + ex.Message);
            }
        }

        // ========================================
        // View control (7 버튼 + 6 텍스트박스) — 카메라 위치/회전 프리셋 + 수동 편집
        // ========================================
        // "Default" 버튼용: 버튼 눌리기 직전 상태 스냅샷
        private float m_fViewDefault_X, m_fViewDefault_Y, m_fViewDefault_Z;
        private float m_fViewDefault_Pan, m_fViewDefault_Tilt, m_fViewDefault_Swing;
        private bool m_bViewDefaultSaved = false;
        private bool m_bViewSyncing = false; // tmr → 텍스트박스 업데이트 중 재진입 방지

        private void SaveViewDefault()
        {
            if (m_C3d == null) return;
            m_C3d.GetPos_Display(out m_fViewDefault_X, out m_fViewDefault_Y, out m_fViewDefault_Z);
            m_C3d.GetAngle_Display(out m_fViewDefault_Pan, out m_fViewDefault_Tilt, out m_fViewDefault_Swing);
            m_bViewDefaultSaved = true;
        }

        /// <summary>프리셋 뷰 적용. pan/tilt/swing 만 변경하고 pos 는 현재 유지.</summary>
        private void ApplyViewPreset(float pan, float tilt, float swing)
        {
            if (m_C3d == null) return;
            if (!m_bViewDefaultSaved) SaveViewDefault();
            m_C3d.SetAngle_Display(pan, tilt, swing);
            UpdateViewTextboxes();
            m_C3d.OjwDraw();
        }

        private void btnView1_Click(object sender, EventArgs e) { ApplyViewPreset(0,     0,    0); }  // 정면 (Front)
        private void btnView2_Click(object sender, EventArgs e) { ApplyViewPreset(180,   0,    0); }  // 뒷면 (Back, Pan 180)
        private void btnView3_Click(object sender, EventArgs e) { ApplyViewPreset(90,    0,    0); }  // 우측 (Right, Pan +90)
        private void btnView4_Click(object sender, EventArgs e) { ApplyViewPreset(-90,   0,    0); }  // 좌측 (Left,  Pan -90)
        private void btnView5_Click(object sender, EventArgs e) { ApplyViewPreset(0,    90,    0); }  // 윗면 (Top,   Tilt +90)
        private void btnView6_Click(object sender, EventArgs e) { ApplyViewPreset(0,   -90,    0); }  // 아랫면 (Bottom, Tilt -90)
        private void btnView7_Click(object sender, EventArgs e) { ApplyViewPreset(0,     0,   90); }  // 우측(Swing) — Swing +90
        private void btnView8_Click(object sender, EventArgs e) { ApplyViewPreset(0,     0,  -90); }  // 좌측(Swing) — Swing -90

        private void btnViewDefault_Click(object sender, EventArgs e)
        {
            if (m_C3d == null || !m_bViewDefaultSaved) return;
            m_C3d.SetPos_Display(m_fViewDefault_X, m_fViewDefault_Y, m_fViewDefault_Z);
            m_C3d.SetAngle_Display(m_fViewDefault_Pan, m_fViewDefault_Tilt, m_fViewDefault_Swing);
            UpdateViewTextboxes();
            m_C3d.OjwDraw();
        }

        /// <summary>텍스트박스 값으로 C3d 의 Pos 업데이트</summary>
        private void txtViewTrans_Leave(object sender, EventArgs e)
        {
            if (m_C3d == null || m_bViewSyncing) return;
            float fx, fy, fz;
            m_C3d.GetPos_Display(out fx, out fy, out fz);
            fx = Ojw.CConvert.StrToFloat(txtViewTX.Text);
            fy = Ojw.CConvert.StrToFloat(txtViewTY.Text);
            fz = Ojw.CConvert.StrToFloat(txtViewTZ.Text);
            m_C3d.SetPos_Display(fx, fy, fz);
            m_C3d.OjwDraw();
        }

        /// <summary>텍스트박스 값으로 C3d 의 Angle 업데이트</summary>
        private void txtViewRot_Leave(object sender, EventArgs e)
        {
            if (m_C3d == null || m_bViewSyncing) return;
            float p, t, s;
            m_C3d.GetAngle_Display(out p, out t, out s);
            p = Ojw.CConvert.StrToFloat(txtViewRX.Text);
            t = Ojw.CConvert.StrToFloat(txtViewRY.Text);
            s = Ojw.CConvert.StrToFloat(txtViewRZ.Text);
            m_C3d.SetAngle_Display(p, t, s);
            m_C3d.OjwDraw();
        }

        /// <summary>Enter 키로 포커스 이동 (Leave 이벤트 발동)</summary>
        private void txtViewAny_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                this.ActiveControl = null;  // 포커스 해제 → Leave 발생
            }
        }

        /// <summary>C3d 상태 → 텍스트박스 반영 (마우스 드래그 후 싱크용)</summary>
        private void UpdateViewTextboxes()
        {
            if (m_C3d == null) return;
            m_bViewSyncing = true;
            try
            {
                float fx, fy, fz, p, t, s;
                m_C3d.GetPos_Display(out fx, out fy, out fz);
                m_C3d.GetAngle_Display(out p, out t, out s);
                txtViewTX.Text = fx.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
                txtViewTY.Text = fy.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
                txtViewTZ.Text = fz.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
                txtViewRX.Text = p.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
                txtViewRY.Text = t.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
                txtViewRZ.Text = s.ToString("F2", System.Globalization.CultureInfo.InvariantCulture);
            }
            catch { }
            m_bViewSyncing = false;
        }

        /// <summary>주기적으로 C3d 상태를 텍스트박스에 싱크 (마우스 드래그 후 자동 반영)</summary>
        private void tmrViewSync_Tick(object sender, EventArgs e)
        {
            if (m_C3d == null) return;
            // 포커스된 텍스트박스는 건드리지 않음 (사용자 편집 중)
            Control focused = this.ActiveControl;
            if (focused == txtViewTX || focused == txtViewTY || focused == txtViewTZ ||
                focused == txtViewRX || focused == txtViewRY || focused == txtViewRZ) return;
            UpdateViewTextboxes();
        }

        // ========================================
        // 3D → Simulator 전송 (Python 뷰어 소켓으로 현재 관절 각도 전송)
        //   포맷: "time_ms,delay_ms,joint1,angle1,joint2,angle2,...;"
        //   예: "500,0,11,45.0,12,-30.0;"
        // ========================================
        private void btnSendToSim_Click(object sender, EventArgs e)
        {
            // 수동 전송 — 0.5초 보간, 로그 출력 + 실패 시 사용자에게 알림.
            SendCurrentJointsToSim(500, true, true);
        }

        // Auto-sync 체크박스 토글: 켜면 타이머 시작 + 수동 버튼 비활성화.
        private void chkAutoSync_CheckedChanged(object sender, EventArgs e)
        {
            bool bAuto = chkAutoSync.Checked;
            tmrAutoSync.Enabled = bAuto;
            btnSendToSim.Enabled = !bAuto;
            if (bAuto)
                lblStatus.Text = "Auto-sync ON (100ms)";
            else
                lblStatus.Text = "Auto-sync OFF";
        }

        // 100ms 주기 자동 전송 — 로그/대화상자 없이 silent 모드.
        //   보간시간을 짧게(100ms) 두어 다음 tick 까지 매끄럽게 도달.
        private bool m_bTmrAutoSync = false;
        private void tmrAutoSync_Tick(object sender, EventArgs e)
        {
            if (m_bTmrAutoSync == true) return;
            m_bTmrAutoSync = true;
            SendCurrentJointsToSim(100, false, false);
            
            m_bTmrAutoSync = false;
        }

        // 공통 전송 헬퍼.
        //   timeMs    : 시뮬레이터의 보간 시간 (ms)
        //   bLog      : true 면 txtLogHistory + lblStatus 갱신
        //   bShowError: true 면 연결 실패 시 MessageBox (수동 전송용)
        private void SendCurrentJointsToSim(int timeMs, bool bLog, bool bShowError)
        {
            try
            {
                string dhString = m_Builder.GenerateFullDh();
                if (string.IsNullOrWhiteSpace(dhString))
                {
                    if (bLog) lblStatus.Text = "Build a robot first";
                    return;
                }

                List<int> motorIds = ExtractMotorIds(dhString);
                if (motorIds.Count == 0)
                {
                    if (bLog) lblStatus.Text = "No motors defined";
                    return;
                }

                int nDelayMs = 0;
                var sb = new StringBuilder();
                sb.Append(timeMs).Append(',').Append(nDelayMs);
                foreach (int id in motorIds)
                {
                    float angle = m_C3d.GetData(id);
                    sb.Append(',').Append(id).Append(',').Append(angle.ToString("F2", System.Globalization.CultureInfo.InvariantCulture));
                }
                sb.Append(';');
                string payload = sb.ToString();

                var client = new Ojw.CSocket();
                if (!client.Connect("127.0.0.1", 4000))
                {
                    if (bShowError)
                    {
                        MessageBox.Show(
                            "Cannot connect to simulator on 127.0.0.1:4000.\n" +
                            "Start MuJoCo or PyBullet first.",
                            "Send Failed", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                    }
                    else if (bLog)
                    {
                        lblStatus.Text = "Auto-sync: connect failed";
                    }
                    return;
                }

                byte[] data = System.Text.Encoding.UTF8.GetBytes(payload);
                bool ok = client.Send(data);
                client.DisConnect();

                if (ok)
                {
                    if (bLog)
                    {
                        Ojw.printf(txtLogHistory, "[Sim] Sent: {0}\r\n", payload);
                        lblStatus.Text = string.Format("Sent {0} joints to simulator", motorIds.Count);
                    }
                }
                else
                {
                    if (bLog) lblStatus.Text = "Send failed";
                }
            }
            catch (Exception ex)
            {
                if (bLog)
                {
                    Ojw.printf(txtLogHistory, "[Sim] Error: {0}\r\n", ex.Message);
                    lblStatus.Text = "Send error: " + ex.Message;
                }
            }
        }

        // ========================================
        // 수식보기 (FK Formula Viewer)
        // ========================================
        private void btnFormulaView_Click(object sender, EventArgs e)
        {
            string dhText = txtDhParams.Text;
            if (string.IsNullOrWhiteSpace(dhText))
            {
                MessageBox.Show("Enter DH parameters first!", "Info",
                    MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }

            try
            {
                // DH 텍스트를 Init=1 기준으로 그룹 분리
                List<DhGroup> groups = SplitDhByInit(dhText);

                // 각 그룹별 수식 생성
                foreach (DhGroup grp in groups)
                {
                    try
                    {
                        grp.XyzFormulas = Ojw.CKinematics.CForward.Make_XYZString_By_Forward(grp.DhText);
                        CDhParamAll dhParamAll;
                        Ojw.CKinematics.CForward.MakeDhParam(grp.DhText, out dhParamAll);
                        double[] adMot = new double[256];
                        string strMatrixChain;
                        Ojw.CKinematics.CForward.CalcKinematics_ToString(dhParamAll, adMot, out strMatrixChain);
                        grp.MatrixChain = strMatrixChain;
                    }
                    catch { }
                }

                // HTML 생성 + 브라우저 열기
                string htmlPath = Path.Combine(
                    Path.GetDirectoryName(Application.ExecutablePath) ?? ".",
                    "formula_view.html");
                GenerateFormulaHtml(dhText, groups, htmlPath);
                try { Process.Start(htmlPath); } catch { }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Formula generation error: " + ex.Message, "Error",
                    MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        // ── EDH 텍스트 계층(DhGroup/체인 분할/IK 매핑/$·Init 스트립)은 DLL 로 이관됨 (2026-08-14) ──
        //   DhGroup = Ojw.C3d.CDhGroup (파일 상단 using 별칭). 아래는 호출 위임 래퍼만 유지.
        //   이유: 앱과 DLL 이 같은 EDH 텍스트를 다르게 해석해 생긴 실사고 재발 방지 —
        //   문법 해석은 렌더 파서(MakeDHSkeleton)와 같은 DLL 클래스 한 곳에만 둔다.

        /// <summary>DH 텍스트를 Init=1 기준으로 그룹 분리 (DLL 위임)</summary>
        private List<DhGroup> SplitDhByInit(string dhText)
        {
            return Ojw.C3d.Edh_SplitByInit(dhText);
        }

        // ========================================
        // 수식번호 자동 매핑 헬퍼 함수
        // ========================================

        /// <summary>기구학 슬롯용: '$' 특수 명령 라인 제거 (DLL 위임)</summary>
        private string StripDollarLines(string text)
        {
            return Ojw.C3d.Edh_StripDollarLines(text);
        }

        /// <summary>개별 체인 DH에서 첫 번째 Init=1을 Init=0으로 변경 (DLL 위임)</summary>
        private string StripInitFlag(string chainDhText)
        {
            return Ojw.C3d.Edh_StripInitFlag(chainDhText);
        }

        /// <summary>3D 렌더링용 DH 텍스트 생성 — 체인별 Type=2,Num 자동 매핑 (DLL 위임)</summary>
        private string BuildFormulaMappedDh(string fullDhText, List<DhGroup> groups)
        {
            return Ojw.C3d.Edh_BuildIkMappedDh(fullDhText, groups);
        }

